import{d as S,C as r,o as A,c as B,j as n,a as e,E as a,a3 as E}from"./chunks/framework.D4-ViStF.js";const O=JSON.parse('{"title":"庄子·大宗师","description":"从真人三论、道之本体到撄宁七阶、坐忘与命也夫，进入庄子论道与论死生的高峰。","frontmatter":{"title":"庄子·大宗师","description":"从真人三论、道之本体到撄宁七阶、坐忘与命也夫，进入庄子论道与论死生的高峰。","category":"guide","aliases":["大宗师","庄子大宗师","zhuangzi chapter 06"],"source":["《庄子》"]},"headers":[],"relativePath":"daoism/zhuang-zi/chapter-06.md","filePath":"daoism/zhuang-zi/chapter-06.md","lastUpdated":1788516578000}'),I={name:"daoism/zhuang-zi/chapter-06.md"},U=S({...I,setup(K){const y=[{id:"tianren_s1",label:"知天之所为……是知之盛也",sentences:[["知天之所为，知人之所为者，",{text:"至矣",glossary:"zhi_yi"},"！"],["知天之所为者，天而生也；"],["知人之所为者，",{text:"以",glossary:"yi_yong"},"其知之所知",{text:"以养",glossary:"yi_yang"},{text:"其知之所不知",glossary:"zhi_suobuzhi"},"，"],[{text:"终",glossary:"zhong_zhongwang"},"其天年而不",{text:"中道",glossary:"zhong_dao"},{text:"夭",glossary:"yao_zaosi"},"者，是知之",{text:"盛也",glossary:"sheng_ye"},"。"]]},{id:"tianren_s2",label:"虽然有患……且有真人而后有真知",sentences:[["虽然，",{text:"有患",glossary:"you_huan"},"：夫",{text:"知有所待而后当",glossary:"zhi_daiding"},"，其所待者",{text:"特未定也",glossary:"te_weidingg"},"。"],[{text:"庸讵",glossary:"yong_ju"},"知吾所谓天之非人乎？所谓人之非天乎？"],["且有",{text:"真人",glossary:"zhen_ren"},"而后有",{text:"真知",glossary:"zhen_zhi"},"。"]]}],_=[{id:"zhi_yi",term:"至矣",pinyin:"zhì yǐ",meaning:"（认识）到达极致了、最高境界了。至：极致、最高；矣：感叹语气词。知天之所为·知人之所为者，至矣：既知天道所为，又知人道所为，这就是认识的极致了。"},{id:"yi_yong",term:"以",pinyin:"yǐ",meaning:"用、凭借。介词。以其知之所知：用（人的）知识所能知道的（部分）。"},{id:"yi_yang",term:"以养",pinyin:"yǐ yǎng",meaning:"来养护、来滋养。以：用来；养：养护、滋养。以其知之所知以养其知之所不知：用知识所能知道的来养护知识所不能知道的（部分）。"},{id:"zhi_suobuzhi",term:"其知之所不知",pinyin:"qí zhī zhī suǒ bù zhī",meaning:"（人的）知识所不能知道的（部分）。知之所不知：知识能力所无法触及的领域。以知之所知养知之所不知：用已知来养护未知——即以有限的认知顺应无限的天道，不强求以知穷尽一切。"},{id:"zhong_zhongwang",term:"终",pinyin:"zhōng",meaning:"终尽、走完。终其天年：走完自然赋予的寿命。"},{id:"zhong_dao",term:"中道",pinyin:"zhōng dào",meaning:"半途、中途。中道夭：在中途夭折。⚠️ 中读 zhōng（中途），非「中道」之道理。"},{id:"yao_zaosi",term:"夭",pinyin:"yāo",meaning:"夭折、早死。不中道夭：不在中途夭折（得以终其天年）。【古今异义】夭：早死，非「夭折」之现代口语义。"},{id:"sheng_ye",term:"盛也",pinyin:"shèng yě",meaning:"（认识的）极盛、最高境界。盛：极盛、最高；也：判断语气词。是知之盛也：这就是认识（智慧）的极盛境界了。"},{id:"you_huan",term:"有患",pinyin:"yǒu huàn",meaning:"有隐患、有问题所在。患：忧患、问题。虽然，有患：虽然如此，（这种认识）仍有隐患。"},{id:"zhi_daiding",term:"知有所待而后当",pinyin:"zhī yǒu suǒ dài ér hòu dāng",meaning:"知识（认识）必须有所依待（凭借）才能恰当（正确）。知：知识、认识；有所待：有所依赖、有所凭借；而后：然后才；当：恰当、正确。"},{id:"te_weidingg",term:"特未定也",pinyin:"tè wèi dìng yě",meaning:"（所依待的对象）偏偏还没有确定。特：偏偏、只是；未定：尚未确定、不稳定；也：语气词。其所待者特未定也：它所依待的对象偏偏是不确定的——知识依赖条件，而条件本身不稳定，故知识不可全信。"},{id:"yong_ju",term:"庸讵",pinyin:"yōng jù",meaning:"哪里能、怎么能。庸：岂、哪里；讵：岂、难道；两字叠用，加强反问语气。庸讵知吾所谓天之非人乎：哪里能知道我所说的「天」不是「人」呢？"},{id:"zhen_ren",term:"真人",pinyin:"zhēn rén",meaning:"真正得道的人。真：真实、真正；人：人。庄子理想人格之一，与「至人」「神人」并列。真人超越天人之辨，不执着于知与不知。"},{id:"zhen_zhi",term:"真知",pinyin:"zhēn zhī",meaning:"真正的知识（智慧）。真：真实、真正；知：知识、智慧。且有真人而后有真知：有了真人才有真知——真知不是依赖条件的认识，而是真人所体悟的道。点明全段核心：知识有其局限（有所待·特未定），唯有真人之真知方能超越。"}],m=[{id:"zhenren_s1",label:"何谓真人……是知之能登假于道者也若此",sentences:[[{text:"何谓真人",glossary:"zhenren_def"},"？古之真人，不逆寡，不雄成，不谟士。"],["若然者，过而弗悔，当而不自得也。"],["若然者，登高不栗，入水不濡，入火不热，是知之能登假于道者也若此。"]]},{id:"zhenren_s2",label:"古之真人其寝不梦……其天机浅",sentences:[["古之真人，其寝不梦，其觉无忧，其食不甘，其息深深。"],["真人之息以踵，众人之息以喉。"],["屈服者，其嗌言若哇。其耆欲深者，其天机浅。"]]},{id:"zhenren_s3",label:"古之真人不知说生……不知恶死",sentences:[["古之真人，不知",{text:"说生",glossary:"shuo_sheng"},"，不知",{text:"恶死",glossary:"wu_si"},"。"],["其出不",{text:"欣",glossary:"xin_huanxi"},"，其入不",{text:"距",glossary:"ju_ju"},"。",{text:"翛然",glossary:"xiao_ran"},"而",{text:"往",glossary:"wang_si"},"，翛然而",{text:"来",glossary:"lai_sheng"},"而已矣。"],["不忘其所",{text:"始",glossary:"shi_laiyuan"},"，不求其所",{text:"终",glossary:"zhong_guisu"},"。"],[{text:"受而喜之",glossary:"shou_er_xi"},"，",{text:"忘而复之",glossary:"wang_er_fu"},"。"],["是之谓",{text:"不以心捐道",glossary:"bu_xin_juan_dao"},"，",{text:"不以人助天",glossary:"bu_ren_zhu_tian"},"，是之谓真人。"]]},{id:"zhenren_s4",label:"若然者其心志……莫知其极",sentences:[["若然者，其心",{text:"志",glossary:"zhi_zhuanyi"},"，其容",{text:"寂",glossary:"ji_anjing"},"，其",{text:"颡",glossary:"sang_e"},{text:"頯",glossary:"kui_kuan"},"。"],[{text:"凄然",glossary:"qi_ran"},"似秋，",{text:"暖然",glossary:"nuan_ran"},"似春，",{text:"喜怒通四时",glossary:"xinu_sishi"},"，",{text:"与物有宜",glossary:"yu_wu_youyi"},"而",{text:"莫知其极",glossary:"mo_zhi_ji"},"。"]]},{id:"zhenren_s5",label:"故圣人之用兵也……非役人也",sentences:[["故圣人之用兵也，",{text:"亡国",glossary:"wang_guo"},"而不失人心。",{text:"利泽",glossary:"li_ze"},{text:"施",glossary:"shi_puji"},"乎万世，不为爱人。"],["故",{text:"乐通物",glossary:"le_tong_wu"},"，非圣人也；有",{text:"亲",glossary:"qin_piaihou"},"，非仁也；",{text:"天时",glossary:"tian_shi_xian"},"，",{text:"非贤也",glossary:"fei_xian_ye"},"；",{text:"利害不通",glossary:"lihai_butong"},"，非君子也；",{text:"行名失己",glossary:"xingming_shiji"},"，",{text:"非士也",glossary:"fei_shi_ye"},"；",{text:"亡身不真",glossary:"wangshen_buzhen"},"，",{text:"非役人也",glossary:"fei_yiren_ye"},"。"]]},{id:"zhenren_s6",label:"若狐不偕务光……而不自适其适者也",sentences:[["若",{text:"狐不偕",glossary:"hu_bu_xie"},"、",{text:"务光",glossary:"wu_guang"},"、",{text:"伯夷",glossary:"bo_yi"},"、",{text:"叔齐",glossary:"shu_qi"},"、",{text:"箕子",glossary:"ji_zi"},"、",{text:"胥余",glossary:"xu_yu"},"、",{text:"纪他",glossary:"ji_tuo"},"、",{text:"申徒狄",glossary:"shentudi"},"，"],["是",{text:"役人之役",glossary:"yiren_zhiyi"},"，",{text:"适人之适",glossary:"shiren_zhishi"},"，而不自适其适者也。"]]}],o=[{id:"zhenren_def",term:"何谓真人",pinyin:"hé wèi zhēn rén",meaning:"什么叫做真人？真人：庄子理想人格，超越生死、顺应天道、不以人为伤天然的得道之人。"},{id:"shuo_sheng",term:"说生",pinyin:"yuè shēng",meaning:"喜悦于生（贪恋生命）。说：通「悦」，喜悦，读 yuè；生：生命。不知说生：不知道贪恋生命——超越对生的执着。"},{id:"wu_si",term:"恶死",pinyin:"wù sǐ",meaning:"厌恶死亡（恐惧死亡）。恶：厌恶，读 wù；死：死亡。不知恶死：不知道厌恶死亡——超越对死的恐惧。不知说生·不知恶死：两句并举，是真人超越生死的核心表述。"},{id:"xin_huanxi",term:"欣",pinyin:"xīn",meaning:"欣喜、高兴。其出不欣：（真人）出生（来到世间）不感到欣喜。"},{id:"ju_ju",term:"距",pinyin:"jù",meaning:"抗拒、拒绝。其入不距：（真人）死去（离开世间）不感到抗拒。出不欣·入不距：生不喜·死不拒，真人对生死的超然态度。"},{id:"xiao_ran",term:"翛然",pinyin:"xiāo rán",meaning:"自由自在、无拘无束的样子。翛：自由飘逸，读 xiāo；然：……的样子。翛然而往·翛然而来：自在地去（死），自在地来（生）——生死皆如自然流动，无所执着。"},{id:"wang_si",term:"往",pinyin:"wǎng",meaning:"去、离去（此处指死亡）。翛然而往：自在地离去（死）。"},{id:"lai_sheng",term:"来",pinyin:"lái",meaning:"来、到来（此处指出生）。翛然而来：自在地到来（生）。往·来：以「往来」喻生死，生死如同自然往来，无需执着。"},{id:"shi_laiyuan",term:"始",pinyin:"shǐ",meaning:"开始、来源（此处指生命的起点·出生）。不忘其所始：不忘记自己的来处（生命的起源）。"},{id:"zhong_guisu",term:"终",pinyin:"zhōng",meaning:"终结、归宿（此处指死亡）。不求其所终：不追求（执着于）自己的归宿（死亡的结果）。不忘所始·不求所终：知来处而不执终点，顺应生死自然流程。"},{id:"shou_er_xi",term:"受而喜之",pinyin:"shòu ér xǐ zhī",meaning:"接受（生命所给予的）而欣然喜之。受：接受、承受；喜之：欣然接受它。受而喜之：得到（生）则欣然接受——顺应自然赋予。"},{id:"wang_er_fu",term:"忘而复之",pinyin:"wàng ér fù zhī",meaning:"忘却（执着）而归还（回归自然）。忘：忘却、放下执着；复：归还、回归；之：代词，指生命。忘而复之：忘却执着而将生命归还自然——死则坦然放下。受而喜之·忘而复之：生则欣然受，死则坦然还，两句合为真人对生死的完整态度。"},{id:"bu_xin_juan_dao",term:"不以心捐道",pinyin:"bù yǐ xīn juān dào",meaning:"不用（主观的）心意去损害道。以：用；心：主观心意、人为意志；捐：损害、背弃；道：自然之道。不以心捐道：不让主观意志凌驾于道之上。"},{id:"bu_ren_zhu_tian",term:"不以人助天",pinyin:"bù yǐ rén zhù tiān",meaning:"不用人为的力量去帮助（干预）天然。人：人为；助：帮助、干预；天：天然、自然。不以人助天：不以人为力量干预自然——顺天而行，无为而治。不以心捐道·不以人助天：两句是《大宗师》核心命题，真人之所以为真人，在于不以人为伤天道。"},{id:"zhi_zhuanyi",term:"志",pinyin:"zhì",meaning:"专一、凝定（心志专一不散）。其心志：他的心志专一凝定。"},{id:"ji_anjing",term:"寂",pinyin:"jì",meaning:"寂静、安静（神情安寂）。其容寂：他的神情安寂沉静。"},{id:"sang_e",term:"颡",pinyin:"sǎng",meaning:"额头。其颡頯：他的额头宽广饱满。"},{id:"kui_kuan",term:"頯",pinyin:"kuí",meaning:"宽广饱满的样子。读 kuí。其颡頯：额头宽广饱满——形容真人气度宏大、从容的外貌特征。"},{id:"qi_ran",term:"凄然",pinyin:"qī rán",meaning:"清凉肃穆的样子。凄：清凉、肃穆；然：……的样子。凄然似秋：清凉肃穆如秋天——非悲凉，而是秋之清肃。"},{id:"nuan_ran",term:"暖然",pinyin:"nuǎn rán",meaning:"温暖和煦的样子。暖然似春：温暖和煦如春天。凄然似秋·暖然似春：真人的气质兼具秋之清肃与春之温暖，随物而化，不偏执一端。"},{id:"xinu_sishi",term:"喜怒通四时",pinyin:"xǐ nù tōng sì shí",meaning:"喜怒（情感）贯通四季（自然变化）。通：贯通、顺应；四时：四季。喜怒通四时：喜怒随四时自然流转，不强压也不放纵——情感顺应自然节律。"},{id:"yu_wu_youyi",term:"与物有宜",pinyin:"yǔ wù yǒu yí",meaning:"与万物相处皆恰当适宜。与：与、和；物：万物；有宜：有所适宜、恰到好处。"},{id:"mo_zhi_ji",term:"莫知其极",pinyin:"mò zhī qí jí",meaning:"没有人知道他的极限（边界）。莫：没有人；知：知道；极：极限、边界。与物有宜而莫知其极：与万物相处皆适宜，却没有人知道他的极限——真人之德广大无边。"},{id:"wang_guo",term:"亡国",pinyin:"wáng guó",meaning:"使国家灭亡（消灭敌国）。亡：使……灭亡；国：国家。亡国而不失人心：消灭（敌）国却不失去（民）心——圣人用兵出于道，非出于私欲。"},{id:"li_ze",term:"利泽",pinyin:"lì zé",meaning:"恩惠利益、恩泽。利：利益；泽：恩泽。"},{id:"shi_puji",term:"施",pinyin:"shī",meaning:"施予、普及。利泽施乎万世：恩泽普及万世——圣人之德泽广被，却非出于刻意爱人。"},{id:"le_tong_wu",term:"乐通物",pinyin:"lè tōng wù",meaning:"以（广泛）施惠万物为乐。乐：以……为乐；通：普及、施惠；物：万物。乐通物，非圣人也：以施惠万物为乐的，不是（真正的）圣人——圣人施惠出于自然，非刻意为乐。"},{id:"qin_piaihou",term:"亲",pinyin:"qīn",meaning:"偏爱、厚此薄彼（有所亲疏）。有亲，非仁也：有所偏爱（亲疏之别），不是（真正的）仁——真仁无亲疏之分。"},{id:"tian_shi_xian",term:"天时",pinyin:"tiān shí",meaning:"（仅凭）顺应天时（行事）。天时：天时、时机。天时，非贤也：仅凭顺应天时（而无内在德性），不是（真正的）贤。"},{id:"fei_xian_ye",term:"非贤也",pinyin:"fēi xián yě",meaning:"不是（真正的）贤者。非：不是；贤：贤者、贤能。"},{id:"lihai_butong",term:"利害不通",pinyin:"lì hài bù tōng",meaning:"不能通达（超越）利害关系。利害：利益与祸害；不通：不能贯通、不能超越。利害不通，非君子也：不能超越利害的，不是（真正的）君子。"},{id:"xingming_shiji",term:"行名失己",pinyin:"xíng míng shī jǐ",meaning:"追求名声而丧失自我。行名：追求、践行名声；失己：失去自我本性。行名失己，非士也：为名声而失去自我的，不是（真正的）士。"},{id:"fei_shi_ye",term:"非士也",pinyin:"fēi shì yě",meaning:"不是（真正的）士（有志之人）。士：有志向、有节操的人。"},{id:"wangshen_buzhen",term:"亡身不真",pinyin:"wáng shēn bù zhēn",meaning:"舍身殉道却不出于真性（不真实）。亡身：舍弃生命；不真：不出于真实本性，非真正的道。亡身不真，非役人也：舍身却不出于真性的，不是（真正的）为道而牺牲的人。"},{id:"fei_yiren_ye",term:"非役人也",pinyin:"fēi yì rén yě",meaning:"不是（真正的）为道而尽力的人。役人：为道义而尽力、牺牲的人；非役人：不是真正的役人。"},{id:"hu_bu_xie",term:"狐不偕",pinyin:"hú bù xié",meaning:"人名，传说中尧时的贤人，因不愿受禅让而投水自尽。"},{id:"wu_guang",term:"务光",pinyin:"wù guāng",meaning:"人名，商汤时的贤人，汤欲让位于他，他不受，投水而死。"},{id:"bo_yi",term:"伯夷",pinyin:"bó yī",meaning:"人名，商末孤竹君之长子，与叔齐一同耻食周粟，饿死首阳山。以「守节」著称。"},{id:"shu_qi",term:"叔齐",pinyin:"shū qí",meaning:"人名，伯夷之弟，与伯夷同饿死首阳山。二人并称「伯夷叔齐」，为儒家节义的典范。"},{id:"ji_zi",term:"箕子",pinyin:"jī zǐ",meaning:"人名，商纣王的叔父，因谏纣不听，装疯为奴。以「忠谏」著称。"},{id:"xu_yu",term:"胥余",pinyin:"xū yú",meaning:"人名，即比干，商纣王的叔父，因强谏被纣王剖心而死。一说「胥余」为比干之字。"},{id:"ji_tuo",term:"纪他",pinyin:"jì tuō",meaning:"人名，传说中的隐士，汤让位于他，他不受，率弟子隐居。读 jì tuō。"},{id:"shentudi",term:"申徒狄",pinyin:"shēn tú dí",meaning:"人名，传说中的隐士，因世道不合而负石投河自尽。"},{id:"yiren_zhiyi",term:"役人之役",pinyin:"yì rén zhī yì",meaning:"为（外在）役使而役使自身。役人：被外物（名义、节操）所役使的人；之役：的役使方式。役人之役：以外在名义役使自身——非出于真性，而是被外在标准所驱使。"},{id:"shiren_zhishi",term:"适人之适",pinyin:"shì rén zhī shì",meaning:"顺应（外在）他人认为合适的（标准）去适应。适人：顺应他人（外在标准）；之适：的适应方式。适人之适，而不自适其适：顺应别人的标准去适应，却不能顺应自己内心真正的适然——是庄子批评八人的核心：他们殉道殉名，皆出于外在标准，非自适其适。"}],l=[{id:"zhuang_s1",label:"古之真人其状义而不朋……悗乎忘其言也",sentences:[["古之真人，其",{text:"状义而不朋",glossary:"zhuang_yi_bupeng"},"，",{text:"若不足",glossary:"ruo_buzu"},"而",{text:"不承",glossary:"bu_cheng"},"；"],["与乎其",{text:"觚而不坚也",glossary:"gu_er_bujian"},"，",{text:"张乎",glossary:"zhang_hu"},"其",{text:"虚",glossary:"xu_kongxu"},"而",{text:"不华也",glossary:"bu_hua"},"；"],[{text:"邴邴乎",glossary:"bing_bing_hu"},"其似喜也，",{text:"崔崔乎",glossary:"cui_cui_hu"},"其不得已也，"],[{text:"滀乎",glossary:"chu_hu"},{text:"进我色也",glossary:"jin_wo_se"},"，",{text:"与乎",glossary:"yu_hu"},{text:"止我德也",glossary:"zhi_wo_de"},"，"],[{text:"广乎",glossary:"guang_hu"},{text:"其似世也",glossary:"si_shi_ye"},"，",{text:"謷乎",glossary:"ao_hu_zhuang"},{text:"其未可制也",glossary:"wei_ke_zhi"},"，"],[{text:"连乎",glossary:"lian_hu"},{text:"其似好闭也",glossary:"si_hao_bi"},"，",{text:"悗乎",glossary:"man_hu"},{text:"忘其言也",glossary:"wang_qi_yan"},"。"]]},{id:"zhuang_s2",label:"以刑为体……而人真以为勤行者也",sentences:[["以刑为体，以",{text:"礼为翼",glossary:"li_wei_yi"},"，以",{text:"知为时",glossary:"zhi_wei_shi"},"，以",{text:"德为循",glossary:"de_wei_xun"},"。"],[{text:"以刑为体者",glossary:"xing_wei_ti"},"，",{text:"绰乎其杀也",glossary:"chuo_sha"},"；"],[{text:"以礼为翼者",glossary:"li_wei_yi_zhe"},"，",{text:"所以行于世也",glossary:"xing_yu_shi"},"；"],[{text:"以知为时者",glossary:"zhi_wei_shi_zhe"},"，",{text:"不得已于事也",glossary:"budyi_shi"},"；"],[{text:"以德为循者",glossary:"de_wei_xun_zhe"},"，言其",{text:"与有足者",glossary:"yu_youzuzhe"},{text:"至于丘也",glossary:"zhi_yu_qiu"},"，而人真以为",{text:"勤行者也",glossary:"qin_xing_zhe"},"。"]]},{id:"zhuang_s3",label:"故其好之也一……是之谓真人",sentences:[["故其",{text:"好之也一",glossary:"hao_zhi_yi"},"，其",{text:"弗",glossary:"fu_bu"},"好之也一。"],[{text:"其一也一",glossary:"qi_yi_ye_yi"},"，",{text:"其不一也一",glossary:"qi_buyi_ye_yi"},"。"],["其一与天为",{text:"徒",glossary:"tu_tong_lei"},"，其不一与人为徒，",{text:"天与人不相胜也",glossary:"tian_ren_bu_sheng"},"，是之谓真人。"]]}],d=[{id:"zhuang_yi_bupeng",term:"状义而不朋",pinyin:"zhuàng yì ér bù péng",meaning:"外貌端正威仪而不结党营私。状：外貌、仪态；义：端正、合宜；不朋：不结朋党、不拉帮结派。"},{id:"ruo_buzu",term:"若不足",pinyin:"ruò bù zú",meaning:"好像有所不足（谦逊的样子）。若：好像；不足：不充足、欠缺。"},{id:"bu_cheng",term:"不承",pinyin:"bù chéng",meaning:"却不（向人）承接（讨好、迎合）。承：承接、迎合、奉承。若不足而不承：看似谦逊不足，却不去迎合奉承他人——外谦而内不卑。"},{id:"gu_er_bujian",term:"觚而不坚也",pinyin:"gū ér bù jiān yě",meaning:"有棱角而不固执生硬。觚：有棱角，读 gū；不坚：不固执、不僵硬。与乎其觚而不坚：和顺中带有棱角，却不固执己见。"},{id:"zhang_hu",term:"张乎",pinyin:"zhāng hū",meaning:"舒展开来的样子。张：舒展、开放；乎：语气词，表状态。"},{id:"xu_kongxu",term:"虚",pinyin:"xū",meaning:"虚空、空旷（内心虚静）。张乎其虚：舒展开来显得虚空旷达。"},{id:"bu_hua",term:"不华也",pinyin:"bù huá yě",meaning:"却不浮华（不炫耀）。华：浮华、炫耀。张乎其虚而不华：舒展虚旷却不浮华——开阔而不张扬。"},{id:"bing_bing_hu",term:"邴邴乎",pinyin:"bǐng bǐng hū",meaning:"喜悦振奋的样子。邴邴：喜悦、振奋，读 bǐng；乎：语气词。邴邴乎其似喜也：喜悦振奋，好像很高兴的样子。"},{id:"cui_cui_hu",term:"崔崔乎",pinyin:"cuī cuī hū",meaning:"高峻不得不然的样子。崔崔：高峻、不得已，读 cuī；乎：语气词。崔崔乎其不得已也：高峻巍然，好像一切都是不得已而为之——非强求，顺势而动。"},{id:"chu_hu",term:"滀乎",pinyin:"chù hū",meaning:"蓄积充盈的样子。滀：水蓄积，读 chù；乎：语气词。"},{id:"jin_wo_se",term:"进我色也",pinyin:"jìn wǒ sè yě",meaning:"（充盈地）向我展现（他的）神色。进：呈现、展现；我：我（观者）；色：神色、气色。滀乎进我色也：蓄积充盈地向我呈现他的神色——德充于内而自然流露。"},{id:"yu_hu",term:"与乎",pinyin:"yǔ hū",meaning:"宽和从容的样子。与：宽和、随顺；乎：语气词。"},{id:"zhi_wo_de",term:"止我德也",pinyin:"zhǐ wǒ dé yě",meaning:"（宽和地）使我的德性安定止息。止：使……安止、安定；我德：我（观者）的德性。与乎止我德也：宽和从容地使我的德性得以安定——真人之德感化他人，令人心安。"},{id:"guang_hu",term:"广乎",pinyin:"guǎng hū",meaning:"广大宏阔的样子。广：广大；乎：语气词。"},{id:"si_shi_ye",term:"其似世也",pinyin:"qí sì shì yě",meaning:"好像容纳了整个世界（一样广大）。似：好像；世：世界、天下。广乎其似世也：广大宏阔，好像包容了整个世界。"},{id:"ao_hu_zhuang",term:"謷乎",pinyin:"áo hū",meaning:"高远卓绝的样子。謷：高大、卓绝，读 áo；乎：语气词。"},{id:"wei_ke_zhi",term:"其未可制也",pinyin:"qí wèi kě zhì yě",meaning:"（高远得）无法被约束（制约）。未可：无法、不能；制：制约、约束。謷乎其未可制也：高远卓绝，无法被外力约束——真人超越一切外在制约。"},{id:"lian_hu",term:"连乎",pinyin:"lián hū",meaning:"连绵内敛的样子。连：连绵、内聚；乎：语气词。"},{id:"si_hao_bi",term:"其似好闭也",pinyin:"qí sì hào bì yě",meaning:"好像喜欢封闭自守（不轻易外露）。似：好像；好闭：喜欢关闭、内敛自守，读 hào bì。连乎其似好闭也：连绵内敛，好像喜欢封闭自守——非孤僻，而是内守不散。"},{id:"man_hu",term:"悗乎",pinyin:"mán hū",meaning:"恍惚忘言的样子。悗：恍惚、忘怀，读 mán；乎：语气词。"},{id:"wang_qi_yan",term:"忘其言也",pinyin:"wàng qí yán yě",meaning:"（恍惚地）忘记了言语（不执着于言辞）。忘其言：忘却言语、不拘于言辞。悗乎忘其言也：恍惚忘怀，连言语都忘了——真人不以言语为念，得意忘言。"},{id:"li_wei_yi",term:"礼为翼",pinyin:"lǐ wéi yì",meaning:"以礼义为羽翼（辅助）。礼：礼义、礼制；翼：羽翼、辅翼。以礼为翼：用礼义作为辅助翅膀——礼是工具，非目的。"},{id:"zhi_wei_shi",term:"知为时",pinyin:"zhì wéi shí",meaning:"以智慧（顺应）时机。知：智慧，读 zhì；时：时机、时宜。以知为时：用智慧顺应时机——智慧是把握时机的工具。"},{id:"de_wei_xun",term:"德为循",pinyin:"dé wéi xún",meaning:"以德性为遵循（依循的准则）。德：德性；循：遵循、依循。以德为循：以德性作为行事的依循——德是内在准则。"},{id:"xing_wei_ti",term:"以刑为体者",pinyin:"yǐ xíng wéi tǐ zhě",meaning:"以刑（法）为本体的（真人）。刑：通「形」，或指刑法、规范；为体：作为本体、根本。以刑为体者，绰乎其杀也：以法度为本体，宽裕地运用刑杀——刑非严苛，而是宽绰自然。⚠️ 此处「刑」历来有争议：一说「刑」通「形」（形体）；一说指「刑法」；从上下文「绰乎其杀」看，当指法度刑制。"},{id:"chuo_sha",term:"绰乎其杀也",pinyin:"chuò hū qí shā yě",meaning:"宽裕从容地（运用）刑杀。绰：宽裕、从容，读 chuò；杀：刑杀、裁减。以刑为体者，绰乎其杀也：以法度为本体，运用刑杀时宽裕从容——非滥杀，而是顺道而裁。"},{id:"li_wei_yi_zhe",term:"以礼为翼者",pinyin:"yǐ lǐ wéi yì zhě",meaning:"以礼义为羽翼的（真人）。"},{id:"xing_yu_shi",term:"所以行于世也",pinyin:"suǒ yǐ xíng yú shì yě",meaning:"（礼是）用来在世间行事（周旋）的。所以：用来……的；行于世：在世间行走、处世。以礼为翼者，所以行于世也：以礼为羽翼，是为了在世间顺利行事——礼是处世的工具，非束缚。"},{id:"zhi_wei_shi_zhe",term:"以知为时者",pinyin:"yǐ zhì wéi shí zhě",meaning:"以智慧顺应时机的（真人）。"},{id:"budyi_shi",term:"不得已于事也",pinyin:"bù dé yǐ yú shì yě",meaning:"（用智慧）是迫不得已应对事务（而非主动谋算）。不得已：迫不得已、顺势而为；于事：在事务上。以知为时者，不得已于事也：以智慧顺时，是迫不得已应对事务——非主动谋划，而是顺势而动。"},{id:"de_wei_xun_zhe",term:"以德为循者",pinyin:"yǐ dé wéi xún zhě",meaning:"以德性为遵循的（真人）。"},{id:"yu_youzuzhe",term:"与有足者",pinyin:"yǔ yǒu zú zhě",meaning:"与有脚（能行走）的人一起。有足者：有脚的人，喻有能力、有条件的人。"},{id:"zhi_yu_qiu",term:"至于丘也",pinyin:"zhì yú qiū yě",meaning:"（一同）走到山丘（目的地）。至：到达；丘：山丘，喻目标、终点。以德为循者，言其与有足者至于丘也：以德为依循，是说他与有能力的人一同到达目标——德是自然引导，非强迫。"},{id:"qin_xing_zhe",term:"勤行者也",pinyin:"qín xíng zhě yě",meaning:"勤勉努力行事的人。勤行：勤勉地行走、努力实践。而人真以为勤行者也：而世人真的以为他是勤勉努力的人——实则真人以德自然引导，非刻意勤行，世人误以为勤。"},{id:"hao_zhi_yi",term:"好之也一",pinyin:"hào zhī yě yī",meaning:"喜好（某事）是同一（道）。好：喜好，读 hào；一：同一、统一于道。其好之也一：他喜好某事，（归根结底）是同一（道）。"},{id:"fu_bu",term:"弗",pinyin:"fú",meaning:"不、没有。弗好之也一：不喜好（某事），也是同一（道）。弗：古汉语否定副词，与「不」同义，语气稍强。"},{id:"qi_yi_ye_yi",term:"其一也一",pinyin:"qí yī yě yī",meaning:"（万物）统一（于道）也是同一（道）。其一：（万物）归一、统一；也一：也是同一（道）。"},{id:"qi_buyi_ye_yi",term:"其不一也一",pinyin:"qí bù yī yě yī",meaning:"（万物）不统一（于道）也是同一（道）。其不一：（万物）不归一、有差异；也一：也是同一（道）。其一也一·其不一也一：无论统一还是不统一，都归于同一个道——「齐物」思想的体现，超越一与多的对立。"},{id:"tu_tong_lei",term:"徒",pinyin:"tú",meaning:"同类、同道（之人）。与天为徒：与天道同类；与人为徒：与人道同类。"},{id:"tian_ren_bu_sheng",term:"天与人不相胜也",pinyin:"tiān yǔ rén bù xiāng shèng yě",meaning:"天道与人道互不相胜（不相压制、不相对立）。天：天道、自然；人：人道、人为；不相胜：互不压倒对方、不相对立。天与人不相胜也，是之谓真人：天道与人道互不相胜，这就叫做真人——真人融合天人，超越天人对立，是《大宗师》天人关系的终极命题。"}],u=[{id:"sisheng_s1",label:"死生命也……皆物之情也",sentences:[["死生，命也；其有",{text:"夜旦之常",glossary:"ye_dan_chang"},"，天也。"],["人之有所",{text:"不得与",glossary:"bu_de_yu"},"，皆",{text:"物之情也",glossary:"wu_zhi_qing"},"。"]]},{id:"sisheng_s2",label:"彼特以天为父……而况其真乎",sentences:[[{text:"彼",glossary:"bi_ren"},{text:"特",glossary:"te_zhi"},"以天为父，而身",{text:"犹爱之",glossary:"you_ai_zhi"},"，而况其",{text:"卓",glossary:"zhuo_chaoyue"},"乎！"],["人",{text:"特",glossary:"te_zhi"},"以有君为",{text:"愈乎己",glossary:"yu_hu_ji"},"，而身犹死之，而况其",{text:"真乎",glossary:"zhen_hu"},"！"]]},{id:"sisheng_s3",label:"泉涸鱼相与处于陆……不如相忘于江湖",sentences:[["泉",{text:"涸",glossary:"he_ganjie"},"，鱼相与处于陆，",{text:"相呴以湿",glossary:"xiang_xu_shi"},"，",{text:"相濡以沫",glossary:"xiang_ru_mo"},"，不如",{text:"相忘于江湖",glossary:"xiang_wang_jianghu"},"。"]]},{id:"sisheng_s4",label:"与其誉尧而非桀也……不如两忘而化其道",sentences:[["与其",{text:"誉",glossary:"yu_chengzan"},{text:"尧",glossary:"yao_shengwang"},"而",{text:"非",glossary:"fei_feidui"},{text:"桀",glossary:"jie_baojun"},"也，不如",{text:"两忘",glossary:"liang_wang"},"而",{text:"化其道",glossary:"hua_qi_dao"},"。"]]}],h=[{id:"ye_dan_chang",term:"夜旦之常",pinyin:"yè dàn zhī cháng",meaning:"昼夜交替的常规（自然规律）。夜：夜晚；旦：白昼；常：常规、规律。其有夜旦之常，天也：（死生）有如昼夜交替的常规，是天道（自然）使然。"},{id:"bu_de_yu",term:"不得与",pinyin:"bù dé yù",meaning:"不能参与（干预、改变）。不得：不能；与：参与、干预。人之有所不得与：人有所不能参与（干预）的——死生昼夜，人力无法左右。"},{id:"wu_zhi_qing",term:"物之情也",pinyin:"wù zhī qíng yě",meaning:"万物的实情（自然本性）。物：万物；情：实情、本性；也：判断语气词。皆物之情也：都是万物自然本性（的规律）——死生是自然，非人力可改。"},{id:"bi_ren",term:"彼",pinyin:"bǐ",meaning:"他（们）、那些人。指示代词，泛指世人。"},{id:"te_zhi",term:"特",pinyin:"tè",meaning:"只是、仅仅。副词，表限定。彼特以天为父：他们只是把天当作父亲。"},{id:"you_ai_zhi",term:"犹爱之",pinyin:"yóu ài zhī",meaning:"尚且（深深地）爱它（天）。犹：尚且、还；爱之：爱它。而身犹爱之：自身尚且深深爱戴天（父），而况其卓乎——以「爱天父」衬托「况其卓（道）」。"},{id:"zhuo_chaoyue",term:"卓",pinyin:"zhuó",meaning:"卓绝超越（天之上）的（道）。卓：卓绝、超越。而况其卓乎：何况那超越天（父）之上的（道）呢！——天尚且被爱，道更应被尊。"},{id:"yu_hu_ji",term:"愈乎己",pinyin:"yù hū jǐ",meaning:"胜过自己（比自己更重要）。愈：胜过、超过；乎：于、比；己：自己。人特以有君为愈乎己：人们只是把君主看作比自己更重要的（存在）。"},{id:"zhen_hu",term:"真乎",pinyin:"zhēn hū",meaning:"真正（超越君主）的（道）。真：真实、真正（指真道、真宰）。而况其真乎：何况那真正（超越君主）的（道）呢！——君主尚且被人以死相殉，道更应被尊崇。彼特以天为父·人特以有君为愈乎己：两句对举，以「爱天·殉君」衬托「况其卓·况其真」，层层递进，说明道超越天与君。"},{id:"he_ganjie",term:"涸",pinyin:"hé",meaning:"（水）干涸、枯竭。泉涸：泉水干涸。"},{id:"xiang_xu_shi",term:"相呴以湿",pinyin:"xiāng xǔ yǐ shī",meaning:"互相用湿气（呼出的气）滋润对方。相：互相；呴：吐气、呼气，读 xǔ；以湿：用湿气。"},{id:"xiang_ru_mo",term:"相濡以沫",pinyin:"xiāng rú yǐ mò",meaning:"互相用唾沫（泡沫）润湿对方。相：互相；濡：润湿、沾湿；沫：唾沫、泡沫。相呴以湿·相濡以沫：两句并举，描绘鱼在陆地上困境中互相救助的情景——看似感人，实则是困境所迫，非自然之道。"},{id:"xiang_wang_jianghu",term:"相忘于江湖",pinyin:"xiāng wàng yú jiāng hú",meaning:"（各自）在江湖中相互忘却（自由自在）。相忘：互相忘却、各自忘怀；江湖：江河湖海（自然广阔之境）。不如相忘于江湖：不如各自在江湖中自由自在地相互忘却——回归自然本性，无需刻意相濡。相濡以沫·相忘于江湖：庄子最著名的意象对比，前者是困境中的人为相助，后者是自然中的自在忘怀。后世「相忘于江湖」成为超然处世的经典意象。"},{id:"yu_chengzan",term:"誉",pinyin:"yù",meaning:"称誉、赞美。誉尧：称赞尧（圣王）。"},{id:"yao_shengwang",term:"尧",pinyin:"yáo",meaning:"传说中的上古圣王，儒家推崇的仁政典范。此处代表「善」「圣」的一端。"},{id:"fei_feidui",term:"非",pinyin:"fēi",meaning:"非议、批评。非桀：批评桀（暴君）。"},{id:"jie_baojun",term:"桀",pinyin:"jié",meaning:"传说中的夏朝末代暴君，儒家批判的暴政典范。此处代表「恶」「暴」的一端。誉尧而非桀：称赞尧而批评桀——执着于善恶是非的对立判断。"},{id:"liang_wang",term:"两忘",pinyin:"liǎng wàng",meaning:"两者都忘却（超越善恶两端）。两：两者（尧与桀·善与恶）；忘：忘却、超越。不如两忘：不如将两者（尧·桀）都忘却——超越善恶是非的对立。"},{id:"hua_qi_dao",term:"化其道",pinyin:"huà qí dào",meaning:"融化（消融）于道之中。化：融化、消融、化入；其道：那个道（自然之道）。两忘而化其道：将两者都忘却，融化于道之中——超越是非对立，归于自然大道。与其誉尧非桀·不如两忘化其道：呼应「相濡以沫·不如相忘于江湖」——前者是鱼的比喻，后者是人事的比喻，两者皆指向同一道理：超越执着，归于自然。"}],p=[{id:"dakuai_s1",label:"夫大块载我以形……乃所以善吾死也",sentences:[["夫",{text:"大块",glossary:"da_kuai"},{text:"载我以形",glossary:"zai_wo_xing"},"，",{text:"劳我以生",glossary:"lao_wo_sheng"},"，",{text:"佚我以老",glossary:"yi_wo_lao"},"，",{text:"息我以死",glossary:"xi_wo_si"},"。"],["故善吾生者，乃所以善吾死也。"]]},{id:"dakuai_s2",label:"夫藏舟于壑……昧者不知也",sentences:[["夫",{text:"藏舟于壑",glossary:"cang_zhou_he"},"，",{text:"藏山于泽",glossary:"cang_shan_ze"},"，",{text:"谓之固矣",glossary:"wei_zhi_gu"},"！"],["然而夜半",{text:"有力者",glossary:"you_li_zhe"},{text:"负之而走",glossary:"fu_zhi_zou"},"，",{text:"昧者",glossary:"mei_zhe"},"不知也。"]]},{id:"dakuai_s3",label:"藏小大有宜……是恒物之大情也",sentences:[[{text:"藏小大有宜",glossary:"cang_xiao_da_yi"},"，",{text:"犹有所循",glossary:"you_suo_xun"},"。"],["若夫藏天下于天下而不得所循，是",{text:"恒物之大情也",glossary:"heng_wu_daqing"},"。"]]},{id:"dakuai_s4",label:"特犯人之形……其为乐可胜计邪",sentences:[[{text:"特",glossary:"te_jin"},{text:"犯人之形",glossary:"fan_ren_xing"},"而犹喜之。"],["若人之形者，",{text:"万化",glossary:"wan_hua"},"而",{text:"未始有极也",glossary:"wei_shi_youji"},"，其为",{text:"乐可胜计邪",glossary:"le_sheng_ji"},"？"]]},{id:"dakuai_s5",label:"故圣人将游于物之所不得循而皆存……而况万物之所系而一化之所待乎",sentences:[["故圣人",{text:"将",glossary:"jiang_jiang"},{text:"游",glossary:"you_xiaoyao"},"于物之所不得循而",{text:"皆存",glossary:"jie_cun"},"。"],[{text:"善妖善老",glossary:"shan_yao_lao"},"，",{text:"善始善终",glossary:"shan_shi_zhong"},"，",{text:"人犹效之",glossary:"ren_xiao_zhi"},"，而况",{text:"万物之所系",glossary:"wanwu_suo_xi"},"而",{text:"一化之所待",glossary:"yi_hua_suo_dai"},"乎！"]]}],x=[{id:"da_kuai",term:"大块",pinyin:"dà kuài",meaning:"大地、自然造化的总体。大块：天地自然的整体，庄子对自然造化的称呼。大块载我以形：大地（自然）以形体承载我。"},{id:"zai_wo_xing",term:"载我以形",pinyin:"zài wǒ yǐ xíng",meaning:"以形体承载我（赋予我形体）。载：承载、赋予；以形：用形体。大块载我以形：自然以形体承载我——形体是自然的赋予。"},{id:"lao_wo_sheng",term:"劳我以生",pinyin:"láo wǒ yǐ shēng",meaning:"以生命使我劳作（赋予我生命让我劳动）。劳：使……劳作；以生：用生命。"},{id:"yi_wo_lao",term:"佚我以老",pinyin:"yì wǒ yǐ lǎo",meaning:"以衰老使我安逸（赋予我老年让我休息）。佚：安逸、休息；以老：用衰老。"},{id:"xi_wo_si",term:"息我以死",pinyin:"xī wǒ yǐ sǐ",meaning:"以死亡使我安息（赋予我死亡让我长眠）。息：安息、休息；以死：用死亡。载我以形·劳我以生·佚我以老·息我以死：四句并举，以「大块」为主语，形·生·老·死皆是自然赋予，层层递进，点明死是生命的自然归宿，非可惧之事。"},{id:"cang_zhou_he",term:"藏舟于壑",pinyin:"cáng zhōu yú hè",meaning:"把船藏在山谷（深壑）中。藏：藏匿、收藏；舟：船；壑：山谷、深沟，读 hè。"},{id:"cang_shan_ze",term:"藏山于泽",pinyin:"cáng shān yú zé",meaning:"把山藏在湖泽之中。山：山岳；泽：湖泽、沼泽。藏舟于壑·藏山于泽：两句并举，以「藏大物于大处」为喻，看似牢固，实则仍有被取走的可能。"},{id:"wei_zhi_gu",term:"谓之固矣",pinyin:"wèi zhī gù yǐ",meaning:"（人们）称之为牢固了。谓：称、说；固：牢固、稳妥；矣：语气词，表确定。"},{id:"you_li_zhe",term:"有力者",pinyin:"yǒu lì zhě",meaning:"有力量的人（喻自然造化之力）。有力者：力大无穷者，此处喻自然造化。"},{id:"fu_zhi_zou",term:"负之而走",pinyin:"fù zhī ér zǒu",meaning:"背着它（连同藏物一起）跑走了。负：背负、扛；之：代词，指藏物（舟·山）连同所藏之处；走：跑走。夜半有力者负之而走：半夜有力量的人（自然造化）背着它跑走了——喻万物随自然变化而迁移，无法真正固定。"},{id:"mei_zhe",term:"昧者",pinyin:"mèi zhě",meaning:"昏昧不知的人（执着于固定之人）。昧：昏昧、不明；者：的人。昧者不知也：昏昧的人（执着于藏匿之法的人）不知道（万物已随化而去）。"},{id:"cang_xiao_da_yi",term:"藏小大有宜",pinyin:"cáng xiǎo dà yǒu yí",meaning:"把小东西藏在大处是合适的（有其道理）。藏小大：把小的藏在大的（地方）；有宜：有其适宜之处。"},{id:"you_suo_xun",term:"犹有所循",pinyin:"yóu yǒu suǒ xún",meaning:"尚且有可以依循（遵循）的（规律）。犹：尚且；有所循：有所依循、有规律可循。藏小大有宜，犹有所循：把小的藏在大处虽有其道理，但尚且有可依循的规律（仍可被找到）。"},{id:"heng_wu_daqing",term:"恒物之大情也",pinyin:"héng wù zhī dà qíng yě",meaning:"万物永恒的大实情（根本规律）。恒：永恒、常久；物：万物；大情：最根本的实情、规律；也：判断语气词。藏天下于天下而不得所循，是恒物之大情也：把天下藏于天下之中而无从寻找，这是万物永恒的根本规律——万物归于天下（自然），无处可循，无从把握，是最大的真实。"},{id:"te_jin",term:"特",pinyin:"tè",meaning:"只是、仅仅（偶然）。副词，表限定或偶然。特犯人之形：只是偶然获得了人的形体。"},{id:"fan_ren_xing",term:"犯人之形",pinyin:"fàn rén zhī xíng",meaning:"偶然获得（进入）人的形体。犯：进入、获得（偶然遭遇）；人之形：人的形体。特犯人之形而犹喜之：只是偶然获得了人的形体，（人们）尚且为此高兴——何况万化无极之乐！"},{id:"wan_hua",term:"万化",pinyin:"wàn huà",meaning:"千变万化（经历无数次变化）。万：极多；化：变化、转化。若人之形者，万化而未始有极：像人这样的形体，经历无数次变化而从未有过穷尽。"},{id:"wei_shi_youji",term:"未始有极也",pinyin:"wèi shǐ yǒu jí yě",meaning:"从未有过穷尽（极限）。未始：从未、从来没有；有极：有穷尽、有极限；也：语气词。"},{id:"le_sheng_ji",term:"乐可胜计邪",pinyin:"lè kě shèng jì yé",meaning:"（这种）快乐能够计算（穷尽）吗？乐：快乐；可胜计：能够数得完、计算得尽；邪：疑问语气词，读 yé。其为乐可胜计邪：（万化无极所带来的）快乐，哪里能计算得尽！"},{id:"jiang_jiang",term:"将",pinyin:"jiāng",meaning:"将要、打算。副词，表将来或意向。故圣人将游于物之所不得循：所以圣人将（自在地）游于万物无从依循之处。"},{id:"you_xiaoyao",term:"游",pinyin:"yóu",meaning:"逍遥游历、自在遨游。游：自在遨游，庄子核心意象。游于物之所不得循：游于万物无从依循（把握）之处——即游于道，超越一切固定规律。"},{id:"jie_cun",term:"皆存",pinyin:"jiē cún",meaning:"（万物）皆得以保全存在。皆：都、全；存：存在、保全。游于物之所不得循而皆存：游于无从依循之处，而万物皆得以保全——顺道而游，万物自存。"},{id:"shan_yao_lao",term:"善妖善老",pinyin:"shàn yāo shàn lǎo",meaning:"善待（顺应）夭折，善待（顺应）衰老。善：善待、顺应；妖：通「夭」，夭折、早死，读 yāo；老：衰老。善妖善老：顺应早死与衰老——不以夭为悲，不以老为苦。"},{id:"shan_shi_zhong",term:"善始善终",pinyin:"shàn shǐ shàn zhōng",meaning:"善待（顺应）开始，善待（顺应）终结。善始：顺应生命的开始；善终：顺应生命的终结。善妖善老·善始善终：四「善」并举，真人对生命各阶段皆顺应自然，无所执着。"},{id:"ren_xiao_zhi",term:"人犹效之",pinyin:"rén yóu xiào zhī",meaning:"人们尚且效法他（圣人）。犹：尚且；效：效法、学习；之：代词，指圣人。"},{id:"wanwu_suo_xi",term:"万物之所系",pinyin:"wàn wù zhī suǒ xì",meaning:"万物所依系（依附）的（道）。所系：所依附、所依托。万物之所系：万物所依托的根本（道）。"},{id:"yi_hua_suo_dai",term:"一化之所待",pinyin:"yī huà zhī suǒ dài",meaning:"一切变化所依待（等待、凭借）的（道）。一化：一切变化、所有变化；所待：所依待、所凭借。万物之所系而一化之所待：万物所依托、一切变化所凭借的（道）——指道是万物与变化的根本依据。人犹效之，而况万物之所系而一化之所待乎：人尚且效法圣人，何况那万物所依托、一切变化所凭借的道呢！——以「况」字层层递进，收束全段。"}],z=[{id:"dao_s1",label:"夫道有情有信……自古以固存",sentences:[["夫道有情有信，无为无形；可传而不可",{text:"受",glossary:"shou_lingwu"},"，可得而不可见；"],["自本自根，未有天地，自古以",{text:"固存",glossary:"gu_cun"},"；"]]},{id:"dao_s2",label:"神鬼神帝……长于上古而不为老",sentences:[["神鬼神帝，生天生地；"],["在",{text:"太极",glossary:"tai_ji"},"之先而不为",{text:"高",glossary:"gao_wei_gao"},"，在",{text:"六极",glossary:"liu_ji"},"之下而不为",{text:"深",glossary:"shen_wei_shen"},"，先天地生而不为",{text:"久",glossary:"jiu_wei_jiu"},"，长于上古而不为",{text:"老",glossary:"lao_wei_lao"},"。"]]},{id:"dao_s3",label:"豨韦氏得之……终古不息",sentences:[[{text:"豨韦氏",glossary:"xi_wei_shi"},"得之，以",{text:"挈天地",glossary:"qie_tiandi"},"；"],[{text:"伏戏氏",glossary:"fu_xi_shi"},"得之，以",{text:"袭气母",glossary:"xi_qi_mu"},"；"],[{text:"维斗",glossary:"wei_dou"},"得之，",{text:"终古不忒",glossary:"zhong_gu_bute"},"；"],["日月得之，终古不",{text:"息",glossary:"xi_tingxi"},"；"]]},{id:"dao_s4",label:"勘坏得之……以处大山",sentences:[[{text:"勘坏",glossary:"kan_huai"},"得之，以",{text:"袭昆仑",glossary:"xi_kunlun"},"；"],[{text:"冯夷",glossary:"feng_yi"},"得之，以游大川；"],[{text:"肩吾",glossary:"jian_wu"},"得之，以",{text:"处大山",glossary:"chu_dashan"},"；"]]},{id:"dao_s5",label:"黄帝得之……以处玄宫",sentences:[[{text:"黄帝",glossary:"huang_di"},"得之，以",{text:"登云天",glossary:"deng_yuntian"},"；"],[{text:"颛顼",glossary:"zhuan_xu"},"得之，以",{text:"处玄宫",glossary:"chu_xuangong"},"；"]]},{id:"dao_s6",label:"禺强得之……莫知其终",sentences:[[{text:"禺强",glossary:"yu_qiang"},"得之，",{text:"立乎北极",glossary:"li_beiji"},"；"],[{text:"西王母",glossary:"xi_wang_mu"},"得之，",{text:"坐乎少广",glossary:"zuo_shaoguang"},"，",{text:"莫知其始",glossary:"mo_zhi_shi"},"，",{text:"莫知其终",glossary:"mo_zhi_zhong"},"；"]]},{id:"dao_s7",label:"彭祖得之……下及五伯",sentences:[[{text:"彭祖",glossary:"peng_zu"},"得之，",{text:"上及有虞",glossary:"shang_ji_youyu"},"，",{text:"下及五伯",glossary:"xia_ji_wuba"},"；"]]},{id:"dao_s8",label:"傅说得之……比于列星",sentences:[[{text:"傅说",glossary:"fu_yue"},"得之，以",{text:"相武丁",glossary:"xiang_wuding"},"，",{text:"奄有天下",glossary:"yan_you_tianxia"},"，",{text:"乘东维",glossary:"cheng_dongwei"},"、",{text:"骑箕尾",glossary:"qi_jiwei"},"而",{text:"比于列星",glossary:"bi_lixing"},"。"]]}],b=[{id:"shou_lingwu",term:"受",pinyin:"shòu",meaning:"接受、领受（以手取得）。可传而不可受：道可以传授（指引方向），却不能被直接领受（把握）——道须自悟，不可硬取。传与受的区别：传是指引，受是执取；道可被指引，不可被执取。"},{id:"gu_cun",term:"固存",pinyin:"gù cún",meaning:"本来就存在、固然存在。固：本来、固然；存：存在。自古以固存：自古以来本来就存在——道先于天地而自存，不依赖任何外物。"},{id:"tai_ji",term:"太极",pinyin:"tài jí",meaning:"天地未分之前的原始状态、宇宙的最高极点。太：最大；极：极点、极限。在太极之先：在宇宙原始状态之前——道先于太极而存在。"},{id:"gao_wei_gao",term:"高",pinyin:"gāo",meaning:"（以）高（自居）。不为高：不因此而显得高——道超越高低，不以位置论高下。"},{id:"liu_ji",term:"六极",pinyin:"liù jí",meaning:"六合之极、宇宙六个方向的最远处（上下东西南北）。六极：宇宙空间的六个极端。在六极之下而不为深：在宇宙最深处之下却不显得深——道超越深浅。"},{id:"shen_wei_shen",term:"深",pinyin:"shēn",meaning:"（以）深（自居）。不为深：不因此而显得深。"},{id:"jiu_wei_jiu",term:"久",pinyin:"jiǔ",meaning:"（以）久远（自居）。不为久：不因此而显得久远——道超越时间长短。"},{id:"lao_wei_lao",term:"老",pinyin:"lǎo",meaning:"（以）古老（自居）。不为老：不因此而显得古老——道超越老幼之别。高·深·久·老：四「不为」并举，从空间（高·深）与时间（久·老）两个维度，说明道超越一切相对概念。"},{id:"xi_wei_shi",term:"豨韦氏",pinyin:"xī wéi shì",meaning:"传说中的上古帝王，比伏羲更古远。豨韦：读 xī wéi；氏：氏族、称号。"},{id:"qie_tiandi",term:"挈天地",pinyin:"qiè tiān dì",meaning:"提挈（统领）天地。挈：提起、统领，读 qiè。豨韦氏得之，以挈天地：豨韦氏得道，凭此统领天地——道使其具有统领天地的能力。"},{id:"fu_xi_shi",term:"伏戏氏",pinyin:"fú xī shì",meaning:"即伏羲氏，传说中的上古圣王，人文始祖。伏戏：伏羲的古写；氏：氏族称号。"},{id:"xi_qi_mu",term:"袭气母",pinyin:"xí qì mǔ",meaning:"契合（进入）气之本源。袭：契合、进入、沿袭；气母：气的本源、元气之母。伏戏氏得之，以袭气母：伏羲氏得道，凭此契合元气的本源——道使其能与元气本源相合。"},{id:"wei_dou",term:"维斗",pinyin:"wéi dǒu",meaning:"北斗星。维：维系、纲维；斗：北斗。维斗：维系天地方位的北斗星。"},{id:"zhong_gu_bute",term:"终古不忒",pinyin:"zhōng gǔ bù tè",meaning:"永远不差错（运行不偏差）。终古：永远、自古至今；不忒：不差错、不偏差，读 bù tè；忒：差错，读 tè。维斗得之，终古不忒：北斗星得道，因此永远运行不偏差。"},{id:"xi_tingxi",term:"息",pinyin:"xī",meaning:"停息、止息。终古不息：永远不停息——日月得道，永恒运行不止。"},{id:"kan_huai",term:"勘坏",pinyin:"kān pèi",meaning:"传说中的山神（大地之神）。勘坏：读 kān pèi，古代神话中掌管山岳大地的神灵。"},{id:"xi_kunlun",term:"袭昆仑",pinyin:"xí kūn lún",meaning:"统御（进入）昆仑山。袭：统御、进入、覆盖；昆仑：传说中天地之中的神山。勘坏得之，以袭昆仑：山神得道，凭此统御昆仑山。"},{id:"feng_yi",term:"冯夷",pinyin:"féng yí",meaning:"传说中的河神（黄河之神）。冯夷：读 féng yí，又称河伯。冯夷得之，以游大川：河神得道，凭此遨游大河——道使其能自在游于大川。"},{id:"jian_wu",term:"肩吾",pinyin:"jiān wú",meaning:"传说中的山神（泰山之神）。肩吾：泰山神的名称，《逍遥游》中亦出现此名。"},{id:"chu_dashan",term:"处大山",pinyin:"chǔ dà shān",meaning:"居处于大山之中。处：居处、安居；大山：大山（泰山）。肩吾得之，以处大山：山神得道，凭此安居于大山之中。"},{id:"huang_di",term:"黄帝",pinyin:"huáng dì",meaning:"传说中的上古帝王，中华人文始祖之一。黄帝：五帝之首，道家常以黄帝为得道的典范。"},{id:"deng_yuntian",term:"登云天",pinyin:"dēng yún tiān",meaning:"升登云天（乘云升天）。登：升登；云天：云端天界。黄帝得之，以登云天：黄帝得道，凭此乘云升天。"},{id:"zhuan_xu",term:"颛顼",pinyin:"zhuān xū",meaning:"传说中的上古帝王，五帝之一，黄帝之孙。颛顼：读 zhuān xū。"},{id:"chu_xuangong",term:"处玄宫",pinyin:"chǔ xuán gōng",meaning:"居处于玄冥之宫（北方幽深之宫）。玄宫：幽深神秘之宫，北方之宫。颛顼得之，以处玄宫：颛顼得道，凭此居于玄冥之宫。"},{id:"yu_qiang",term:"禺强",pinyin:"yú qiáng",meaning:"传说中的北海之神（风神）。禺强：读 yú qiáng，又作「禺京」，北方水神兼风神，人面鸟身。"},{id:"li_beiji",term:"立乎北极",pinyin:"lì hū běi jí",meaning:"屹立于北极之上。立：屹立；乎：于；北极：北方极点。禺强得之，立乎北极：北海神得道，凭此屹立于北极。"},{id:"xi_wang_mu",term:"西王母",pinyin:"xī wáng mǔ",meaning:"传说中的西方女神，掌管长生不老之药。西王母：神话中居于昆仑山的女神，象征永恒与长生。"},{id:"zuo_shaoguang",term:"坐乎少广",pinyin:"zuò hū shǎo guǎng",meaning:"端坐于少广山（西方神山）。坐：端坐；乎：于；少广：传说中的西方神山，西王母所居之处。"},{id:"mo_zhi_shi",term:"莫知其始",pinyin:"mò zhī qí shǐ",meaning:"没有人知道她的开始（起源）。莫：没有人；知：知道；其始：她的起始。"},{id:"mo_zhi_zhong",term:"莫知其终",pinyin:"mò zhī qí zhōng",meaning:"没有人知道她的终结。莫知其始·莫知其终：无始无终，与道同体——西王母得道，故与道一样无始无终。"},{id:"peng_zu",term:"彭祖",pinyin:"péng zǔ",meaning:"传说中的长寿者，相传活了八百岁。彭祖：上古长寿神人，《逍遥游》中亦提及。"},{id:"shang_ji_youyu",term:"上及有虞",pinyin:"shàng jí yǒu yú",meaning:"往上追溯到有虞氏（舜）的时代。上：往上、追溯；及：到达；有虞：有虞氏，即舜，上古圣王。"},{id:"xia_ji_wuba",term:"下及五伯",pinyin:"xià jí wǔ bà",meaning:"往下延续到五霸的时代。下：往下、延续；及：到达；五伯：春秋五霸，伯通「霸」。上及有虞·下及五伯：彭祖得道，寿命从舜的时代延续到春秋五霸，跨越极长的历史时段。"},{id:"fu_yue",term:"傅说",pinyin:"fù yuè",meaning:"商朝贤相，武丁（高宗）的名臣。傅说：读 fù yuè，原为筑墙奴隶，被武丁发现拜为相，辅佐武丁中兴商朝。"},{id:"xiang_wuding",term:"以相武丁",pinyin:"yǐ xiàng wǔ dīng",meaning:"凭此辅佐武丁（为武丁之相）。相：辅佐、担任宰相，读 xiàng；武丁：商朝中兴之君（高宗）。"},{id:"yan_you_tianxia",term:"奄有天下",pinyin:"yǎn yǒu tiān xià",meaning:"统有（拥有）整个天下。奄：全部、统统，读 yǎn；有：拥有；天下：天下。"},{id:"cheng_dongwei",term:"乘东维",pinyin:"chéng dōng wéi",meaning:"乘驾东维星（东方天际的维星）。乘：乘驾、乘坐；东维：东方天际维系天地的星宿（一说为东方星名）。"},{id:"qi_jiwei",term:"骑箕尾",pinyin:"qí jī wěi",meaning:"骑乘箕宿与尾宿（星座）。骑：骑乘；箕尾：二十八宿中的箕宿与尾宿，位于东方苍龙尾部。乘东维·骑箕尾：傅说死后化为星宿，乘驾天际——得道者死后与天地同化。"},{id:"bi_lixing",term:"比于列星",pinyin:"bǐ yú liè xīng",meaning:"与列星（群星）并列齐肩。比：并列、齐肩；于：与；列星：群星、众星。乘东维·骑箕尾而比于列星：乘驾天际星宿，与群星并列——傅说得道，死后升化为星，与天地永恒同存，是「得道者列传」的最高境界。"}],w=[{id:"nvyu_s1",label:"南伯子葵问乎女偊……何也",sentences:[[{text:"南伯子葵",glossary:"nan_bo_zikui"},"问乎",{text:"女偊",glossary:"nv_yu"},"曰：「子之年长矣，而",{text:"色",glossary:"se_rongmao"},"若",{text:"孺子",glossary:"ru_zi"},"，何也？」"],["曰：「吾闻道矣。」"]]},{id:"nvyu_s2",label:"南伯子葵曰道可得学邪……亦易矣",sentences:[["南伯子葵曰：「道可得学邪？」"],["曰：「",{text:"恶可",glossary:"e_ke"},"！子非其人也。夫",{text:"卜梁倚",glossary:"bu_liang_yi"},"有圣人之才而无圣人之道，我有圣人之道而无圣人之才。"],["吾欲以教之，",{text:"庶几",glossary:"shu_ji"},"其",{text:"果",glossary:"guo_guoran"},"为圣人乎？"],["不然，以圣人之道",{text:"告",glossary:"gao_gaoshu"},"圣人之才，亦",{text:"易矣",glossary:"yi_yi"},"。"]]},{id:"nvyu_s3",label:"吾犹守而告之……九日而后能外生",sentences:[["吾犹",{text:"守而告之",glossary:"shou_er_gao"},"，参日而后能",{text:"外天下",glossary:"wai_tianxia"},"；"],[{text:"已",glossary:"yi_jiyiran"},"外天下矣，吾又守之，七日而后能",{text:"外物",glossary:"wai_wu"},"；"],["已外物矣，吾又守之，九日而后能",{text:"外生",glossary:"wai_sheng"},"；"]]},{id:"nvyu_s4",label:"已外生矣……无古今而后能入于不死不生",sentences:[["已外生矣，而后能",{text:"朝彻",glossary:"zhao_che"},"；"],["朝彻而后能",{text:"见独",glossary:"jian_du"},"；"],["见独而后能",{text:"无古今",glossary:"wu_gujin"},"；"],["无古今而后能入于不死不生。"]]},{id:"nvyu_s5",label:"杀生者不死……其名为撄宁",sentences:[[{text:"杀生者不死",glossary:"sha_sheng_busi"},"，",{text:"生生者不生",glossary:"sheng_sheng_busheng"},"。"],[{text:"其",glossary:"qi_dao"},"为物，",{text:"无不将也",glossary:"wu_bu_jiang"},"，",{text:"无不迎也",glossary:"wu_bu_ying"},"，",{text:"无不毁也",glossary:"wu_bu_hui"},"，",{text:"无不成也",glossary:"wu_bu_cheng"},"。"],["其名为",{text:"撄宁",glossary:"ying_ning"},"。",{text:"撄宁也者，撄而后成者也",glossary:"ying_er_cheng"},"。」"]]},{id:"nvyu_s6",label:"南伯子葵曰子独恶乎闻之……闻之疑始",sentences:[["南伯子葵曰：「子独恶乎闻之？」曰：「闻",{text:"诸",glossary:"zhu_yuzhiyu"},{text:"副墨之子",glossary:"fu_mo_zi"},"，"],[{text:"副墨之子",glossary:"fu_mo_zi"},"闻",{text:"诸",glossary:"zhu_yuzhiyu"},{text:"洛诵之孙",glossary:"luo_song_sun"},"，"],[{text:"洛诵之孙",glossary:"luo_song_sun"},"闻之",{text:"瞻明",glossary:"zhan_ming"},"，"],[{text:"瞻明",glossary:"zhan_ming"},"闻之",{text:"聂许",glossary:"nie_xu"},"，"],[{text:"聂许",glossary:"nie_xu"},"闻之",{text:"需役",glossary:"xu_yi"},"，"],[{text:"需役",glossary:"xu_yi"},"闻之",{text:"于讴",glossary:"yu_ou"},"，"],[{text:"于讴",glossary:"yu_ou"},"闻之",{text:"玄冥",glossary:"xuan_ming"},"，"],[{text:"玄冥",glossary:"xuan_ming"},"闻之",{text:"参寥",glossary:"can_liao"},"，"],[{text:"参寥",glossary:"can_liao"},"闻之",{text:"疑始",glossary:"yi_shi"},"。」"]]}],c=[{id:"nan_bo_zikui",term:"南伯子葵",pinyin:"nán bó zǐ kuí",meaning:"人名，庄子虚构的求道者。南伯：南方之伯（封号）；子葵：名。以问道者的身份出现，衬托女偊的得道之深。"},{id:"nv_yu",term:"女偊",pinyin:"nǚ yǔ",meaning:"人名，庄子虚构的得道者。女偊：读 nǚ yǔ，传道者，年长而容若孺子，以得道而驻颜。"},{id:"se_rongmao",term:"色",pinyin:"sè",meaning:"面色、容貌。色若孺子：面色如同幼童（驻颜不老）——得道者形神俱养，外貌不随年岁衰老。"},{id:"ru_zi",term:"孺子",pinyin:"rú zǐ",meaning:"幼童、小孩。孺：幼小；子：孩子。色若孺子：面色如同幼童一般。"},{id:"e_ke",term:"恶可",pinyin:"wū kě",meaning:"哪里可以！怎么可能！恶：哪里、怎么，读 wū；可：可以。恶可：强烈否定，表道不可强学。"},{id:"bu_liang_yi",term:"卜梁倚",pinyin:"bǔ liáng yǐ",meaning:"人名，庄子虚构的有才无道者。卜梁倚：有圣人之才（聪明才智）而无圣人之道（得道境界）——才与道须兼备方能成圣。"},{id:"shu_ji",term:"庶几",pinyin:"shù jī",meaning:"也许、或许（表希望或推测）。庶：差不多、或许；几：近乎。庶几其果为圣人乎：也许他真能成为圣人吧？"},{id:"guo_guoran",term:"果",pinyin:"guǒ",meaning:"果真、真的。副词，表确实。庶几其果为圣人乎：也许他果真能成为圣人吧？"},{id:"gao_gaoshu",term:"告",pinyin:"gào",meaning:"告知、传授。以圣人之道告圣人之才：把圣人之道传授给有圣人之才的人。"},{id:"yi_yi",term:"易矣",pinyin:"yì yǐ",meaning:"容易了。易：容易；矣：语气词，表确定。以圣人之道告圣人之才，亦易矣：把道传授给有才的人，也就容易了——才与道相合，成圣自然。"},{id:"shou_er_gao",term:"守而告之",pinyin:"shǒu ér gào zhī",meaning:"守护（陪伴）着他，持续告知（引导）他。守：守护、持续陪伴；告之：告知他、引导他。吾犹守而告之：我尚且守护着他持续引导——强调得道须持续守护，非一蹴而就。"},{id:"wai_tianxia",term:"外天下",pinyin:"wài tiān xià",meaning:"将天下（世俗名利）置于自身之外（超越、忘却）。外：使……在外、超越、忘却；天下：世俗的天下（名利权位）。外天下：超越对天下（世俗）的执着——第一阶。"},{id:"yi_jiyiran",term:"已",pinyin:"yǐ",meaning:"已经（完成某阶段）。副词，表完成。已外天下矣：已经超越了天下（的执着）了。"},{id:"wai_wu",term:"外物",pinyin:"wài wù",meaning:"将万物置于自身之外（超越对外物的执着）。外：超越、忘却；物：外在事物。外物：超越对万物的执着——第二阶（比外天下更深一层）。"},{id:"wai_sheng",term:"外生",pinyin:"wài shēng",meaning:"将生命置于自身之外（超越对生命的执着）。外：超越、忘却；生：生命。外生：超越对生命的执着——第三阶（最难，须超越对自身生命的留恋）。外天下·外物·外生：三「外」层层递进，由外（天下）到近（物）到己（生），逐步剥除执着。"},{id:"zhao_che",term:"朝彻",pinyin:"zhāo chè",meaning:"如朝阳般豁然贯通（心境澄明透彻）。朝：朝阳，读 zhāo；彻：透彻、贯通。朝彻：如朝阳破晓般豁然开朗，心境澄明——第四阶，外生之后的精神突破。"},{id:"jian_du",term:"见独",pinyin:"jiàn dú",meaning:"见到独一（道的本体）。见：见到、体悟；独：独一无二、道的本体（超越一切对待的绝对存在）。见独：体悟到道的独一本体——第五阶，朝彻之后见到道本身。"},{id:"wu_gujin",term:"无古今",pinyin:"wú gǔ jīn",meaning:"超越古今（时间）的对立。无：超越、消除；古今：过去与现在（时间的对立）。无古今：超越时间的古今之别——第六阶，见独之后超越时间。"},{id:"sha_sheng_busi",term:"杀生者不死",pinyin:"shā shēng zhě bù sǐ",meaning:"能使生命消亡的（道）自身不死。杀生者：使生命消亡的（道）；不死：自身不死亡。"},{id:"sheng_sheng_busheng",term:"生生者不生",pinyin:"shēng shēng zhě bù shēng",meaning:"能使生命诞生的（道）自身不生。生生者：使生命产生的（道）；不生：自身不诞生。杀生者不死·生生者不生：道是生死的根源，却自身超越生死——道不在生死之中，故能主宰生死。"},{id:"qi_dao",term:"其",pinyin:"qí",meaning:"它（道）。代词，指道。其为物：道作为存在（物）。"},{id:"wu_bu_jiang",term:"无不将也",pinyin:"wú bù jiāng yě",meaning:"没有什么不送走的（无不送）。将：送走、送行；无不将：无所不送——道送走一切（死）。"},{id:"wu_bu_ying",term:"无不迎也",pinyin:"wú bù yíng yě",meaning:"没有什么不迎来的（无不迎）。迎：迎接；无不迎：无所不迎——道迎来一切（生）。无不将·无不迎：送往迎来，道主宰生死往来。"},{id:"wu_bu_hui",term:"无不毁也",pinyin:"wú bù huǐ yě",meaning:"没有什么不毁灭的（无不毁）。毁：毁灭、消解；无不毁：无所不毁——道消解一切（破）。"},{id:"wu_bu_cheng",term:"无不成也",pinyin:"wú bù chéng yě",meaning:"没有什么不成就的（无不成）。成：成就、生成；无不成：无所不成——道成就一切（立）。无不毁·无不成：毁而后成，道在毁灭与成就之间循环——呼应「撄宁」：撄（扰动·毁）而后宁（成）。"},{id:"ying_ning",term:"撄宁",pinyin:"yīng níng",meaning:"在扰动中保持宁静（动中之静）。撄：扰动、纷扰，读 yīng；宁：宁静、安宁。撄宁：经历扰动而后达到的宁静——非远离扰动的宁静，而是在扰动中仍能安宁。"},{id:"ying_er_cheng",term:"撄宁也者，撄而后成者也",pinyin:"yīng níng yě zhě yīng ér hòu chéng zhě yě",meaning:"所谓撄宁，是经历扰动之后才成就（宁静）的。撄而后成：经过扰动之后才成就；者也：判断语气。撄宁不是逃避扰动，而是经历扰动、超越扰动之后的宁静——是《大宗师》修道七阶的最高境界。"},{id:"zhu_yuzhiyu",term:"诸",pinyin:"zhū",meaning:"「之于」的合音。诸：之于，兼词。闻诸副墨之子：从副墨之子那里听来的。"},{id:"fu_mo_zi",term:"副墨之子",pinyin:"fù mò zhī zǐ",meaning:"文字（书写）之子，喻文字记录。副墨：文字、书写；之子：之子（拟人化）。道从文字记录开始流传——最外层、最具体的传道方式。"},{id:"luo_song_sun",term:"洛诵之孙",pinyin:"luò sòng zhī sūn",meaning:"反复诵读之孙，喻口诵记忆。洛诵：反复诵读、背诵；之孙：之孙（拟人化）。道从文字进入口诵记忆——第二层传递。"},{id:"zhan_ming",term:"瞻明",pinyin:"zhān míng",meaning:"明察（眼见为实），喻视觉观察。瞻：观察、瞻望；明：明亮、清晰。道从口诵进入视觉观察——第三层。"},{id:"nie_xu",term:"聂许",pinyin:"niè xǔ",meaning:"附耳细语（耳闻心受），喻听觉领受。聂：附耳低语，读 niè；许：应许、领受。道从观察进入耳闻心受——第四层。"},{id:"xu_yi",term:"需役",pinyin:"xū yì",meaning:"实践践行，喻身体力行。需役：需要、役使（付诸实践）。道从耳闻进入身体力行——第五层。"},{id:"yu_ou",term:"于讴",pinyin:"yú ōu",meaning:"歌咏吟唱，喻心灵吟咏（内化为情感）。于讴：吟唱、歌咏，读 yú ōu。道从实践升华为心灵歌咏——第六层。"},{id:"xuan_ming",term:"玄冥",pinyin:"xuán míng",meaning:"幽深冥暗（超越感知），喻道的幽深境界。玄：幽深；冥：冥暗、深远。道从歌咏进入幽深冥暗的境界——第七层。"},{id:"can_liao",term:"参寥",pinyin:"cān liáo",meaning:"高远寥廓（超越空间），喻道的高远空旷。参：高；寥：寥廓、空旷，读 cān liáo。道从幽深进入高远寥廓——第八层。"},{id:"yi_shi",term:"疑始",pinyin:"yí shǐ",meaning:"疑似有始（道的本源，似有似无）。疑：似乎、疑似；始：开始、本源。疑始：似乎有一个开始，却又无从把握——道的最终本源，不可名状。道的传递溯源至「疑始」，即回到道本身——无从追溯的本源。"}],j=[{id:"zisi_s1",label:"子祀、子舆、子犁、子来……遂相与为友",sentences:[[{text:"子祀",glossary:"zi_si"},"、",{text:"子舆",glossary:"zi_yu"},"、",{text:"子犁",glossary:"zi_li"},"、",{text:"子来",glossary:"zi_lai"},"四人",{text:"相与",glossary:"xiang_yu_yiqi"},"语曰："],["「孰能以",{text:"无为首",glossary:"wu_wei_shou"},"，以",{text:"生为脊",glossary:"sheng_wei_ji"},"，以",{text:"死为尻",glossary:"si_wei_kao"},"，"],["孰知",{text:"死生存亡",glossary:"si_sheng_cun_wang"},"之",{text:"一体者",glossary:"yi_ti_zhe"},"，",{text:"吾与之友矣",glossary:"wu_yu_you"},"！」"],["四人相视而笑，",{text:"莫逆于心",glossary:"mo_ni_xin"},"，",{text:"遂相与为友",glossary:"sui_xiang_you"},"。"]]},{id:"zisi_s2",label:"俄而子舆有病……予何恶",sentences:[[{text:"俄而",glossary:"e_er"},"子舆有病，子祀",{text:"往",glossary:"wang_tanwang"},"问之。"],["曰：「伟哉！夫造物者将",{text:"以予为此拘拘也",glossary:"ci_ju_ju"},"！」"],[{text:"曲偻发背",glossary:"qu_lou_fa_bei"},"，",{text:"五管",glossary:"wu_guan"},"在上，",{text:"颐隐",glossary:"yi_yin"},"于脐，肩高于顶，",{text:"句赘",glossary:"ju_zhui"},"指天。"],[{text:"阴阳之气有沴",glossary:"yin_yang_li"},"，其心闲而无事，",{text:"胼𫏨",glossary:"pian_jing"},"而鉴于井，曰：「嗟乎！夫造物者又将以予为此",{text:"拘拘",glossary:"ci_ju_ju"},"也。」"],["子祀曰：「女",{text:"恶",glossary:"wu_hen"},"之乎？」曰：「",{text:"亡",glossary:"wang_wu"},"，",{text:"予何恶",glossary:"yu_he_wu"},"！」"]]},{id:"zisi_s3",label:"浸假而化予之左臂以为鸡……以求时夜",sentences:[[{text:"浸假",glossary:"jin_jia"},"而化予之",{text:"左臂以为鸡",glossary:"zuo_bi_ji"},"，",{text:"予因",glossary:"yu_yin"},"以求",{text:"时夜",glossary:"shi_ye"},"；"],["浸假而化予之右臂以为",{text:"弹",glossary:"dan_danzhi"},"，予因以求",{text:"鸮炙",glossary:"xiao_zhi"},"；"]]},{id:"zisi_s4",label:"浸假而化予之尻以为轮……息我以死",sentences:[["浸假而化予之尻以为",{text:"轮",glossary:"lun_chelun"},"，以神为马，予因",{text:"乘",glossary:"cheng_chengzuo"},"之，岂更",{text:"驾",glossary:"jia_jia"},"哉！"],["且夫",{text:"得者",glossary:"de_zhe"},"，",{text:"时也",glossary:"shi_ye_shi"},"；",{text:"失者",glossary:"shi_zhe"},"，",{text:"顺也",glossary:"shun_ye"},"。"],["安时而处顺，",{text:"哀乐",glossary:"ai_le"},"不能",{text:"入也",glossary:"ru_ye"},"，此古之所谓",{text:"县解",glossary:"xian_jie"},"也。"],["而不能",{text:"自解者",glossary:"zi_jie_zhe"},"，",{text:"物有结之",glossary:"wu_you_jie"},"。"],["且夫大块载我以形，劳我以生，佚我以老，息我以死。"]]},{id:"zisi_s5",label:"子来有病……奚以汝适",sentences:[["子来有病，",{text:"喘喘然",glossary:"chuan_chuan"},"将死，其妻子",{text:"环",glossary:"huan_wei"},"而泣。子犁往问之，曰：「",{text:"叱",glossary:"chi_chi"},"！",{text:"避",glossary:"bi_bi"},"！",{text:"无怛化",glossary:"wu_da_hua"},"！」"],[{text:"倚",glossary:"yi_kao"},"其户与之语曰："],["「",{text:"伟哉造化",glossary:"wei_zao_hua"},"！又将奚以汝为？将奚以汝",{text:"适",glossary:"shi_wangna"},"？"],["以汝为",{text:"鼠肝",glossary:"shu_gan"},"乎？以汝为",{text:"虫臂",glossary:"chong_bi"},"乎？」"]]},{id:"zisi_s6",label:"子来曰且夫得者时也……蘧然觉",sentences:[["子来曰：「父母于子，东西南北，唯命之从。阴阳于人，不翅于父母；"],["彼",{text:"近吾死",glossary:"jin_si"},"而我不听，我则",{text:"悍",glossary:"han_weifu"},"矣，彼何",{text:"罪",glossary:"zui_zui"},"哉！"],["夫",{text:"大块",glossary:"da_kuai_08"},"载我以形，劳我以生，佚我以老，息我以死。"],["故善吾生者，乃所以善吾死也。"],["今",{text:"大冶铸金",glossary:"da_ye_zhu_jin"},"，金",{text:"踊跃",glossary:"yong_yue"},"曰『我且必为",{text:"镆铘",glossary:"mo_ye"},"』，大冶必以为不祥之金。"],["今一犯人之形，而曰『人耳人耳』，夫造化者必以为不祥之人。"],["今一以天地为大炉，以造化为大冶，恶乎往而不可哉！」"],[{text:"成然寐",glossary:"cheng_ran_mei"},"，",{text:"蘧然觉",glossary:"qu_ran_jue"},"。"]]}],f=[{id:"zi_si",term:"子祀",pinyin:"zǐ sì",meaning:"人名，庄子虚构的得道者之一。四人皆为庄子虚构，以「子」字命名，象征得道之人。"},{id:"zi_yu",term:"子舆",pinyin:"zǐ yú",meaning:"人名，庄子虚构的得道者之一。后文身患重病，形体极度扭曲，仍安然处顺，是本节核心人物。"},{id:"zi_li",term:"子犁",pinyin:"zǐ lí",meaning:"人名，庄子虚构的得道者之一。后文往问将死的子来，以「伟哉造化」宽慰之。"},{id:"zi_lai",term:"子来",pinyin:"zǐ lái",meaning:"人名，庄子虚构的得道者之一。后文临死前以「大冶铸金」为喻，坦然面对死亡。"},{id:"xiang_yu_yiqi",term:"相与",pinyin:"xiāng yǔ",meaning:"相互、一起（共同）。相与：互相、共同。四人相与语：四人在一起交谈。"},{id:"wu_wei_shou",term:"以无为首",pinyin:"yǐ wú wéi shǒu",meaning:"以「无」（虚无·道）为头。无：虚无、道；首：头部。以无为首·以生为脊·以死为尻：以道·生·死为身体的头·脊·尾，喻将道与生死视为一体。"},{id:"sheng_wei_ji",term:"以生为脊",pinyin:"yǐ shēng wéi jǐ",meaning:"以「生」为脊背（躯干）。脊：脊背，身体的中段。"},{id:"si_wei_kao",term:"以死为尻",pinyin:"yǐ sǐ wéi kāo",meaning:"以「死」为尾骨（末端）。尻：尾骨、臀部，读 kāo，身体的末端。以无为首·以生为脊·以死为尻：道·生·死构成一个完整的身体——三者本为一体，无分高下。"},{id:"si_sheng_cun_wang",term:"死生存亡",pinyin:"sǐ shēng cún wáng",meaning:"死亡、生存、存在、消亡——生命的全部状态。死生存亡之一体者：将死生存亡视为同一整体的人。"},{id:"yi_ti_zhe",term:"一体者",pinyin:"yī tǐ zhě",meaning:"视为同一整体的人。一体：同一整体；者：的人。死生存亡之一体者：能将死生存亡看作同一整体的人。"},{id:"wu_yu_you",term:"吾与之友矣",pinyin:"wú yǔ zhī yǒu yǐ",meaning:"我就与他为友了。与之友：与他结为朋友；矣：语气词，表确定。"},{id:"mo_ni_xin",term:"莫逆于心",pinyin:"mò nì yú xīn",meaning:"心中没有任何抵触（心意相通）。莫：没有；逆：抵触、违逆；于心：在心中。莫逆于心：心心相印，毫无隔阂——「莫逆之交」的出处。"},{id:"sui_xiang_you",term:"遂相与为友",pinyin:"suì xiāng yǔ wéi yǒu",meaning:"于是互相结为朋友。遂：于是；相与：互相；为友：结为朋友。"},{id:"e_er",term:"俄而",pinyin:"é ér",meaning:"不久、过了一会儿。俄：短暂时间；而：连词。俄而：表时间短暂过渡。"},{id:"wang_tanwang",term:"往",pinyin:"wǎng",meaning:"前往（探望）。往问之：前往探望他。"},{id:"ci_ju_ju",term:"以予为此拘拘也",pinyin:"yǐ yǔ wéi cǐ jū jū yě",meaning:"把我变成这副蜷曲拘束的样子。以予为：把我变成；此：这；拘拘：蜷曲拘束的样子，读 jū jū。造物者将以予为此拘拘也：造物者将要把我变成这副蜷曲的样子——子舆不以为苦，反以「伟哉」叹之。"},{id:"qu_lou_fa_bei",term:"曲偻发背",pinyin:"qū lóu fā bèi",meaning:"脊背弯曲隆起（驼背）。曲偻：弯曲驼背，读 qū lóu；发背：背部隆起。"},{id:"wu_guan",term:"五管",pinyin:"wǔ guǎn",meaning:"五脏的管道（五脏六腑）。五管：五脏，此处指内脏因驼背而向上挤压。五管在上：五脏被挤压到上方。"},{id:"yi_yin",term:"颐隐",pinyin:"yí yǐn",meaning:"下巴隐入（藏于）。颐：下巴；隐：隐入、藏入。颐隐于脐：下巴藏到了肚脐处——形容身体极度扭曲。"},{id:"ju_zhui",term:"句赘",pinyin:"gōu zhuì",meaning:"颈部赘肉隆起（颈项弯曲突出）。句：弯曲，读 gōu；赘：赘肉、突出物。句赘指天：颈部赘肉朝天突出。"},{id:"yin_yang_li",term:"阴阳之气有沴",pinyin:"yīn yáng zhī qì yǒu lì",meaning:"阴阳之气出现了乖戾（失调）。沴：气不和、乖戾，读 lì。阴阳之气有沴：阴阳之气失调——指疾病的根源。"},{id:"pian_jing",term:"胼𫏨",pinyin:"pián jìng",meaning:"蹒跚、步履艰难地走。胼𫏨：跛行、步履不稳，读 pián jìng。胼𫏨而鉴于井：蹒跚走到井边照看自己（的倒影）。"},{id:"wang_wu",term:"亡",pinyin:"wú",meaning:"没有、无。通「无」，读 wú。亡：没有（厌恶之情）。"},{id:"wu_hen",term:"恶",pinyin:"wù",meaning:"厌恶、憎恨。读 wù。女恶之乎：你厌恶（这种状态）吗？"},{id:"yu_he_wu",term:"予何恶",pinyin:"yǔ hé wù",meaning:"我厌恶什么呢（我有什么可厌恶的）！予：我；何：什么；恶：厌恶，读 wù。亡，予何恶：没有，我有什么可厌恶的！——子舆安时处顺，不以形体扭曲为苦。"},{id:"jin_jia",term:"浸假",pinyin:"jìn jiǎ",meaning:"渐渐地、假如渐渐地。浸：渐渐；假：假如。浸假而化予之左臂以为鸡：假如渐渐地把我的左臂变化为鸡。"},{id:"zuo_bi_ji",term:"左臂以为鸡",pinyin:"zuǒ bì yǐ wéi jī",meaning:"把左臂变化为鸡。以为：变化为；鸡：鸡（司晨报时之鸟）。"},{id:"yu_yin",term:"予因",pinyin:"yǔ yīn",meaning:"我就顺势（凭此）。予：我；因：顺势、凭借。予因以求时夜：我就顺势用它来报时（司晨）。"},{id:"shi_ye",term:"时夜",pinyin:"shí yè",meaning:"司晨报时（报告夜晚时辰）。时夜：掌管夜晚时辰，即鸡司晨报时之职。"},{id:"dan_danzhi",term:"弹",pinyin:"dàn",meaning:"弹弓（弹射鸟兽的工具）。以右臂为弹：把右臂变化为弹弓。"},{id:"xiao_zhi",term:"鸮炙",pinyin:"xiāo zhì",meaning:"烤猫头鹰（用弹弓射猫头鹰来烤食）。鸮：猫头鹰，读 xiāo；炙：烤肉。予因以求鸮炙：我就顺势用它来射猫头鹰烤着吃。"},{id:"lun_chelun",term:"轮",pinyin:"lún",meaning:"车轮。以尻为轮：把尾骨变化为车轮。"},{id:"cheng_chengzuo",term:"乘",pinyin:"chéng",meaning:"乘坐、乘驾。予因乘之：我就顺势乘坐它（以神为马，乘轮而行）。"},{id:"jia_jia",term:"驾",pinyin:"jià",meaning:"驾车（另外套车）。岂更驾哉：哪里还需要另外套车呢！——身体即车，神即马，无需外求。"},{id:"de_zhe",term:"得者",pinyin:"dé zhě",meaning:"（形体）得到（生命）的。得者：获得（形体·生命）的（情况）。"},{id:"shi_ye_shi",term:"时也",pinyin:"shí yě",meaning:"是时机（天时）使然。时：时机、天时；也：判断语气。得者，时也：得到（生命形体），是天时使然——非人力所求。"},{id:"shi_zhe",term:"失者",pinyin:"shī zhě",meaning:"（形体）失去（生命）的。失者：失去（形体·生命）的（情况）。"},{id:"shun_ye",term:"顺也",pinyin:"shùn yě",meaning:"是顺应（自然）使然。顺：顺应自然；也：判断语气。失者，顺也：失去（生命），是顺应自然——非可抗拒之事。得者时也·失者顺也：得失皆有其道，时与顺皆是自然，无需执着。"},{id:"ai_le",term:"哀乐",pinyin:"āi lè",meaning:"悲哀与欢乐（情绪的两端）。哀乐不能入也：悲哀与欢乐都不能进入（心中）——安时处顺，情绪无从侵扰。"},{id:"ru_ye",term:"入也",pinyin:"rù yě",meaning:"进入（心中）。入：侵入、进入。哀乐不能入也：哀乐不能进入心中——心境超然，不为情绪所动。"},{id:"xian_jie",term:"县解",pinyin:"xuán jiě",meaning:"悬挂的解脱（倒悬得解）。县：通「悬」，悬挂；解：解脱、解开。县解：如同解开倒悬之苦——古人以「倒悬」喻极苦，县解即从极苦中彻底解脱。此古之所谓县解也：这就是古人所说的「县解」——安时处顺，哀乐不入，即是真正的解脱。"},{id:"zi_jie_zhe",term:"自解者",pinyin:"zì jiě zhě",meaning:"能自己解脱的人。自解：自行解脱。"},{id:"wu_you_jie",term:"物有结之",pinyin:"wù yǒu jié zhī",meaning:"是外物（执着）将他束缚住了。物：外物、执着；结：束缚、缠结；之：他。而不能自解者，物有结之：不能自行解脱的人，是因为外物（执着）将他束缚住了。"},{id:"chuan_chuan",term:"喘喘然",pinyin:"chuǎn chuǎn rán",meaning:"气喘吁吁的样子（将死时的急促呼吸）。喘喘：急促喘息；然：……的样子。"},{id:"huan_wei",term:"环",pinyin:"huán",meaning:"围绕（团团围住）。环而泣：围绕着（子来）哭泣。"},{id:"chi_chi",term:"叱",pinyin:"chì",meaning:"大声呵斥。叱：呵斥、喝止。叱！避！：呵斥道：走开！"},{id:"bi_bi",term:"避",pinyin:"bì",meaning:"走开、回避。叱！避！：呵斥妻子儿女走开，不要以哭泣打扰子来的死亡过程。"},{id:"wu_da_hua",term:"无怛化",pinyin:"wú dá huà",meaning:"不要惊扰（阻碍）造化（的进程）。无：不要；怛：惊扰、惊动，读 dá；化：造化、变化。无怛化：不要惊扰造化的自然进程——死亡是造化，不应以哭泣打扰。"},{id:"yi_kao",term:"倚",pinyin:"yǐ",meaning:"倚靠（门旁）。倚其户：倚靠在门旁。"},{id:"wei_zao_hua",term:"伟哉造化",pinyin:"wěi zāi zào huà",meaning:"伟大啊，造化！伟哉：感叹词，伟大啊；造化：自然造化。伟哉造化：以赞叹造化开头，表达对自然变化的敬畏与顺应。"},{id:"shi_wangna",term:"适",pinyin:"shì",meaning:"去往、前往（何处）。奚以汝适：要把你送往何处。奚以汝为·奚以汝适：将要把你变成什么？将要把你送往何处？——造化主宰一切变化，人只需顺应。"},{id:"shu_gan",term:"鼠肝",pinyin:"shǔ gān",meaning:"老鼠的肝脏（极微小卑贱之物）。以汝为鼠肝乎：把你变成老鼠的肝脏吗？——以极微小之物为喻，说明造化可将人变成任何形态，皆应顺应。"},{id:"chong_bi",term:"虫臂",pinyin:"chóng bì",meaning:"虫子的手臂（极微小卑贱之物）。以汝为虫臂乎：把你变成虫子的手臂吗？鼠肝·虫臂：两个极微小的意象，说明无论变化为何物，皆是造化，皆应坦然接受。"},{id:"jin_si",term:"近吾死",pinyin:"jìn wú sǐ",meaning:"使我趋近死亡。近：使……接近；吾死：我的死亡。彼近吾死：它（阴阳造化）使我趋近死亡。"},{id:"han_weifu",term:"悍",pinyin:"hàn",meaning:"违逆、抗拒（强悍不从）。我则悍矣：我就是在违逆（造化）了——若不顺应死亡，便是抗拒造化。"},{id:"zui_zui",term:"罪",pinyin:"zuì",meaning:"罪过、过错。彼何罪哉：它（造化）有什么罪过呢！——造化无罪，死亡是自然，不应怨恨。"},{id:"da_kuai_08",term:"大块",pinyin:"dà kuài",meaning:"大地、自然造化的总体。同第五节「大块」，此处子来引用，强调死生皆是大块（自然）的赋予。"},{id:"da_ye_zhu_jin",term:"大冶铸金",pinyin:"dà yě zhù jīn",meaning:"伟大的冶匠铸造金属。大冶：伟大的冶匠（喻造化）；铸金：熔铸金属（喻造化塑造万物）。大冶铸金：以冶匠铸金喻造化塑造人的形体——人不能自主选择形体，正如金属不能自主选择形状。"},{id:"yong_yue",term:"踊跃",pinyin:"yǒng yuè",meaning:"跳跃（金属熔液沸腾跳动）。踊跃：跳动、沸腾。金踊跃曰：金属（熔液）跳跃着说——拟人化，喻人执着于自身形体。"},{id:"mo_ye",term:"镆铘",pinyin:"mò yé",meaning:"传说中的名剑（极珍贵之器）。镆铘：读 mò yé，古代名剑，象征最珍贵的器物。我且必为镆铘：我一定要成为镆铘（名剑）——喻人执着于成为某种特定形态，不肯顺应造化。大冶必以为不祥之金：大冶匠一定认为这是不吉祥的金属——执着于形态者，是造化眼中的不祥之物。"},{id:"cheng_ran_mei",term:"成然寐",pinyin:"chéng rán mèi",meaning:"安然入睡（平静地睡去）。成然：安然、平静的样子；寐：入睡。成然寐：平静地睡去——喻死亡如安然入睡，毫无恐惧。"},{id:"qu_ran_jue",term:"蘧然觉",pinyin:"qú rán jué",meaning:"豁然醒来（惊喜地醒来）。蘧然：惊喜、豁然的样子，读 qú rán；觉：醒来。成然寐·蘧然觉：安然睡去·豁然醒来——以睡眠与觉醒喻死亡与新生，死如入睡，生如觉醒，循环往复，无需恐惧。"}],q=[{id:"sang_s1",label:"子桑户、孟子反、子琴张……遂相与友",sentences:[[{text:"子桑户",glossary:"zi_sang_hu"},"、",{text:"孟子反",glossary:"meng_zi_fan"},"、",{text:"子琴张",glossary:"zi_qin_zhang"},"三人相与友曰："],["「孰能相与",{text:"于无相与",glossary:"wu_xiang_yu"},"，相为",{text:"于无相为",glossary:"wu_xiang_wei"},"；"],["孰能",{text:"登天游雾",glossary:"deng_tian_wu"},"，",{text:"挠挑无极",glossary:"nao_tiao_wuji"},"，",{text:"相忘以生",glossary:"xiang_wang_sheng"},"，",{text:"无所穷终",glossary:"wu_qiong_zhong"},"！」"],["三人相视而笑，莫逆于心，遂相与友。"]]},{id:"sang_s2",label:"莫然有间而子桑户死……无以命之",sentences:[["莫然有间，而子桑户死，未葬。孔子闻之，",{text:"使子贡往",glossary:"shi_zigong_wang"},{text:"侍事",glossary:"shi_shi"},"焉。"],["或编曲，或鼓琴，相和而歌曰：「",{text:"嗟来桑户乎",glossary:"jie_lai_sang"},"！嗟来桑户乎！"],[{text:"而已反其真",glossary:"fan_qi_zhen"},"，",{text:"而我犹为人猗",glossary:"you_wei_ren_yi"},"！」"],["子贡",{text:"趋而进",glossary:"qu_er_jin"},"曰：「敢问临尸而歌，礼乎？」"],["二人相视而笑曰：「是恶知礼意！」"],["子贡反，以告孔子曰：「彼何人者邪？修行无有而外其形骸，临尸而歌，",{text:"颜色不变",glossary:"yan_se_bu_bian"},"，",{text:"无以命之",glossary:"wu_yi_ming_zhi"},"。彼何人者邪？」"]]},{id:"sang_s3",label:"孔子曰彼游方之外者也……以观众人之耳目哉",sentences:[["孔子曰：「彼",{text:"游方之外者",glossary:"you_fang_wai"},"也，而丘",{text:"游方之内者",glossary:"you_fang_nei"},"也。"],["外内不",{text:"相及",glossary:"xiang_ji"},"，而丘使女往",{text:"吊之",glossary:"diao_zhi"},"，丘则",{text:"陋矣",glossary:"lou_yi"},"！"],["彼方且与造物者为人，而游乎",{text:"天地之一气",glossary:"yi_qi"},"。"],["彼以生为",{text:"附赘县疣",glossary:"fu_zhui_xian_you"},"，以死为",{text:"决疴溃痈",glossary:"jue_ke_kui_yong"},"。"],["夫若然者，又恶知死生先后之所在！"],[{text:"假于异物",glossary:"jia_yi_wu"},"，",{text:"托于同体",glossary:"tuo_tong_ti"},"；"],[{text:"忘其肝胆",glossary:"wang_gan_dan"},"，",{text:"遗其耳目",glossary:"yi_er_mu"},"；"],[{text:"反复终始",glossary:"fan_fu_zhong_shi"},"，",{text:"不知端倪",glossary:"bu_zhi_duan_ni"},"；"],[{text:"芒然",glossary:"mang_ran"},{text:"仿徨",glossary:"fang_huang"},"乎",{text:"尘垢之外",glossary:"chen_gou_wai"},"，逍遥乎",{text:"无为之业",glossary:"wu_wei_ye"},"。"],["彼又恶能",{text:"愦愦然",glossary:"kui_kui_ran"},"为世俗之礼，以观众人之耳目哉！」"]]},{id:"sang_s4",label:"子贡曰然则夫子何方之依……吾与汝共之",sentences:[["子贡曰：「然则夫子何方之",{text:"依",glossary:"yi_yifu"},"？」"],["孔子曰：「",{text:"丘",glossary:"qiu_kongzi"},"，",{text:"天之戮民也",glossary:"tian_lu_min"},"。虽然，吾与汝共之。」"]]},{id:"sang_s5",label:"鱼相造乎水……人相忘乎道术",sentences:[["孔子曰：「",{text:"鱼相造乎水",glossary:"yu_zao_shui"},"，",{text:"人相造乎道",glossary:"ren_zao_dao"},"。"],[{text:"相造乎水者",glossary:"zao_shui_zhe"},"，",{text:"穿池而养给",glossary:"chuan_chi_yang_ji"},"；"],[{text:"相造乎道者",glossary:"zao_dao_zhe"},"，",{text:"无事而生定",glossary:"wu_shi_sheng_ding"},"。"],["故曰：鱼",{text:"相忘乎",glossary:"xiang_wang_hu"},{text:"江湖",glossary:"jiang_hu_dao"},"，人相忘乎",{text:"道术",glossary:"dao_shu"},"。」"]]},{id:"sang_s6",label:"子贡曰敢问畸人……天之小人也",sentences:[["子贡曰：「敢问",{text:"畸人",glossary:"ji_ren"},"？」"],["曰：「畸人者，",{text:"畸于人",glossary:"ji_yu_ren"},"而",{text:"侔于天",glossary:"mou_yu_tian"},"。"],["故曰：",{text:"天之小人",glossary:"tian_xiao_ren"},"，",{text:"人之君子",glossary:"ren_jun_zi_tian"},"；",{text:"人之君子",glossary:"ren_jun_zi_tian"},"，",{text:"天之小人也",glossary:"tian_xiao_ren"},"。」"]]}],k=[{id:"zi_sang_hu",term:"子桑户",pinyin:"zǐ sāng hù",meaning:"人名，庄子虚构的得道者，本节主角。子桑户死后，友人临尸而歌，引发子贡的困惑与孔子的论道。"},{id:"meng_zi_fan",term:"孟子反",pinyin:"mèng zǐ fǎn",meaning:"人名，庄子虚构的得道者之一。与子桑户、子琴张同为「游方之外」的真人。"},{id:"zi_qin_zhang",term:"子琴张",pinyin:"zǐ qín zhāng",meaning:"人名，庄子虚构的得道者之一。子桑户死后，与孟子反临尸鼓琴而歌。"},{id:"wu_xiang_yu",term:"于无相与",pinyin:"yú wú xiāng yǔ",meaning:"在无需相交之中（相交）。无相与：没有刻意相交的形式；于无相与：在无形式的相交中——真正的友谊超越形式，无需刻意维系。"},{id:"wu_xiang_wei",term:"于无相为",pinyin:"yú wú xiāng wéi",meaning:"在无需相助之中（相助）。无相为：没有刻意相为的行为；于无相为：在无形式的相助中——真正的帮助超越刻意，自然而然。相与于无相与·相为于无相为：两句并举，以「无」字点出真友谊的本质：超越形式与刻意，回归自然。"},{id:"deng_tian_wu",term:"登天游雾",pinyin:"dēng tiān yóu wù",meaning:"登上天际，遨游云雾之中。登天：升登天际；游雾：遨游雾中。登天游雾·挠挑无极：描绘得道者自在遨游于天地之间，超越一切界限。"},{id:"nao_tiao_wuji",term:"挠挑无极",pinyin:"náo tiāo wú jí",meaning:"腾跃于无穷无极之境。挠挑：腾跃、翻腾，读 náo tiāo；无极：无穷无尽之境。"},{id:"xiang_wang_sheng",term:"相忘以生",pinyin:"xiāng wàng yǐ shēng",meaning:"在生命中互相忘却（超越生死执着而相忘）。相忘：互相忘却；以生：在生命之中。相忘以生：在生命中彼此忘却——呼应「相忘于江湖」，超越生死执着。"},{id:"wu_qiong_zhong",term:"无所穷终",pinyin:"wú suǒ qióng zhōng",meaning:"没有穷尽与终结。无所：没有；穷终：穷尽与终结。无所穷终：永无穷尽——超越时间的终始，与道同化。"},{id:"shi_zigong_wang",term:"使子贡往",pinyin:"shǐ zǐ gòng wǎng",meaning:"派遣子贡前往。使：派遣；子贡：孔子弟子，儒家礼仪的代表；往：前往。孔子使子贡往侍事：孔子派子贡前往协助丧事——以儒家礼仪代表遭遇道家真人，形成对比。"},{id:"shi_shi",term:"侍事",pinyin:"shì shì",meaning:"协助料理（丧）事。侍：侍奉、协助；事：事务（此处指丧事）。"},{id:"jie_lai_sang",term:"嗟来桑户乎",pinyin:"jiē lái sāng hù hū",meaning:"哎，桑户啊！嗟来：感叹词，哎；桑户乎：桑户啊。嗟来桑户乎（重复两次）：呼唤死者，以歌代哭——得道者以歌送别，非以泪悲哀。"},{id:"fan_qi_zhen",term:"而已反其真",pinyin:"ér yǐ fǎn qí zhēn",meaning:"你已经回归了本真（真道）。而：你；已：已经；反：返回；其真：他的本真、真性。而已反其真：你（桑户）已经回归了本真——死亡是回归真道，非损失。"},{id:"you_wei_ren_yi",term:"而我犹为人猗",pinyin:"ér wǒ yóu wéi rén yī",meaning:"而我还在做人啊（尚未回归本真）。而我：而我；犹：尚且、还；为人：做人（受形体束缚）；猗：语气词，读 yī，表感叹。而我犹为人猗：反衬桑户已归真，自己尚在人形中——以羡慕语气，点出死亡是解脱。"},{id:"qu_er_jin",term:"趋而进",pinyin:"qū ér jìn",meaning:"快步上前。趋：快步走；而：连词；进：上前。子贡趋而进：子贡快步上前（质问）——以子贡的急切衬托二人的从容。"},{id:"yan_se_bu_bian",term:"颜色不变",pinyin:"yán sè bù biàn",meaning:"面色没有变化（神情自若）。颜色：面色、神情；不变：没有改变。临尸而歌，颜色不变：面对死尸唱歌，神情自若——得道者超越生死，死亡不能动其心。"},{id:"wu_yi_ming_zhi",term:"无以命之",pinyin:"wú yǐ mìng zhī",meaning:"无法用（任何名称）来称呼他们。无以：没有办法；命：命名、称呼；之：他们。无以命之：无法定义——得道者超越一切名称与分类。"},{id:"you_fang_wai",term:"游方之外者",pinyin:"yóu fāng zhī wài zhě",meaning:"游于规矩（礼法）之外的人。游：遨游、超越；方：方圆、规矩、礼法；之外：之外。游方之外：超越礼法规矩，自在遨游——道家真人的境界。"},{id:"you_fang_nei",term:"游方之内者",pinyin:"yóu fāng zhī nèi zhě",meaning:"游于规矩（礼法）之内的人。方之内：礼法规矩之内。游方之内：在礼法规矩之内行事——儒家君子的境界。游方之外·游方之内：庄子借孔子之口，区分道家（外）与儒家（内）的境界，并非高下之判，而是各有其道。"},{id:"xiang_ji",term:"相及",pinyin:"xiāng jí",meaning:"相互涉及（干涉）。相及：互相涉及、相互影响。外内不相及：方外与方内不相互干涉——各有其道，不应以方内之礼衡量方外之人。"},{id:"diao_zhi",term:"吊之",pinyin:"diào zhī",meaning:"前往吊唁他（们）。吊：吊唁、慰问丧家；之：他们（孟子反·子琴张）。"},{id:"lou_yi",term:"陋矣",pinyin:"lòu yǐ",meaning:"浅陋了（做错了）。陋：浅陋、不当；矣：语气词。丘则陋矣：我（孔子）就浅陋了——孔子自我批评，以儒家礼仪去衡量道家真人，是不恰当的。"},{id:"yi_qi",term:"天地之一气",pinyin:"tiān dì zhī yī qì",meaning:"天地之间的同一元气。一气：同一元气、浑然一体的气。游乎天地之一气：遨游于天地浑然一体的元气之中——得道者与天地元气融为一体。"},{id:"fu_zhui_xian_you",term:"附赘县疣",pinyin:"fù zhuì xuán yóu",meaning:"附着的赘肉与悬挂的疣（多余无用之物）。附赘：附着的赘肉；县：通「悬」，悬挂；疣：皮肤上的赘生物，读 yóu。以生为附赘县疣：把生命看作多余的赘肉——生命只是暂时附着的形态，无需执着。"},{id:"jue_ke_kui_yong",term:"决疴溃痈",pinyin:"jué kē kuì yōng",meaning:"切除病灶、溃破脓疮（去除病痛的解脱）。决：切开；疴：病，读 kē；溃：溃破；痈：脓疮，读 yōng。以死为决疴溃痈：把死亡看作切除病灶——死亡是解脱，如同去除身上的病痛。附赘县疣·决疴溃痈：生是赘肉，死是去病——两个医学意象，彻底颠覆世俗的生死观。"},{id:"jia_yi_wu",term:"假于异物",pinyin:"jiǎ yú yì wù",meaning:"借寓于不同的事物（形态）之中。假：借寓、寄托；于：于；异物：不同的事物（各种形态）。假于异物：寄托于各种不同的形态——道在万物中流转，无固定形态。"},{id:"tuo_tong_ti",term:"托于同体",pinyin:"tuō yú tóng tǐ",meaning:"寄托于同一本体（道）之中。托：寄托；同体：同一本体（道）。假于异物·托于同体：形态各异，本体同一——万物形态不同，却同托于道这一本体。"},{id:"wang_gan_dan",term:"忘其肝胆",pinyin:"wàng qí gān dǎn",meaning:"忘却自身的肝胆（内脏·身体内部）。忘：忘却；肝胆：内脏，喻身体内部、自我执着。"},{id:"yi_er_mu",term:"遗其耳目",pinyin:"yí qí ěr mù",meaning:"遗忘自身的耳目（感官·身体外部）。遗：遗忘、舍弃；耳目：感官，喻身体外部、感知执着。忘其肝胆·遗其耳目：忘却内外（内脏与感官）——超越身体的内外执着，与道合一。"},{id:"fan_fu_zhong_shi",term:"反复终始",pinyin:"fǎn fù zhōng shǐ",meaning:"在终结与开始之间往复循环。反复：往复、循环；终始：终结与开始。反复终始：在生死终始之间循环往复——无固定的起点与终点。"},{id:"bu_zhi_duan_ni",term:"不知端倪",pinyin:"bù zhī duān ní",meaning:"不知道（生死的）端绪与边际。端：端绪、起点；倪：边际、终点，读 ní。不知端倪：无从把握起点与终点——超越时间的始终，与道同化。"},{id:"mang_ran",term:"芒然",pinyin:"máng rán",meaning:"茫然自在、无所拘束的样子。芒然：通「茫然」，广漠无际、自在无拘的样子。"},{id:"fang_huang",term:"仿徨",pinyin:"fǎng huáng",meaning:"自在徘徊、逍遥游荡。仿徨：通「彷徨」，此处非迷茫之意，而是自在游荡、无所拘束。芒然仿徨乎尘垢之外：茫然自在地游荡于尘世污垢之外——超越世俗，自在无拘。"},{id:"chen_gou_wai",term:"尘垢之外",pinyin:"chén gòu zhī wài",meaning:"尘世污垢之外（世俗名利之外）。尘垢：尘世的污垢，喻世俗的名利礼法；之外：之外。芒然仿徨乎尘垢之外：自在游荡于世俗之外。"},{id:"wu_wei_ye",term:"无为之业",pinyin:"wú wéi zhī yè",meaning:"无为的事业（道的境界）。无为：顺应自然、不刻意作为；业：事业、境界。逍遥乎无为之业：逍遥于无为的境界之中——得道者的终极状态。"},{id:"kui_kui_ran",term:"愦愦然",pinyin:"kuì kuì rán",meaning:"烦扰纷乱的样子（拘谨忙碌于礼仪）。愦愦：烦乱、纷扰，读 kuì kuì；然：……的样子。愦愦然为世俗之礼：烦扰纷乱地去遵行世俗礼仪——以「愦愦然」讽刺拘于礼仪的繁琐。"},{id:"yi_yifu",term:"依",pinyin:"yī",meaning:"依从、依归（所遵循的）。何方之依：依归于哪种方（规矩·道）？然则夫子何方之依：那么您（孔子）依归于哪种方呢？"},{id:"qiu_kongzi",term:"丘",pinyin:"qiū",meaning:"孔子自称其名。丘：孔子名丘，此处自称，表谦逊。"},{id:"tian_lu_min",term:"天之戮民也",pinyin:"tiān zhī lù mín yě",meaning:"被天（道）所刑戮的人（受天惩罚而困于礼法的人）。戮：刑戮、惩罚，读 lù；民：人。天之戮民：被天道惩罚（束缚于礼法）的人——孔子自嘲受礼法束缚，无法游方之外，是天道对他的一种「刑戮」。"},{id:"yu_zao_shui",term:"鱼相造乎水",pinyin:"yú xiāng zào hū shuǐ",meaning:"鱼相互聚合于水中。相造：相互聚合、相互依存；乎：于。鱼相造乎水：鱼依水而聚、依水而生。"},{id:"ren_zao_dao",term:"人相造乎道",pinyin:"rén xiāng zào hū dào",meaning:"人相互聚合于道中。人依道而聚、依道而生。鱼相造乎水·人相造乎道：鱼与水·人与道，两组对应——水是鱼的本源，道是人的本源。"},{id:"zao_shui_zhe",term:"相造乎水者",pinyin:"xiāng zào hū shuǐ zhě",meaning:"依水而聚的（鱼）。相造乎水者：依水而聚合的（鱼）。"},{id:"chuan_chi_yang_ji",term:"穿池而养给",pinyin:"chuān chí ér yǎng jǐ",meaning:"挖掘水池便能得到充足的养育。穿池：挖掘水池；养给：养育充足、供给充分。相造乎水者，穿池而养给：依水而生的鱼，只需挖个水池便能养活——水是鱼的根本需求。"},{id:"zao_dao_zhe",term:"相造乎道者",pinyin:"xiāng zào hū dào zhě",meaning:"依道而聚的（人）。相造乎道者：依道而聚合的（人）。"},{id:"wu_shi_sheng_ding",term:"无事而生定",pinyin:"wú shì ér shēng dìng",meaning:"无所事事（顺应自然）而生命自然安定。无事：无所刻意作为；生定：生命自然安定。相造乎道者，无事而生定：依道而生的人，顺应自然无为，生命便自然安定——道是人的根本，无需刻意求取。"},{id:"xiang_wang_hu",term:"相忘乎",pinyin:"xiāng wàng hū",meaning:"在……中互相忘却。相忘：互相忘却；乎：于、在……中。"},{id:"jiang_hu_dao",term:"江湖",pinyin:"jiāng hú",meaning:"江河湖海（自然广阔之境）。鱼相忘乎江湖：鱼在江湖中互相忘却——回归自然本性，自在无拘。呼应第四节「相忘于江湖」。"},{id:"dao_shu",term:"道术",pinyin:"dào shù",meaning:"道（自然之道）。道术：道的方法与本体，此处即指道本身。人相忘乎道术：人在道中互相忘却——回归道的本性，自在无拘。鱼相忘乎江湖·人相忘乎道术：两句对应，江湖之于鱼，道之于人——各归其本源，自然相忘。"},{id:"ji_ren",term:"畸人",pinyin:"jī rén",meaning:"奇异之人（与世俗不同的人）。畸：奇异、与众不同，读 jī；人：人。畸人：在世人眼中奇异怪诞，却与天道相合的人——游方之外的真人。"},{id:"ji_yu_ren",term:"畸于人",pinyin:"jī yú rén",meaning:"在人（世俗）看来是奇异的。畸：奇异；于人：在世人看来。畸于人：在世俗眼中是奇人怪人。"},{id:"mou_yu_tian",term:"侔于天",pinyin:"móu yú tiān",meaning:"与天（道）相齐等（相合）。侔：齐等、相等，读 móu；于天：与天道。侔于天：与天道相合、与自然齐等。畸于人·侔于天：在人看来奇异，在天看来齐等——世俗的「奇」正是天道的「正」。"},{id:"tian_xiao_ren",term:"天之小人",pinyin:"tiān zhī xiǎo rén",meaning:"天（道）眼中的小人（不合天道的人）。天之小人：在天道看来是小人——世俗的君子，遵守礼法，却不合天道，故为天之小人。"},{id:"ren_jun_zi_tian",term:"人之君子",pinyin:"rén zhī jūn zǐ",meaning:"人（世俗）眼中的君子。人之君子：在世俗看来是君子——遵守礼法、合乎世俗规范。天之小人，人之君子；人之君子，天之小人也：世俗君子·天道小人，两者互为反转——庄子以此彻底颠覆儒家的君子观，点明「游方之内」与「游方之外」的根本差异。"}],P=[{id:"meng_s1",label:"颜回问仲尼……回壹怪之",sentences:[[{text:"颜回",glossary:"yan_hui"},"问仲尼曰：「",{text:"孟孙才",glossary:"meng_sun_cai"},"，其母死，哭泣无",{text:"涕",glossary:"ti_lei"},"，",{text:"中心不戚",glossary:"zhong_xin_qi"},"，",{text:"居丧不哀",glossary:"ju_sang_ai"},"。"],[{text:"无是三者，以善处丧",glossary:"shan_chu_sang"},"，",{text:"盖",glossary:"gai_mingwen"},"鲁国，"],["固",{text:"有无其实而得其名者乎",glossary:"wu_shi_de_ming"},"？",{text:"回壹怪之",glossary:"hui_yi_guai"},"。」"]]},{id:"meng_s2",label:"仲尼曰夫孟孙氏尽之矣……夫已有所简矣",sentences:[["仲尼曰：「夫孟孙氏",{text:"尽之矣",glossary:"jin_zhi_yi"},"，",{text:"进于知矣",glossary:"jin_yu_zhi"},"，"],[{text:"唯",glossary:"wei_suiran"},{text:"简之而不得",glossary:"jian_zhi_bude"},"，",{text:"夫已有所简矣",glossary:"you_suo_jian"},"。"]]},{id:"meng_s3",label:"孟孙氏不知所以生……以待其所不知之化已乎",sentences:[["孟孙氏不知所以生，不知所以死。"],[{text:"不知就先",glossary:"zhi_jiu_xian"},"，",{text:"不知就后",glossary:"zhi_jiu_hou"},"。"],["若",{text:"化为物",glossary:"hua_wei_wu"},"，",{text:"以",glossary:"yi_er_deng"},"待",{text:"其",glossary:"qi_suobu_zhi"},"所不知之化",{text:"已乎",glossary:"yi_hu_eryi"},"。"],["且方将化，",{text:"恶知不化哉",glossary:"wu_zhi_bu_hua"},"？方将不化，恶知已化哉？"]]},{id:"meng_s4",label:"吾特与汝其梦未始觉者邪……有旦宅而无情死",sentences:[["吾特与汝，",{text:"其梦未始觉者邪",glossary:"meng_wei_jue"},"！"],["且彼",{text:"有骇形而无损心",glossary:"hai_xing_sun_xin"},"，",{text:"有旦宅",glossary:"dan_zhai"},"而",{text:"无情死",glossary:"wu_qing_si"},"。"]]},{id:"meng_s5",label:"孟孙氏特觉……庸讵知吾所谓吾之乎",sentences:[["孟孙氏",{text:"特",glossary:"te_jin_meng"},{text:"觉",glossary:"jue_xingwu"},"，人哭亦哭，",{text:"是自其所以乃",glossary:"zi_qi_suo_nai"},"。"],["且也相与",{text:"『吾之』",glossary:"wu_zhi_wei"},"耳矣，",{text:"庸讵",glossary:"yong_ju"},"知吾所谓『吾之』乎？"]]},{id:"meng_s6",label:"且汝梦为鸟而厉乎天……其梦者乎",sentences:[["且汝梦为鸟而",{text:"厉乎天",glossary:"li_tian"},"，梦为鱼而",{text:"没于渊",glossary:"mo_yuan"},"。"],["不识今之言者，其",{text:"觉",glossary:"jue_xingwu"},"者乎？其梦者乎？"]]},{id:"meng_s7",label:"造适不及笑……乃入于寥天一",sentences:[[{text:"造适不及笑",glossary:"zao_shi_xiao"},"，",{text:"献笑不及排",glossary:"xian_xiao_pai"},"，"],[{text:"安排而去化",glossary:"an_pai_qu_hua"},"，",{text:"乃",glossary:"nai_caineng"},"入于",{text:"寥天一",glossary:"liao_tian_yi"},"。」"]]}],T=[{id:"yan_hui",term:"颜回",pinyin:"yán huí",meaning:"孔子最得意的弟子，以仁德著称。此处以颜回发问，引出孔子对孟孙才的深层阐释——颜回代表儒家礼仪的困惑者。"},{id:"meng_sun_cai",term:"孟孙才",pinyin:"mèng sūn cái",meaning:"鲁国贵族，庄子借以阐发「安时处顺」的得道境界。孟孙才：孟孙氏，名才，鲁国大夫。其母死而哭泣无涕·中心不戚·居丧不哀，却被称为善处丧——表面违礼，实则超越礼的形式，直达丧的本质。"},{id:"ti_lei",term:"涕",pinyin:"tì",meaning:"眼泪。涕：眼泪（古代「涕」专指眼泪，「泗」指鼻涕）。哭泣无涕：哭泣却没有眼泪——形式上哭，内心却无悲痛。"},{id:"zhong_xin_qi",term:"中心不戚",pinyin:"zhōng xīn bù qī",meaning:"内心不悲伤。中心：内心；不戚：不悲伤、不忧戚，读 qī。中心不戚：内心没有悲痛——超越情绪的执着。"},{id:"ju_sang_ai",term:"居丧不哀",pinyin:"jū sāng bù āi",meaning:"守丧期间不哀痛。居丧：守丧、服丧；不哀：不哀痛。哭泣无涕·中心不戚·居丧不哀：三者并举，从外（泪）到内（心）到行（丧），层层说明孟孙才超越世俗丧礼形式。"},{id:"shan_chu_sang",term:"无是三者，以善处丧",pinyin:"wú shì sān zhě yǐ shàn chǔ sāng",meaning:"没有这三者（涕·戚·哀），却以善于处理丧事（著称）。善处丧：善于处理丧事——世人认可其处丧之道，尽管形式上违反礼仪。"},{id:"gai_mingwen",term:"盖",pinyin:"gài",meaning:"盖过、名闻于（整个）。盖：超过、名闻，读 gài。盖鲁国：名闻于整个鲁国——孟孙才处丧之名传遍鲁国。"},{id:"wu_shi_de_ming",term:"有无其实而得其名者乎",pinyin:"yǒu wú qí shí ér dé qí míng zhě hū",meaning:"真的有没有实际（悲哀）却得到（善处丧）名声的人吗？无其实：没有实际的（悲哀）；得其名：得到（善处丧的）名声。颜回以为孟孙才是「名实不符」，实则孟孙才超越了名实的对立。"},{id:"hui_yi_guai",term:"回壹怪之",pinyin:"huí yī guài zhī",meaning:"我（颜回）实在对此感到奇怪。壹：实在、确实（副词，表强调）；怪之：对此感到奇怪。回壹怪之：我颜回实在觉得奇怪——颜回以礼仪眼光看孟孙才，自然困惑。"},{id:"jin_zhi_yi",term:"尽之矣",pinyin:"jìn zhī yǐ",meaning:"（孟孙才）已经做到极致了。尽：极致、尽善尽美；之：代词，指处丧之道；矣：语气词。夫孟孙氏尽之矣：孟孙才在处丧之道上已经做到极致了。"},{id:"jin_yu_zhi",term:"进于知矣",pinyin:"jìn yú zhī yǐ",meaning:"超越了（一般的）知识（智慧）了。进：超越、进一步；于知：超过知识层面；矣：语气词。进于知矣：超越了一般的知识层面——孟孙才的境界不是知识可以解释的。"},{id:"wei_suiran",term:"唯",pinyin:"wéi",meaning:"只是、虽然（表转折）。唯：只是、虽然，此处表转折。唯简之而不得：只是（虽然）想要再简省（某些东西）却做不到。"},{id:"jian_zhi_bude",term:"简之而不得",pinyin:"jiǎn zhī ér bù dé",meaning:"想要简省（某些东西）却做不到。简：简省、减去；之：代词，指某些形式（如哭泣）；不得：做不到。唯简之而不得：只是想再简省却做不到——孟孙才已尽量简省，但仍有不得不保留的形式（如随众人哭）。"},{id:"you_suo_jian",term:"夫已有所简矣",pinyin:"fū yǐ yǒu suǒ jiǎn yǐ",meaning:"他已经有所简省了。夫：发语词；已：已经；有所简：有所简省；矣：语气词。夫已有所简矣：他已经在形式上做了大量简省——哭泣无涕·中心不戚·居丧不哀，皆是简省的体现。"},{id:"zhi_jiu_xian",term:"不知就先",pinyin:"bù zhī jiù xiān",meaning:"不知道（生死）哪个在先。就：趋向、接近；先：在先、先来。不知就先：不知道生死哪个先来——超越对生死先后的执着。"},{id:"zhi_jiu_hou",term:"不知就后",pinyin:"bù zhī jiù hòu",meaning:"不知道（生死）哪个在后。就后：趋向在后。不知就先·不知就后：不知生死的先后顺序——超越时间顺序的执着，生死循环，无先无后。"},{id:"hua_wei_wu",term:"化为物",pinyin:"huà wéi wù",meaning:"（顺应造化）变化为（各种）事物。化：变化、随化；为物：成为（各种）事物。若化为物：就像（顺应造化）变化为各种事物一样。"},{id:"yi_er_deng",term:"以",pinyin:"yǐ",meaning:"而、来（连词，表目的或承接）。以待：来等待。若化为物，以待其所不知之化：就像变化为各种事物，来等待那不可知的变化。"},{id:"qi_suobu_zhi",term:"其",pinyin:"qí",meaning:"那（指示代词，指代不可知的变化）。其所不知之化：那不可知的变化——死亡、转化等未知的变化。"},{id:"yi_hu_eryi",term:"已乎",pinyin:"yǐ hū",meaning:"罢了（就这样了）。已：停止、就此；乎：语气词，表感叹或疑问。以待其所不知之化已乎：来等待那不可知的变化，就这样罢了——顺应变化，无需追问。"},{id:"wu_zhi_bu_hua",term:"恶知不化哉",pinyin:"wū zhī bù huà zāi",meaning:"怎么知道（自己）没有在变化呢？恶：怎么，读 wū；知：知道；不化：没有变化；哉：语气词。且方将化，恶知不化哉：正将要变化（死亡），怎么知道自己没在变化呢？方将不化，恶知已化哉：正将要不变化（生存），怎么知道自己没有已经变化了呢？——两句互文，说明变与不变皆不可知，无需执着。"},{id:"meng_wei_jue",term:"其梦未始觉者邪",pinyin:"qí mèng wèi shǐ jué zhě yé",meaning:"（我们）都是在梦中从未醒来的人吧！其：大概、恐怕；梦：梦境；未始觉：从未曾醒来；者邪：……的人吧。吾特与汝，其梦未始觉者邪：我和你，大概都是在梦中从未醒来的人吧——以梦喻人生，觉醒者（孟孙才）超越了生死，我们仍在梦中。"},{id:"hai_xing_sun_xin",term:"有骇形而无损心",pinyin:"yǒu hài xíng ér wú sǔn xīn",meaning:"形体受到（死亡的）惊扰，但内心没有损伤。骇形：形体受到惊扰（死亡使形体消散）；无损心：内心没有损伤。有骇形而无损心：形体虽死，心（本真）不损——形与心分离，死亡只是形体的变化。"},{id:"dan_zhai",term:"有旦宅",pinyin:"yǒu dàn zhái",meaning:"形体（住所）有更迭变换（如同早晨换了一个住所）。旦宅：早晨的住所，喻形体是暂时的居所，随时更换；旦：早晨（喻短暂）；宅：住所（喻形体）。有旦宅：形体只是暂时的居所，随时更换——死亡是换了一个住所，非永久消亡。"},{id:"wu_qing_si",term:"无情死",pinyin:"wú qíng sǐ",meaning:"没有（执着于）情感（而导致的）死（的痛苦）。无情死：不以情感执着面对死亡——死亡是自然变化，无需以情感执着去面对。有旦宅而无情死：形体只是暂时的居所（随时更换），死亡不是情感执着的终结——旦宅（形体）可换，情（执着）不死，真正的「无情死」是超越对死亡的情感执着。"},{id:"te_jin_meng",term:"特",pinyin:"tè",meaning:"只是、独自（副词，表限定）。孟孙氏特觉：孟孙才只是（独自）觉醒了——在众人皆梦的世界中，孟孙才是独自觉醒者。"},{id:"jue_xingwu",term:"觉",pinyin:"jué",meaning:"觉醒、醒悟。觉：从梦中醒来，喻超越世俗执着的觉悟。孟孙氏特觉：孟孙才独自觉醒——超越了生死执着。"},{id:"zi_qi_suo_nai",term:"是自其所以乃",pinyin:"shì zì qí suǒ yǐ nǎi",meaning:"这是顺应他自身（处境）的自然而然。是：这；自：顺应、出于；其所以：他的（处境）原因；乃：自然而然。人哭亦哭，是自其所以乃：别人哭他也哭，这是顺应自身处境的自然而然——孟孙才随众人哭，非出于悲痛，而是顺应外在处境。"},{id:"wu_zhi_wei",term:"『吾之』",pinyin:"wú zhī",meaning:"「我」（以「我」来称呼自身）。吾之：以「吾」来指称自身（执着于「我」的概念）。且也相与『吾之』耳矣：大家不过都是互相以「我」来称呼自身罢了——「我」只是一个暂时的名称，并无固定的实体。"},{id:"yong_ju",term:"庸讵",pinyin:"yōng jù",meaning:"哪里、怎么能（表强烈反问）。庸：哪里、怎么；讵：岂、怎么，读 jù。庸讵知：哪里能知道——强调「吾之」（我）的概念本身无法被真正把握。"},{id:"li_tian",term:"厉乎天",pinyin:"lì hū tiān",meaning:"飞翔于天际（高飞入天）。厉：高飞、升腾，读 lì；乎：于。梦为鸟而厉乎天：梦见自己变成鸟飞翔于天际。"},{id:"mo_yuan",term:"没于渊",pinyin:"mò yú yuān",meaning:"沉入深渊之中。没：沉入、潜入；渊：深渊。梦为鱼而没于渊：梦见自己变成鱼沉入深渊。厉乎天·没于渊：天与渊，一上一下，极度对比——梦中可以是任何形态，正如死生变化，无固定形态。"},{id:"zao_shi_xiao",term:"造适不及笑",pinyin:"zào shì bù jí xiào",meaning:"（心境）刚刚到达适意，还来不及笑（就已变化）。造：到达；适：适意、舒适；不及笑：来不及笑——适意转瞬即逝，无法执着。"},{id:"xian_xiao_pai",term:"献笑不及排",pinyin:"xiàn xiào bù jí pái",meaning:"（刚刚）露出笑容，还来不及舒展（就已变化）。献笑：露出笑容；不及排：来不及舒展、排开；排：舒展、铺排。造适不及笑·献笑不及排：两句并举，以「笑」为喻，说明情绪与执着皆转瞬即逝，无从把握——既然如此，何必执着于哀乐？"},{id:"an_pai_qu_hua",term:"安排而去化",pinyin:"ān pái ér qù huà",meaning:"安然顺应（造化的）安排，随之而去（融入）变化。安排：安然接受安排、顺应；去化：随之而去，融入变化。安排而去化：安然顺应造化的安排，随化而去——不执着，不抗拒，顺应一切变化。"},{id:"nai_caineng",term:"乃",pinyin:"nǎi",meaning:"才能、于是（副词，表结果）。乃：才能、方能。安排而去化，乃入于寥天一：安然顺化，才能进入寥天一的境界。"},{id:"liao_tian_yi",term:"寥天一",pinyin:"liáo tiān yī",meaning:"寥廓天道的浑然一体（道的终极境界）。寥：寥廓、空旷；天：天道、自然；一：浑然一体、道的整体。寥天一：天道的寥廓浑一——超越一切分别，与道融为一体的最高境界。安排而去化，乃入于寥天一：安然顺化，才能进入这寥廓天道浑然一体的境界——《大宗师》全篇的终极归宿。"}],v=[{id:"yi_s1",label:"意而子见许由……汝必躬服仁义而明言是非",sentences:[[{text:"意而子",glossary:"yi_er_zi"},"见",{text:"许由",glossary:"xu_you"},"，许由曰：「尧何以",{text:"资",glossary:"zi_zengyi"},"汝？」"],["意而子曰：「尧谓我：汝必",{text:"躬服仁义",glossary:"gong_fu_renyi"},"而",{text:"明言是非",glossary:"ming_yan_shifei"},"。」"]]},{id:"yi_s2",label:"许由曰而奚来为轵……之涂乎",sentences:[["许由曰：「而奚来为",{text:"轵",glossary:"zhi_hewei"},"？"],["夫尧",{text:"既已",glossary:"ji_yi"},{text:"黥汝",glossary:"qing_ru"},"以仁义，而",{text:"劓",glossary:"yi_bi"},"汝以是非矣。"],["汝将",{text:"何以游夫",glossary:"he_yi_you_fu"},{text:"遥荡",glossary:"yao_dang"},{text:"恣睢",glossary:"zi_sui"},{text:"转徙",glossary:"zhuan_xi"},"之",{text:"涂",glossary:"tu_lu"},"乎？」"]]},{id:"yi_s3",label:"意而子曰虽然吾愿游于其藩……瞽者无以与乎青黄黼黻之观",sentences:[["意而子曰：「虽然，吾愿游于其",{text:"藩",glossary:"fan_fanli"},"。」"],["许由曰：「不然。夫盲者",{text:"无以与乎",glossary:"wu_yi_yu"},{text:"眉目",glossary:"mei_mu_rong"},{text:"颜色",glossary:"yan_se_rong"},"之好，"],[{text:"瞽者",glossary:"gu_zhe"},"无以与乎",{text:"青黄黼黻",glossary:"qing_huang_fu_fu"},"之观。」"]]},{id:"yi_s4",label:"意而子曰夫无庄之失其美……使我乘成以随先生邪",sentences:[["意而子曰：「夫",{text:"无庄之失其美",glossary:"wu_zhuang_mei"},"，",{text:"据梁之失其力",glossary:"ju_liang_li"},"，",{text:"黄帝之亡其知",glossary:"huangdi_wang_zhi"},"，皆在",{text:"炉捶之间",glossary:"lu_chui"},"耳。"],[{text:"庸讵",glossary:"yong_ju_yi"},"知夫造物者之不",{text:"息我黥",glossary:"xi_wo_qing"},"而",{text:"补我劓",glossary:"bu_wo_yi"},"，使我",{text:"乘成",glossary:"cheng_cheng"},"以随先生邪？」"]]},{id:"yi_s5",label:"许由曰噫未可知也……此所游已",sentences:[["许由曰：「噫！未可知也。我为汝言其",{text:"大略",glossary:"da_lve"},"："],["吾师乎！吾师乎！",{text:"赍万物",glossary:"ji_wan_wu"},"而不为义，",{text:"泽及万世",glossary:"ze_ji_wan_shi"},"而不为仁，"],["长于上古而不为老，",{text:"覆载",glossary:"fu_zai"},"天地、",{text:"刻雕众形",glossary:"ke_diao_zhong_xing"},"而不为",{text:"巧",glossary:"qiao_wei_qiao"},"。"],[{text:"此所游已",glossary:"ci_suo_you_yi"},"！」"]]}],G=[{id:"yi_er_zi",term:"意而子",pinyin:"yì ér zǐ",meaning:"人名，庄子虚构的求道者。曾受尧的教化（躬服仁义·明言是非），后来向许由求道——代表被儒家礼法「刑伤」后仍寻求超越的人。"},{id:"xu_you",term:"许由",pinyin:"xǔ yóu",meaning:"传说中的上古隐士，尧欲让位于他而不受。许由：道家理想中超越世俗权位的真人，《逍遥游》中亦出现。此处作为得道者，指点意而子。"},{id:"zi_zengyi",term:"资",pinyin:"zī",meaning:"给予、资助（教给了什么）。资：给予、赠与。尧何以资汝：尧给了你什么（教了你什么）？"},{id:"gong_fu_renyi",term:"躬服仁义",pinyin:"gōng fú rén yì",meaning:"亲身践行仁义。躬：亲身、亲自；服：践行、服从；仁义：儒家核心道德。躬服仁义：亲身践行仁义——尧以儒家道德教化意而子。"},{id:"ming_yan_shifei",term:"明言是非",pinyin:"míng yán shì fēi",meaning:"明确地辨别（言说）是非。明言：明确言说；是非：对错、是非判断。躬服仁义·明言是非：两者并举，是儒家教化的核心——仁义（道德实践）与是非（价值判断）。"},{id:"zhi_hewei",term:"轵",pinyin:"zhǐ",meaning:"来此做什么（疑问词，表「为何」）。轵：读 zhǐ，语气词，表疑问「为何·做什么」。而奚来为轵：你为何来这里呢？——许由以此质问意而子来意，暗示被仁义是非「刑伤」之人难以游于大道。"},{id:"ji_yi",term:"既已",pinyin:"jì yǐ",meaning:"已经（完成某事）。既：已经；已：已经（两字叠用，强调完成）。尧既已黥汝以仁义：尧已经用仁义在你脸上刺字了。"},{id:"qing_ru",term:"黥汝",pinyin:"qíng rǔ",meaning:"在你脸上刺字（以仁义为刑）。黥：古代刑罚，在脸上刺字，读 qíng；汝：你。黥汝以仁义：用仁义在你脸上刺字——以「黥」喻仁义对人心的刻印束缚，是永久性的伤害。"},{id:"yi_bi",term:"劓",pinyin:"yì",meaning:"割去鼻子（以是非为刑）。劓：古代刑罚，割去鼻子，读 yì。劓汝以是非：用是非割去你的鼻子——以「劓」喻是非判断对人心的切割伤害。黥汝以仁义·劓汝以是非：两种古代酷刑并举，以极端的身体刑罚喻仁义是非对心灵的永久束缚——被儒家教化者，如同受刑，难以复原。"},{id:"he_yi_you_fu",term:"何以游夫",pinyin:"hé yǐ yóu fū",meaning:"凭什么遨游于那（大道之境）。何以：凭什么；游：遨游；夫：那（指示词）。汝将何以游夫……之涂乎：你将凭什么遨游于那……的道路呢？"},{id:"yao_dang",term:"遥荡",pinyin:"yáo dàng",meaning:"遥远广荡（自由自在的境界）。遥：遥远；荡：荡漾、广阔。遥荡：广阔自在的境界。"},{id:"zi_sui",term:"恣睢",pinyin:"zì suī",meaning:"自由放纵、无所拘束（此处为褒义，指自在无碍）。恣：放纵、自由；睢：任意，读 suī。恣睢：自在无拘——得道者游于大道的自由状态。"},{id:"zhuan_xi",term:"转徙",pinyin:"zhuǎn xǐ",meaning:"辗转迁移、自由流转。转：辗转；徙：迁移，读 xǐ。转徙：自由流转——随化而动，无固定形态。"},{id:"tu_lu",term:"涂",pinyin:"tú",meaning:"道路、途径。通「途」。遥荡恣睢转徙之涂：自由广阔、自在流转的道路（大道之境）。"},{id:"fan_fanli",term:"藩",pinyin:"fān",meaning:"藩篱、边界（外围）。藩：篱笆、边界，读 fān。吾愿游于其藩：我希望在（大道的）边界游历——意而子自知受仁义是非束缚，退而求其次，愿游于大道的外围。"},{id:"wu_yi_yu",term:"无以与乎",pinyin:"wú yǐ yù hū",meaning:"无法参与（欣赏）……。无以：没有办法；与：参与、欣赏；乎：于。盲者无以与乎眉目颜色之好：盲人无法欣赏眉目容色之美——以盲者·瞽者喻被仁义是非「刑伤」者，无法感知大道之美。"},{id:"mei_mu_rong",term:"眉目",pinyin:"méi mù",meaning:"眉毛与眼睛（面部容貌）。眉目颜色之好：眉目容色之美——视觉之美，盲者无法感知。"},{id:"yan_se_rong",term:"颜色",pinyin:"yán sè",meaning:"面色、容色（此处指容貌的色彩之美）。颜色：面色、容貌。眉目颜色之好：眉目容色之美。"},{id:"gu_zhe",term:"瞽者",pinyin:"gǔ zhě",meaning:"盲人（天生失明者）。瞽：天生盲目，读 gǔ；者：的人。瞽者无以与乎青黄黼黻之观：天生盲人无法欣赏青黄黼黻的色彩之美。盲者·瞽者：两种盲——盲者泛指失明，瞽者特指天生盲目，两者并举，强调「刑伤」的不可逆性。"},{id:"qing_huang_fu_fu",term:"青黄黼黻",pinyin:"qīng huáng fǔ fú",meaning:"青色·黄色·黼纹·黻纹（华美的色彩与纹饰）。青黄：颜色；黼：斧形纹饰，读 fǔ；黻：弓形纹饰，读 fú。青黄黼黻之观：华美色彩纹饰的视觉之美——瞽者无法欣赏。以「眉目颜色」·「青黄黼黻」喻大道之美，被仁义是非刑伤者如盲如瞽，无法感知。"},{id:"wu_zhuang_mei",term:"无庄之失其美",pinyin:"wú zhuāng zhī shī qí měi",meaning:"无庄失去了她的美貌。无庄：传说中的美女，读 wú zhuāng；失其美：失去了美貌——喻通过某种「炉捶」（修炼·造化）而超越了原有的执着。"},{id:"ju_liang_li",term:"据梁之失其力",pinyin:"jù liáng zhī shī qí lì",meaning:"据梁失去了他的力气。据梁：传说中的力士；失其力：失去了力气——喻通过「炉捶」而超越了对力量的执着。"},{id:"huangdi_wang_zhi",term:"黄帝之亡其知",pinyin:"huáng dì zhī wáng qí zhī",meaning:"黄帝失去了他的智慧（知识）。亡：失去；其知：他的智慧、知识。黄帝之亡其知：黄帝失去智慧——喻通过「炉捶」而超越了对知识的执着。无庄之失其美·据梁之失其力·黄帝之亡其知：三例并举，美·力·知皆可在「炉捶之间」失去（超越）——喻仁义是非的执着同样可以通过造化的「炉捶」而消除。"},{id:"lu_chui",term:"炉捶之间",pinyin:"lú chuí zhī jiān",meaning:"熔炉与锤打之间（造化锻造的过程中）。炉：熔炉；捶：锤打，读 chuí；之间：之间。炉捶之间：造化熔炼锤打的过程——喻造化可以改变一切，包括美·力·知，乃至仁义是非的刻印。"},{id:"yong_ju_yi",term:"庸讵",pinyin:"yōng jù",meaning:"哪里、怎么能（表强烈反问）。庸：哪里；讵：岂、怎么，读 jù。庸讵知：哪里能知道——意而子以此反问，表达对造化可能消除「黥劓」的希望。"},{id:"xi_wo_qing",term:"息我黥",pinyin:"xī wǒ qíng",meaning:"消除（平息）我脸上的刺字（仁义的束缚）。息：消除、平息；我黥：我（脸上）的刺字。不息我黥：不消除我的黥刑——造物者或许能消除仁义对我的束缚。"},{id:"bu_wo_yi",term:"补我劓",pinyin:"bǔ wǒ yì",meaning:"修补我被割去的鼻子（是非的伤害）。补：修补、恢复；我劓：我（被割去的）鼻子。不息我黥而补我劓：消除我的黥刑并修补我的劓刑——造物者或许能消除是非对我的伤害，使我恢复本真。"},{id:"cheng_cheng",term:"乘成",pinyin:"chéng chéng",meaning:"凭借（造化）成就（的完整状态）。乘：凭借；成：完成、成就（恢复完整）。使我乘成以随先生：使我凭借（造化）恢复完整，从而追随先生（许由）——意而子希望通过造化的修复，达到可以追随许由的境界。"},{id:"da_lve",term:"大略",pinyin:"dà lüè",meaning:"大概、大要（概略地说）。大略：大概的要点。我为汝言其大略：我为你大概说说（道的）要点。"},{id:"ji_wan_wu",term:"赍万物",pinyin:"jī wàn wù",meaning:"携带（给予）万物（一切）。赍：携带、给予，读 jī。赍万物而不为义：给予万物一切却不以此为「义」——道施予万物，却不以「义」自居。"},{id:"ze_ji_wan_shi",term:"泽及万世",pinyin:"zé jí wàn shì",meaning:"恩泽遍及万世（永恒）。泽：恩泽；及：到达；万世：万代、永恒。泽及万世而不为仁：恩泽遍及万世却不以此为「仁」——道惠及万世，却不以「仁」自居。赍万物而不为义·泽及万世而不为仁：道给予万物、惠及万世，却不以仁义自居——正是对儒家仁义的超越，道无名无为，远超仁义的范畴。"},{id:"fu_zai",term:"覆载",pinyin:"fù zài",meaning:"覆盖（天）与承载（地）。覆：覆盖（天覆）；载：承载（地载）。覆载天地：覆盖并承载天地——道包容天地，超越天地。"},{id:"ke_diao_zhong_xing",term:"刻雕众形",pinyin:"kè diāo zhòng xíng",meaning:"雕刻塑造万物的形态。刻雕：雕刻、塑造；众形：万物的各种形态。刻雕众形而不为巧：塑造万物形态却不以此为「巧」——道创造万物，却不以「巧」自居。"},{id:"qiao_wei_qiao",term:"巧",pinyin:"qiǎo",meaning:"技巧、巧妙（以技巧自居）。不为巧：不以此为技巧——道的创造超越技巧，无需以「巧」标榜。赍万物不为义·泽及万世不为仁·长于上古不为老·覆载天地不为高深·刻雕众形不为巧：五「不为」并举，与第六节「道之本体」的四「不为」（不为高·不为深·不为久·不为老）相呼应，共同描绘道超越一切人间价值标准的本质。"},{id:"ci_suo_you_yi",term:"此所游已",pinyin:"cǐ suǒ yóu yǐ",meaning:"这就是（吾师）所遨游的境界了。此：这；所游：所遨游之处；已：语气词，表确定（就是了）。此所游已：这就是道所游历的境界——许由以「吾师乎」描绘道的境界，以「此所游已」收束，指出这才是真正值得遨游的地方，远超仁义是非的藩篱。"}],D=[{id:"zuo_s1",label:"颜回曰回益矣……犹未也（忘仁义·忘礼乐）",sentences:[["颜回曰：「",{text:"回益矣",glossary:"hui_yi_yi"},"。」仲尼曰：「何谓也？」"],["曰：「回忘仁义矣。」曰：「",{text:"可矣，犹未也",glossary:"ke_you_wei"},"。」"],["他日复见，曰：「回益矣。」曰：「何谓也？」"],["曰：「回忘礼乐矣！」曰：「可矣，犹未也。」"]]},{id:"zuo_s2",label:"他日复见回益矣……何谓坐忘",sentences:[["他日复见，曰：「回益矣！」曰：「何谓也？」"],["曰：「回",{text:"坐忘",glossary:"zuo_wang"},"矣。」"],["仲尼",{text:"蹴然",glossary:"cu_ran"},"曰：「何谓坐忘？」"]]},{id:"zuo_s3",label:"颜回曰堕肢体……此谓坐忘",sentences:[["颜回曰：「",{text:"堕肢体",glossary:"duo_zhi_ti"},"，",{text:"黜聪明",glossary:"chu_cong_ming"},"，",{text:"离形去知",glossary:"li_xing_qu_zhi"},"，",{text:"同于大通",glossary:"tong_da_tong"},"，此谓坐忘。」"]]},{id:"zuo_s4",label:"仲尼曰同则无好也……丘也请从而后也",sentences:[["仲尼曰：「",{text:"同则无好也",glossary:"tong_wu_hao"},"，",{text:"化则无常也",glossary:"hua_wu_chang"},"。"],[{text:"而果其贤乎",glossary:"er_guo_xian"},"！丘也",{text:"请从而后也",glossary:"qing_cong_hou"},"。」"]]}],C=[{id:"hui_yi_yi",term:"回益矣",pinyin:"huí yì yǐ",meaning:"我（颜回）有进益了（又进步了）。益：进步、增益；矣：语气词，表确定。回益矣：颜回自报进境——三次「回益矣」层层递进，每次忘却更深一层（仁义→礼乐→坐忘）。"},{id:"ke_you_wei",term:"可矣，犹未也",pinyin:"kě yǐ yóu wèi yě",meaning:"可以了，但还不够。可矣：可以了、不错了；犹未也：但尚且还不够、还未到（最终境界）。可矣，犹未也：两次重复，表示忘仁义·忘礼乐皆是进步，但仍未达到最终境界——层层递进，为「坐忘」的出现蓄势。"},{id:"zuo_wang",term:"坐忘",pinyin:"zuò wàng",meaning:"端坐而忘却一切（身心俱忘的冥想境界）。坐：端坐；忘：忘却。坐忘：静坐中忘却形体与知识，超越自我与外物的对立，与道合一——《大宗师》最核心的修道概念，也是庄子哲学中最高的精神境界之一。"},{id:"cu_ran",term:"蹴然",pinyin:"cù rán",meaning:"惊讶肃然的样子（震惊而恭敬）。蹴：惊动、震惊，读 cù；然：……的样子。仲尼蹴然：孔子惊讶肃然——孔子被颜回的「坐忘」所震动，由师转为学生，反映庄子对儒家的超越性诠释。"},{id:"duo_zhi_ti",term:"堕肢体",pinyin:"duò zhī tǐ",meaning:"忘却（放下）肢体（形体的执着）。堕：放下、忘却，读 duò（通「惰」，此处为使动，使……堕落·放下）；肢体：四肢身体。堕肢体：放下对形体的执着——超越身体的感知与束缚。"},{id:"chu_cong_ming",term:"黜聪明",pinyin:"chù cōng míng",meaning:"摒除聪明（感官与智识）。黜：摒除、废黜，读 chù；聪明：耳聪目明，指感官知觉与智识。黜聪明：摒除感官知觉与智识的执着——超越耳目聪明的束缚。堕肢体·黜聪明：一「堕」一「黜」，分别超越形体（外）与感官智识（内）——由外到内，层层放下。"},{id:"li_xing_qu_zhi",term:"离形去知",pinyin:"lí xíng qù zhī",meaning:"脱离形体，去除知识（执着）。离形：脱离形体的束缚；去知：去除知识·智慧的执着。离形去知：同时超越形体与知识——是「堕肢体·黜聪明」的深化与总结。堕肢体·黜聪明·离形去知：三层递进，由「放下」到「摒除」到「脱离·去除」，动作逐渐彻底，指向完全的超越。"},{id:"tong_da_tong",term:"同于大通",pinyin:"tóng yú dà tōng",meaning:"与大通（道）融为一体。同：同一、融合；于：与；大通：道的别称，指浑然贯通的大道。同于大通：与道融为一体——坐忘的最终境界，超越一切分别，与道合一。离形去知，同于大通：脱离形体、去除知识，方能与道融为一体——「坐忘」的完整定义：堕肢体→黜聪明→离形去知→同于大通，四步递进，层层深入。"},{id:"tong_wu_hao",term:"同则无好也",pinyin:"tóng zé wú hào yě",meaning:"与道同一则没有（个人的）偏好了。同：与道同一（坐忘后的状态）；无好：没有偏好、好恶；也：语气词。同则无好也：与道合一，则超越了个人的偏好——无好恶，无执着。"},{id:"hua_wu_chang",term:"化则无常也",pinyin:"huà zé wú cháng yě",meaning:"随化变化则没有（固定的）常规了。化：随造化变化；无常：没有固定常规、不执着于常。化则无常也：随化而变，则超越了固定的常规——无常，无执，自在流转。同则无好也·化则无常也：两句并举，「同」（与道合一）→无好，「化」（随化流转）→无常——坐忘的两个维度：静（同·无好）与动（化·无常）。"},{id:"er_guo_xian",term:"而果其贤乎",pinyin:"ér guǒ qí xián hū",meaning:"你果真是贤于我（胜过我）啊！而：你；果：果真；其贤：贤于（胜过）；乎：语气词，表感叹。而果其贤乎：你果真胜过我了——孔子承认颜回的境界超越了自己，是全篇最动人的转折：师拜弟子，儒家最高弟子反超儒家之师，庄子以此点明「坐忘」超越了儒家的一切修养。"},{id:"qing_cong_hou",term:"请从而后也",pinyin:"qǐng cóng ér hòu yě",meaning:"请允许我跟随你（走在你后面）。请：请允许；从：跟随；而后：在你后面（落后于你）；也：语气词。丘也请从而后也：我孔丘请求跟随你走在你后面——孔子甘愿拜颜回为师，以「后」字表谦逊，承认颜回已超越自己。此句是《大宗师》全篇的终结，以孔子的「请从而后」收束，呼应开篇「真人」的境界——真正的大宗师，不在外部，而在「坐忘·同于大通」的内在超越。"}],N=[{id:"sang_yu_s1",label:"子舆与子桑友……裹饭而往食之",sentences:[["子舆与子桑友。而",{text:"霖雨",glossary:"lin_yu"},"十日，子舆曰：「子桑",{text:"殆病矣",glossary:"dai_bing"},"！」",{text:"裹",glossary:"guo_bao"},"饭而往食之。"]]},{id:"sang_yu_s2",label:"至子桑之门……有不任其声而趋举其诗焉",sentences:[["至子桑之门，则若歌若哭，鼓琴曰：「父邪！母邪！天乎！人乎！」"],["有",{text:"不任其声",glossary:"bu_ren_sheng"},"而",{text:"趋举其诗",glossary:"qu_ju_shi"},"焉。"]]},{id:"sang_yu_s3",label:"子舆入……命也夫",sentences:[["子舆入，曰：「子之歌诗，",{text:"何故若是",glossary:"he_gu_ru_shi"},"？」"],["曰：「吾思夫使我",{text:"至此极者",glossary:"zhi_ci_ji"},"而",{text:"弗得也",glossary:"fu_de"},"。"],["父母岂欲吾",{text:"贫",glossary:"pin_qionku"},"哉？"],["天无",{text:"私",glossary:"si_piansi"},{text:"覆",glossary:"fu_fugai"},"，地无私",{text:"载",glossary:"zai_chengzai"},"，天地岂私贫我哉？"],["求其为之者而不得也！然而至此极者，",{text:"命也夫",glossary:"ming_ye_fu"},"！」"]]}],V=[{id:"lin_yu",term:"霖雨",pinyin:"lín yǔ",meaning:"连绵不断的大雨。霖：连续下雨，读 lín；雨：雨。霖雨十日：连续下了十天大雨——子桑处境极度困苦（无食·受寒）的自然背景。"},{id:"dai_bing",term:"殆病矣",pinyin:"dài bìng yǐ",meaning:"恐怕病了。殆：恐怕、大概；病：生病；矣：语气词，表推测确定。子桑殆病矣：子桑恐怕病了——子舆的关切，引出裹饭往食的行动。"},{id:"guo_bao",term:"裹",pinyin:"guǒ",meaning:"包裹、包好。裹饭：包好饭食。裹饭而往食之：包好饭食前往喂他——「食之」（喂他吃），可见子桑已虚弱到无法自食。"},{id:"bu_ren_sheng",term:"不任其声",pinyin:"bù rèn qí shēng",meaning:"声音支撑不住（气力不足以维持歌声）。不任：承受不住、支撑不了；其声：他的声音。有不任其声：（歌声中）有支撑不住声音（的虚弱感）——子桑病弱至极，歌声断续，却仍鼓琴而歌。"},{id:"qu_ju_shi",term:"趋举其诗",pinyin:"qū jǔ qí shī",meaning:"勉强撑起（完成）那歌诗。趋：急促、勉强；举：举起、完成；其诗：那歌诗（所唱的诗句）。不任其声而趋举其诗：声音支撑不住却勉强撑完那歌诗——以「不任」与「趋举」的张力，描绘子桑在极度困苦中仍坚持歌唱的状态。"},{id:"he_gu_ru_shi",term:"何故若是",pinyin:"hé gù ruò shì",meaning:"为何（歌声）如此（这般）？何故：为何、什么缘故；若是：如此、这般。子之歌诗，何故若是：你唱的歌诗，为何如此（若歌若哭）？"},{id:"zhi_ci_ji",term:"至此极者",pinyin:"zhì cǐ jí zhě",meaning:"使我到达这种极度（困境）的（原因·力量）。至此极：到达这种极度困苦；者：……的（原因）。吾思夫使我至此极者：我思索那使我到达这种极度困境的（原因）——子桑追问贫困的根源，却找不到答案。"},{id:"fu_de",term:"弗得也",pinyin:"fú dé yě",meaning:"却找不到（得不到答案）。弗：不；得：找到、得到；也：语气词。而弗得也：却找不到——三次追问（父母·天地·为之者）皆弗得，最终归于「命也夫」。"},{id:"pin_qionku",term:"贫",pinyin:"pín",meaning:"贫困、穷苦。父母岂欲吾贫哉：父母难道希望我贫困吗？——排除父母的主观意愿，非父母之过。"},{id:"si_piansi",term:"私",pinyin:"sī",meaning:"偏私、私心（偏袒某人）。天无私覆·地无私载：天没有偏私地覆盖，地没有偏私地承载——天地对万物一视同仁，无偏袒。天地岂私贫我哉：天地难道偏私地使我贫困吗？——排除天地的主观意愿，非天地之过。"},{id:"fu_fugai",term:"覆",pinyin:"fù",meaning:"覆盖（天覆盖万物）。天无私覆：天没有偏私地覆盖（一视同仁）。"},{id:"zai_chengzai",term:"载",pinyin:"zài",meaning:"承载（地承载万物）。地无私载：地没有偏私地承载（一视同仁）。覆·载：天覆地载，呼应第五节「大块载我以形」——天地无私，万物皆在其中，贫困非天地之私。"},{id:"ming_ye_fu",term:"命也夫",pinyin:"mìng yě fū",meaning:"是命啊！命：天命、自然的命运；也：判断语气；夫：语气词，表感叹，读 fū。命也夫：是命啊——三问（父母·天地·为之者）皆无答案，最终归结于「命」。与第四节「死生，命也」相呼应：命不是消极的宿命，而是超越人力所能追问的自然规律——既然无从追问，便顺应之，安时处顺。"}];return(L,i)=>{const R=r("DaoReadingPrelude"),t=r("DaoTextReading"),s=r("DaoKeywordCards"),g=r("DaoLineGuide");return A(),B("div",null,[i[0]||(i[0]=n("h1",{id:"庄子·大宗师",tabindex:"-1"},[e("庄子·大宗师 "),n("a",{class:"header-anchor",href:"#庄子·大宗师","aria-label":'Permalink to "庄子·大宗师"'},"​")],-1)),i[1]||(i[1]=n("h2",{id:"篇名释义",tabindex:"-1"},[e("篇名释义 "),n("a",{class:"header-anchor",href:"#篇名释义","aria-label":'Permalink to "篇名释义"'},"​")],-1)),i[2]||(i[2]=n("blockquote",null,[n("p",null,[n("strong",null,"大宗师——那个最根本的、值得效法的宗主。")]),n("p",null,"「大」：最高的、根本的；「宗」：宗主、根源、所归依的；「师」：老师、效法的对象。"),n("p",null,[e("不是某个人，而是"),n("strong",null,"道本身"),e("。《大宗师》全篇，就是在回答一个问题：什么是值得我们效法的最高存在？答案是道——那个「自本自根，未有天地，自古以固存」的道，那个「赍万物而不为义，泽及万世而不为仁」的道，那个「可传而不可受，可得而不可见」的道。")])],-1)),a(R,{title:"从真人三论到撄宁七阶、坐忘与命也夫",summary:"《大宗师》是内篇七篇的枢纽与高峰。它正面展开道的本体与真人的境界：真人是什么样的人（描述·定义），道是什么（本体·宇宙论），如何得道（路径·方法），真实的人如何面对（寓言·人间）。",points:[{label:"先看",text:"顺着真人论（1-3）、道论（4-6）、得道之路（7）、寓言群像（8-13）四个部分走一遍。"},{label:"再问",text:"撄宁七阶与坐忘，分别给出了怎样的修道路径？"},{label:"最后",text:"「命也夫」——为什么在穷尽追问之后说出的「命」，才是真实的安命？"}],hint:"这是内篇哲学浓度最高的篇章之一。第一次读不必逐句求通，先把真人、道、撄宁、坐忘、命这几个核心意象立住。"}),i[3]||(i[3]=n("h2",{id:"一、天人之知·有真人而后有真知",tabindex:"-1"},[e("一、天人之知·有真人而后有真知 "),n("a",{class:"header-anchor",href:"#一、天人之知·有真人而后有真知","aria-label":'Permalink to "一、天人之知·有真人而后有真知"'},"​")],-1)),i[4]||(i[4]=n("h3",{id:"原文",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:y,glossary:_,"default-mode":"classic","aria-label":"大宗师·天人之知 原文"}),i[5]||(i[5]=n("h3",{id:"生僻字词",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"知天之所为",pinyin:["zhī","tiān","zhī","suǒ","wéi"],meaning:"知道什么是天（自然）的作为。天之所为：自然而然、不由人力的那部分。"},{term:"知人之所为",pinyin:["zhī","rén","zhī","suǒ","wéi"],meaning:"知道什么是人的作为。人之所为：人力可以把握、可以努力的那部分。"},{term:"至矣",pinyin:["zhì","yǐ"],meaning:"达到极致了，是最高的境界。"},{term:"庸讵知",pinyin:["yōng","jù","zhī"],meaning:"怎么能知道……？庸：岂、难道；讵：怎么、哪里。两字合用，表示强烈的反问。"},{term:"真人",pinyin:["zhēn","rén"],meaning:"道家理想人格的最高境界。有真人而后有真知：先有真人，才有真知。"},{term:"真知",pinyin:["zhēn","zhī"],meaning:"真正的、与道合一的知识。知识来自存在状态的转化，不来自积累。"}]}),i[6]||(i[6]=n("h3",{id:"核心句引读",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"有真人而后有真知",subtitle:"知识本身是有局限的；只有先成为真人，他的知识才是真正的知识。",lines:[{text:"知天之所为，知人之所为者，至矣！",tone:"开篇",guide:"《大宗师》开篇，庄子直接抛出了全篇最核心的问题：什么是天？什么是人？这不是一个简单的分类问题，而是一个关于认知边界的根本追问。能同时知道这两者，就是最高的境界。但庄子马上说：虽然，有患。"},{text:"夫知有所待而后当，其所待者特未定也。",tone:"质疑",guide:"这是全段最深刻的一句话，也是庄子对「知识」最根本的质疑：所有的判断，都需要一个依凭才能成立——但那个依凭本身，是不确定的。我说「这是天的作为」——但我凭什么知道这是天而不是人？判断「天」与「人」的标准，本身就是不稳定的。人的知识，永远依赖于某个前提；而那个前提，本身就是可疑的。"},{text:"且有真人而后有真知。",tone:"结论",guide:"这是全段的结论，也是《大宗师》全篇的逻辑起点。这句话的逻辑，与我们通常的认知方向相反：通常我们以为先有知识才能成为真人；庄子说：知识本身是有局限的（知有所待而后当），只有先成为真人——与道合一的人——他的知识才是真正的知识。这不是反智，而是对「知识的来源」的根本追问：真正的知，不来自积累，而来自存在状态的转化。"}]}),i[7]||(i[7]=n("h2",{id:"二、真人三论",tabindex:"-1"},[e("二、真人三论 "),n("a",{class:"header-anchor",href:"#二、真人三论","aria-label":'Permalink to "二、真人三论"'},"​")],-1)),i[8]||(i[8]=n("h3",{id:"原文-1",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-1","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:m,glossary:o,"default-mode":"classic","aria-label":"大宗师·真人三论 原文"}),i[9]||(i[9]=n("h3",{id:"生僻字词-1",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-1","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"不逆寡",pinyin:["bù","nì","guǎ"],meaning:"不因为自己势单力薄而抗拒。逆：抗拒、违逆；寡：少数、势弱。"},{term:"不雄成",pinyin:["bù","xióng","chéng"],meaning:"不以成功自雄（不以成就来炫耀自己）。雄：自以为雄，骄傲自大。"},{term:"不谟士",pinyin:["bù","mó","shì"],meaning:"不谋划事情（不刻意筹谋）。谟：谋划、筹谋；士：事情。"},{term:"过而弗悔",pinyin:["guò","ér","fú","huǐ"],meaning:"犯了过失不懊悔。弗：不。"},{term:"当而不自得",pinyin:["dāng","ér","bù","zì","dé"],meaning:"做对了事不沾沾自喜。自得：自我满足、沾沾自喜。"},{term:"息以踵",pinyin:["xī","yǐ","zhǒng"],meaning:"气息深入到脚跟（生命的根基）。真人之息以踵：气息绵长深沉，不浮于表面。"},{term:"耆欲",pinyin:["qí","yù"],meaning:"嗜欲、深重的欲望。其耆欲深者，其天机浅：欲望越深，天赋灵机越浅。"},{term:"天机",pinyin:["tiān","jī"],meaning:"天赋的灵性与生机，与道相通的内在感知力。"},{term:"翛然",pinyin:["xiāo","rán"],meaning:"自由自在、无拘无束的样子。翛然而往，翛然而来：自由地来去，不执着。"}]}),i[10]||(i[10]=n("h3",{id:"核心句引读-1",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-1","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"真人不执着于结果的好坏，不执着于自我的得失",subtitle:"真人不是没有情感，而是情感像四季一样自然流动。",lines:[{text:"古之真人，不逆寡，不雄成，不谟士。若然者，过而弗悔，当而不自得也。",tone:"三不",guide:"真人第一论，庄子用三个「不」来定义：不逆寡（不因势单力薄而抗拒）、不雄成（不以成功自雄）、不谟士（不刻意谋划）。这三个「不」，指向同一件事：真人不执着于结果的好坏，不执着于自我的得失。所以过而弗悔（犯了错，不懊悔——因为懊悔是执着于「我本可以做得更好」），当而不自得（做对了，不沾沾自喜——因为自得是执着于「我做对了」）。"},{text:"真人之息以踵，众人之息以喉。",tone:"深度",guide:"这是《大宗师》中最著名的一句话，也是最难解的一句：真人的气息深入到脚跟，众人的气息只到喉咙。字面上，这当然不是生理描述。这是一个关于生命深度的比喻：喉咙是表面，脚跟是根基。众人的生命停留在表面的反应——看见好的就喜，看见坏的就怒，被外物牵着走；真人的生命扎根于最深处——外物在表面涌动，根基始终稳定。"},{text:"其耆欲深者，其天机浅。",tone:"因果",guide:"这是全段最精炼的一句因果判断：欲望越深，天机越浅。天机：天赋的灵性与生机——那个与道相通的内在感知力。欲望占据的空间越多，那个与道相通的内在空间就越小。不是说欲望本身是坏的，而是说：欲望是一种消耗——消耗那个原本可以与道相通的内在空间。"},{text:"古之真人，不知说生，不知恶死。其出不欣，其入不距。翛然而往，翛然而来而已矣。",tone:"生死",guide:"这是真人第三论最核心的一段，也是《大宗师》全篇最重要的命题：真人不喜欢活着，也不厌恶死亡。不是麻木，不是冷漠，而是生与死，对真人来说，不是对立的两极，而是同一个流动的过程。其出不欣（来到世间，不欣喜——因为「来」不是得到），其入不距（离开世间，不抗拒——因为「去」不是失去）。翛然而往，翛然而来——就像风来风去，没有执着，没有留恋，没有抗拒。"},{text:"是之谓不以心捐道，不以人助天，是之谓真人。",tone:"定义",guide:"这是真人的终极定义，两个「不」：不以心捐道（不用心智去背离道——不用聪明去对抗自然），不以人助天（不用人为去帮助天然——不用努力去强化自然）。两个方向的「不干预」：不用心智破坏道，也不用努力强化道——只是顺应，只是在，只是翛然往来。"},{text:"凄然似秋，暖然似春，喜怒通四时，与物有宜而莫知其极。",tone:"气象",guide:"这是真人外在气象的最美描述：凄然似秋（有秋天的肃穆清明——清冷而不冷漠），暖然似春（有春天的温润生机——温暖而不热烈），喜怒通四时（情感如四季流转——自然流动，不执着于任何一种状态），与物有宜而莫知其极（与万物相处恰到好处，没有人知道他的边界）。真人不是没有情感，而是情感像四季一样自然流动——该冷时冷，该暖时暖，没有执着，没有强迫。"}]}),i[11]||(i[11]=n("h2",{id:"三、真人之状·天与人不相胜",tabindex:"-1"},[e("三、真人之状·天与人不相胜 "),n("a",{class:"header-anchor",href:"#三、真人之状·天与人不相胜","aria-label":'Permalink to "三、真人之状·天与人不相胜"'},"​")],-1)),i[12]||(i[12]=n("h3",{id:"原文-2",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-2","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:l,glossary:d,"default-mode":"classic","aria-label":"大宗师·真人之状 原文"}),i[13]||(i[13]=n("h3",{id:"生僻字词-2",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-2","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"觚",pinyin:["gū"],meaning:"有棱角的器物，比喻有原则。与乎其觚而不坚也：棱角分明却不固执。"},{term:"邴邴",pinyin:["bǐng","bǐng"],meaning:"神采奕奕、欢快的样子。邴邴乎其似喜也：神采奕奕，好像很喜悦。"},{term:"崔崔",pinyin:["cuī","cuī"],meaning:"高峻的样子。崔崔乎其不得已也：高峻挺立，一切都出于不得已（非刻意）。"},{term:"不相胜",pinyin:["bù","xiāng","shèng"],meaning:"不相互压制。天与人不相胜：天道与人间各有其位，不需要互相胜过。"}]}),i[14]||(i[14]=n("h3",{id:"核心句引读-2",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-2","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"天与人不相胜，是之谓真人",subtitle:"真人能同时在天道与人间两个层面自由游走。",lines:[{text:"以刑为体，以礼为翼，以知为时，以德为循。",tone:"四维",guide:"这四句，是真人处世的四个维度：刑是体（骨架）——内在的，不显于外；礼是翼（翅膀）——外在的工具，用于行世；知是时（时机）——被动的，不得已才用；德是循（遵循）——自然的，不是刻意的。真人不是没有规范、没有礼仪、没有智慧、没有德行——而是这四者在他那里，都是自然的、不刻意的。"},{text:"故其好之也一，其弗好之也一。其一也一，其不一也一。其一与天为徒，其不一与人为徒，天与人不相胜也，是之谓真人。",tone:"终极",guide:"这是第三段的终极结论，也是《大宗师》真人论最深的一句：好与不好，都是一；一与不一，也都是一。这不是文字游戏，而是对「执着」的彻底消解。普通人喜欢某事时执着于喜欢，不喜欢时执着于不喜欢——两种执着；真人在任何状态下都是同一种自然状态——无执着。「其一与天为徒，其不一与人为徒」——当他统一万物（齐物）时，他与天道同行；当他不统一（顺应人间差异）时，他与人间同行。天与人不相胜——天道与人间，不是对立的，不需要互相压倒。真人能同时在这两个层面自由游走——这才是真正的真人。"}]}),i[15]||(i[15]=n("h2",{id:"四、死生命也·相濡以沫不如相忘于江湖",tabindex:"-1"},[e("四、死生命也·相濡以沫不如相忘于江湖 "),n("a",{class:"header-anchor",href:"#四、死生命也·相濡以沫不如相忘于江湖","aria-label":'Permalink to "四、死生命也·相濡以沫不如相忘于江湖"'},"​")],-1)),i[16]||(i[16]=n("h3",{id:"原文-3",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-3","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:u,glossary:h,"default-mode":"classic","aria-label":"大宗师·相忘于江湖 原文"}),i[17]||(i[17]=n("h3",{id:"生僻字词-3",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-3","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"泉涸",pinyin:["quán","hé"],meaning:"泉水干涸。涸：干涸、枯竭。"},{term:"相呴以湿",pinyin:["xiāng","xǔ","yǐ","shī"],meaning:"互相用湿气呵护对方。呴：呵气、吐气。"},{term:"相濡以沫",pinyin:["xiāng","rú","yǐ","mò"],meaning:"互相用唾沫润湿对方。濡：沾湿、润湿；沫：唾沫。"},{term:"相忘于江湖",pinyin:["xiāng","wàng","yú","jiāng","hú"],meaning:"在江湖中彼此相忘，各自自由，不需要互相依赖。"}]}),i[18]||(i[18]=n("h3",{id:"核心句引读-3",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-3","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"相濡以沫，不如相忘于江湖",subtitle:"相濡以沫是困境中的温情，相忘于江湖是回归本然的自由。",lines:[{text:"死生，命也；其有夜旦之常，天也。人之有所不得与，皆物之情也。",tone:"定性",guide:"这三句，是《大宗师》对死生问题最简洁的定性：死生是命——不是惩罚，不是奖赏，不是因果报应，只是命，只是那个不由人力决定的东西。死生像昼夜交替一样，有其自然的规律。有些事，人根本无法参与、无法干预——这不是失败，不是无能，这是「物之情」——事物本来的情状。庄子在这里做了一件重要的事：把死生从「道德问题」还原为「自然问题」。"},{text:"泉涸，鱼相与处于陆，相呴以湿，相濡以沫，不如相忘于江湖。",tone:"意象",guide:"这是《庄子》全书最著名的意象之一，今天「相濡以沫」已成为汉语中形容患难深情的成语——但庄子的原意，恰恰相反。庄子说：相濡以沫，不如相忘于江湖。泉水干涸，鱼儿困在陆地上——它们互相用湿气、用唾沫润湿对方，这是极深的情谊，极大的努力——但这一切，都是因为它们失去了江湖。如果有江湖，它们根本不需要相濡以沫——在江湖里，彼此相忘，各自自在，才是真正的好。庄子用这个意象，说的是：那些看起来感人的「相互依赖」，往往是因为失去了更根本的东西。"},{text:"与其誉尧而非桀也，不如两忘而化其道。",tone:"两忘",guide:"这句话，是「相濡以沫」意象的直接延伸：称颂尧（善）、批判桀（恶）——这是儒家的基本立场，也是世俗道德的基本操作。庄子说：不如两忘。不是说尧和桀没有区别，而是说：执着于「誉尧非桀」这件事本身，就像相濡以沫——是失去了江湖之后的困境之举。回到道，把善恶的对立都融化掉——这才是真正的「化其道」。这与《齐物论》的「两行」是同一个境界：不是消灭差异，而是不执着于差异。"}]}),i[19]||(i[19]=n("h2",{id:"五、大块载我·藏天下于天下",tabindex:"-1"},[e("五、大块载我·藏天下于天下 "),n("a",{class:"header-anchor",href:"#五、大块载我·藏天下于天下","aria-label":'Permalink to "五、大块载我·藏天下于天下"'},"​")],-1)),i[20]||(i[20]=n("h3",{id:"原文-4",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-4","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:p,glossary:x,"default-mode":"classic","aria-label":"大宗师·藏天下于天下 原文"}),i[21]||(i[21]=n("h3",{id:"生僻字词-4",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-4","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"大块",pinyin:["dà","kuài"],meaning:"大地、天地、造化。大块载我以形，劳我以生，佚我以老，息我以死：造化用形载我、以生劳我、以老佚我、以死息我。"},{term:"藏舟于壑",pinyin:["cáng","zhōu","yú","hè"],meaning:"把船藏在山谷里。藏舟于壑，藏山于泽，谓之固矣：以为藏得很稳固。"},{term:"藏山于泽",pinyin:["cáng","shān","yú","zé"],meaning:"把山藏在大泽里。比喻任何试图「固定」的东西，都终将流失。"},{term:"善妖善老",pinyin:["shàn","yāo","shàn","lǎo"],meaning:"善待夭折，善待衰老。妖：通「夭」，夭折、早死。"},{term:"善始善终",pinyin:["shàn","shǐ","shàn","zhōng"],meaning:"善待开始，善待终结。对待生命的全程，皆是造化的恩赐。"}]}),i[22]||(i[22]=n("h3",{id:"核心句引读-4",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-4","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"善吾生者，乃所以善吾死也",subtitle:"生与死，是同一件事的两面——来是恩赐，去也是恩赐。",lines:[{text:"夫大块载我以形，劳我以生，佚我以老，息我以死。故善吾生者，乃所以善吾死也。",tone:"恩赐",guide:"这是《大宗师》中最温柔的一段话，也是庄子对生命最深的感恩：大地（造化）给了我什么？载我以形（给了我这副身体——让我有形可居），劳我以生（让我在生命中劳作——让我有事可做），佚我以老（用衰老给我安逸——让我有息可歇），息我以死（用死亡给我休息——让我有归可返）。四个动词：载、劳、佚、息——这不是苦难的清单，而是恩赐的清单。庄子把生命的全部过程——包括衰老和死亡——都看作造化对我们的善待。所以：善吾生者，乃所以善吾死也。"},{text:"夫藏舟于壑，藏山于泽，谓之固矣！然而夜半有力者负之而走，昧者不知也。",tone:"藏舟",guide:"这是《大宗师》中最震撼的一个比喻：把船藏在山谷——很稳固；把山藏在大泽——更稳固；但半夜，有力气的人把它背走了。「有力者」是谁？——造化、时间、变化本身。你以为藏得很稳固——但造化的力量，可以在你浑然不觉的时候，把你以为最稳固的东西带走。这个比喻指向一个根本的事实：任何你试图「固定」的东西，都终将流失。「昧者不知也」——糊涂的人浑然不觉，以为自己拥有的东西是稳固的。"},{text:"若夫藏天下于天下而不得所循，是恒物之大情也。",tone:"藏天下",guide:"这是全段最深刻的一句话，也是庄子最根本的宇宙观：把天下藏在天下之中——无迹可循。如果把船藏在山谷，有力者可以把它背走——因为船与山谷是分离的，可以被找到、被带走。但如果把天下藏在天下——天下就是天下本身，无处不在，也无处可找，没有什么「有力者」可以把它带走。这就是道的存在方式：不藏于某处，而是藏于一切处——因此无迹可循，也无法失去。「是恒物之大情也」——真正永恒的东西，不是因为被保护得好，而是因为它本来就是一切，无处不在，无法失去。"},{text:"善妖善老，善始善终。",tone:"四善",guide:"这四个「善」，是庄子对生命全程的态度：善妖（善待夭折——早死不是悲剧，是另一种形态），善老（善待衰老——老不是衰败，是造化的安逸），善始（善待开始——生不是偶然，是造化的承载），善终（善待终结——死不是结束，是造化的安息）。善待生命的全部——这就是圣人的境界。"}]}),i[23]||(i[23]=n("h2",{id:"六、道之本体·得道者列传",tabindex:"-1"},[e("六、道之本体·得道者列传 "),n("a",{class:"header-anchor",href:"#六、道之本体·得道者列传","aria-label":'Permalink to "六、道之本体·得道者列传"'},"​")],-1)),i[24]||(i[24]=n("h3",{id:"原文-5",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-5","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:z,glossary:b,"default-mode":"classic","aria-label":"大宗师·道之本体 原文"}),i[25]||(i[25]=n("h3",{id:"生僻字词-5",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-5","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"有情有信",pinyin:["yǒu","qíng","yǒu","xìn"],meaning:"道有真实的内容，有可信的根据。情：真实的内容、实质；信：可信、真实可验。"},{term:"无为无形",pinyin:["wú","wéi","wú","xíng"],meaning:"道没有作为，没有形状。"},{term:"自本自根",pinyin:["zì","běn","zì","gēn"],meaning:"以自身为本，以自身为根。道是自己的根源，不依赖任何外在。"}]}),i[26]||(i[26]=n("h3",{id:"核心句引读-5",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-5","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"道做了一切，却不执着于任何一种身份",subtitle:"真正的伟大，从不需要证明自己的伟大。",lines:[{text:"夫道有情有信，无为无形；可传而不可受，可得而不可见。",tone:"悖论",guide:"这是《庄子》全书中对「道」最完整的正面描述，四组对句，每组都是一个悖论：有情有信（道是真实的、可信的）vs 无为无形（道没有作为、没有形状）；可传（道可以被传授、指引方向、启发领悟）vs 不可受（不能像物品一样被直接给予——道不能「教会」，只能「领悟」）；可得（道可以被体悟得到）vs 不可见（不能用眼睛看见）。这四组悖论，共同指向道的根本性质：道是真实存在的，但不是任何感官或概念可以直接把握的——它只能被「得到」，不能被「看见」或「接受」。"},{text:"自本自根，未有天地，自古以固存；神鬼神帝，生天生地。",tone:"本体",guide:"这是道的本体论定义，也是《大宗师》中最宏大的一段：自本自根——道以自身为本，以自身为根。不依赖任何外在，不需要任何支撑——道是唯一真正自足的存在。未有天地，自古以固存——在天地存在之前，道就已经存在了。这不是时间上的「更早」，而是本体上的「更根本」——天地是道的产物，道是天地的根源。神鬼神帝，生天生地——道使鬼神有灵，使帝王有威，生成了天，生成了地。道是一切存在的根源，包括那些我们以为最神圣的存在。"},{text:"在太极之先而不为高，在六极之下而不为深，先天地生而不为久，长于上古而不为老。",tone:"四不为",guide:"这四句，是《大宗师》文学性最强的一段，也是对道最精炼的描述：四个「不为」——道超越了一切极限，但不以此自居。在宇宙之始之前——不以高自居；在宇宙最深处之下——不以深自居；比天地更早存在——不以久自居；比上古更古老——不以老自居。道的伟大，不在于它的「高深久老」，而在于它对这一切的「不为」——不执着，不自居。这与真人「不雄成」是同一个逻辑：真正伟大的，从不需要证明自己的伟大。"}]}),i[27]||(i[27]=n("h2",{id:"七、女偊论道·撄宁七阶",tabindex:"-1"},[e("七、女偊论道·撄宁七阶 "),n("a",{class:"header-anchor",href:"#七、女偊论道·撄宁七阶","aria-label":'Permalink to "七、女偊论道·撄宁七阶"'},"​")],-1)),i[28]||(i[28]=n("h3",{id:"原文-6",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-6","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:w,glossary:c,"default-mode":"classic","aria-label":"大宗师·女偊论道 原文"}),i[29]||(i[29]=n("h3",{id:"生僻字词-6",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-6","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"女偊",pinyin:["nǚ","yǔ"],meaning:"人名，虚构。得道者，貌老色若孺子。"},{term:"孺子",pinyin:["rú","zǐ"],meaning:"幼儿。色若孺子：面色如孩童（得道的证明）。"},{term:"卜梁倚",pinyin:["bǔ","liáng","yǐ"],meaning:"人名，虚构。有圣人之才而无圣人之道者。"},{term:"外天下",pinyin:["wài","tiān","xià"],meaning:"超越天下（不以天下为念）。外：超越、置于身外。"},{term:"外物",pinyin:["wài","wù"],meaning:"超越外物（不以外物为念）。"},{term:"外生",pinyin:["wài","shēng"],meaning:"超越生命（不以生死为念）。"},{term:"朝彻",pinyin:["zhāo","chè"],meaning:"朝：早晨，喻豁然；彻：通透。内心豁然通透如朝光。"},{term:"见独",pinyin:["jiàn","dú"],meaning:"独：道的独一性。见到道的本体。"},{term:"无古今",pinyin:["wú","gǔ","jīn"],meaning:"超越时间，古今不分。"},{term:"撄宁",pinyin:["yīng","níng"],meaning:"撄：扰动；宁：安宁。在扰动中保持安宁。撄而后成：被扰动了，仍能在扰动中成就安宁。"}]}),i[30]||(i[30]=n("h3",{id:"核心句引读-6",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-6","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"撄宁：在扰动中成就的安宁",subtitle:"不是在平静中成就安宁，而是在被扰动之后，仍然安宁。",lines:[{text:"子之年长矣，而色若孺子，何也？曰：吾闻道矣。",tone:"证明",guide:"故事从一个问题开始——你年纪这么大，为什么面色像孩童？女偊的回答只有四个字：吾闻道矣。不解释，不论证。得道的证明，不是言语，而是那张面孔。庄子用这个细节，把「道」从抽象概念，变成了一个可以被看见的东西——不是在书里，不是在论辩里，而是在一个人的面色里。"},{text:"参日而后能外天下；……七日而后能外物；……九日而后能外生；……朝彻而后能见独；见独而后能无古今；无古今而后能入于不死不生。",tone:"七阶",guide:"女偊描述了传道给卜梁倚的完整过程，共经历七个阶段，是《大宗师》全篇最重要的修道路径：外天下（3日，放下对天下事的执着：功名、地位、家国）→ 外物（7日，放下身外之物：财富、名声、感官享受）→ 外生（9日，超越生命本身——人最深的执着）→ 朝彻（内心豁然通透，如早晨的阳光穿透黑暗——从「放下」到「看见」的临界时刻）→ 见独（见到道的独一本体——不是创造了什么，而是看见了本来就在的东西）→ 无古今（超越时间，不被时间的流逝所困）→ 不死不生（死与生的对立彻底消解，入于道的本体）。"},{text:"杀生者不死，生生者不生。",tone:"悖论",guide:"这是七阶之后，女偊对「不死不生」境界的终极诠释，也是《大宗师》最深的一句悖论：杀生者不死——消灭了对「生」的执着的人，不再死。因为死，是执着于生的人才会经历的——执着于生，才会恐惧死；放下生的执着，死也就消失了。生生者不生——执着于生的人，反而得不到真正的生。因为他的「生」，是被恐惧和执着扭曲的生——那不是真正的生，只是对死亡的逃避。真正的「不死」，不来自长生，而来自放下对生的执着。"},{text:"撄宁也者，撄而后成者也。",tone:"撄宁",guide:"撄宁是《大宗师》最重要的概念之一：撄——被扰动、被冲击、被波及；宁——安宁、平静、不动。撄宁，不是不被扰动，而是在被扰动之后，仍然安宁。这与《德充符》的「才全」（不足以滑和，不可入于灵府）是同一个境界，但更进一步：才全说的是外物无法扰动内心；撄宁说的是即使被扰动了，也能在扰动中成就安宁。「撄而后成」——不是在平静中成就安宁，而是在扰动中成就安宁——这才是真正的宁，不是回避，而是穿越。"}]}),i[31]||(i[31]=n("h2",{id:"八、子祀四人·安时处顺·县解",tabindex:"-1"},[e("八、子祀四人·安时处顺·县解 "),n("a",{class:"header-anchor",href:"#八、子祀四人·安时处顺·县解","aria-label":'Permalink to "八、子祀四人·安时处顺·县解"'},"​")],-1)),i[32]||(i[32]=n("h3",{id:"原文-7",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-7","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:j,glossary:f,"default-mode":"classic","aria-label":"大宗师·子祀四人 原文"}),i[33]||(i[33]=n("h3",{id:"生僻字词-7",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-7","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"尻",pinyin:["kāo"],meaning:"尾骨、屁股。以无为首，以生为脊，以死为尻。"},{term:"莫逆于心",pinyin:["mò","nì","yú","xīn"],meaning:"心心相印，无所违逆。"},{term:"拘拘",pinyin:["jū","jū"],meaning:"蜷曲变形的样子。"},{term:"曲偻发背",pinyin:["qū","lóu","fā","bèi"],meaning:"曲偻：驼背弯曲；发背：背部隆起。"},{term:"句赘指天",pinyin:["gōu","zhuì","zhǐ","tiān"],meaning:"句赘：颈部赘瘤；指天：朝上突出。"},{term:"沴",pinyin:["lì"],meaning:"乖戾、失调。阴阳之气有沴：阴阳之气失调。"},{term:"浸假",pinyin:["jìn","jiǎ"],meaning:"渐渐地、假以时日。"},{term:"时夜",pinyin:["shí","yè"],meaning:"司夜，即报晓的鸡。"},{term:"鸮炙",pinyin:["xiāo","zhì"],meaning:"鸮：猫头鹰；炙：烤肉。烤猫头鹰肉。"},{term:"县解",pinyin:["xuán","jiě"],meaning:"县：通「悬」，倒悬。解除倒悬之苦。"},{term:"无怛化",pinyin:["wú","dá","huà"],meaning:"怛：惊扰。不要惊扰变化（死亡）。"},{term:"不翅于父母",pinyin:["bù","chì","yú","fù","mǔ"],meaning:"翅：通「啻」，止、只是。不止于父母，更甚于父母。"},{term:"大冶",pinyin:["dà","yě"],meaning:"大铸造师，喻造化。"},{term:"镆铘",pinyin:["mò","yé"],meaning:"古代名剑。"},{term:"成然",pinyin:["chéng","rán"],meaning:"安然的样子。成然寐：安然入睡。"},{term:"蘧然",pinyin:["qú","rán"],meaning:"惊然、豁然的样子。蘧然觉：豁然醒来。"}]}),i[34]||(i[34]=n("h3",{id:"核心句引读-7",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-7","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"以天地为大炉，以造化为大冶",subtitle:"没有一种变化是「坏」的，因为每一种形态，都有它自己的用处和乐趣。",lines:[{text:"孰能以无为首，以生为脊，以死为尻；孰知死生存亡之一体者，吾与之友矣！",tone:"结友",guide:"四人结友的誓言，是《大宗师》最豪迈的一句话。他们用身体做比喻，把死生存亡排列成一副骨架：无为头（以虚无为起点），生为脊（以生命为支撑），死为尻（以死亡为终端）。死生存亡，是同一副身体的不同部位——不是对立，而是一体。能知道这一点的人，才是他们要交的朋友。四人相视而笑，莫逆于心——不需要解释，只需要那一个眼神。庄子用「笑」来标记那些真正相遇的时刻——言语到达不了的地方，笑到了。"},{text:"伟哉，夫造物者将以予为此拘拘也。",tone:"伟哉",guide:"子舆病得身体严重变形——驼背、下巴垂到肚脐、颈部长瘤、阴阳之气失调。他的第一反应，不是哀叹，不是愤怒，而是：伟哉。造物者真伟大啊，要把我变成这副蜷曲的样子。这个「伟哉」，是全段最震撼的两个字。不是反讽，不是苦中作乐，而是真正的惊叹——造化的创造力，连这种变形，都是一种奇异的作品。他在欣赏造化对自己的塑造，就像欣赏一件雕塑。"},{text:"浸假而化予之左臂以为鸡，予因以求时夜；浸假而化予之右臂以为弹，予因以求鸮炙；浸假而化予之尻以为轮，以神为马，予因以乘之，岂更驾哉！",tone:"随化",guide:"子祀问：你厌恶这副身体吗？子舆用三个「浸假」来回答——假如造化把我的左臂变成鸡，我就用它来报晓；假如把右臂变成弹弓，我就用它来打猫头鹰烤着吃；假如把尾骨变成车轮，把精神变成马，我就骑着它走，还需要另外套车吗？这三个假设，是庄子最生动的「随化」示范：不管造化把我变成什么，我都顺着那个形态去用它。变成鸡翅，就去报晓；变成弹弓，就去打猎；变成车轮，就去驰骋——没有一种变化是「坏」的，因为每一种形态，都有它自己的用处和乐趣。"},{text:"且夫得者，时也；失者，顺也。安时而处顺，哀乐不能入也，此古之所谓县解也。",tone:"县解",guide:"这是《大宗师》中最重要的处世命题之一：得者，时也——得到，是时机（不是因为我努力，是时机到了）；失者，顺也——失去，是顺应（不是因为我失败，是顺应变化）。得与失，都不是「我」的功过——都是时机与顺应的自然结果。安时而处顺——安于时机，处于顺应——不强求，不抗拒，只是随着时机与变化自然流动。哀乐不能入也——当一个人真正做到安时处顺，哀愁和欢乐，都无法进入他的内心——不是没有感受，而是感受不会变成执着，不会变成伤害。县解——解除倒悬之苦。人被哀乐、得失、生死倒悬着，痛苦不堪——安时处顺，就是从这种倒悬中解脱出来。"},{text:"今一以天地为大炉，以造化为大冶，恶乎往而不可哉！",tone:"壮阔",guide:"这是子来最后的话，也是第八段最壮阔的收尾：以天地为大熔炉，以造化为大铸造师——还有什么地方去不得？还有什么变化不可以？天地是炉，造化是冶——我只是炉中的金属，随造化铸成任何形态——没有什么「不可以」，因为一切都是造化的作品。说完，成然寐，蘧然觉——安然入睡，豁然醒来。庄子用这四个字结束子来的故事：死亡，就像入睡；而那个「蘧然觉」——也许是另一种形态的醒来。"}]}),i[35]||(i[35]=n("h2",{id:"九、子桑户死·游方之外·畸人",tabindex:"-1"},[e("九、子桑户死·游方之外·畸人 "),n("a",{class:"header-anchor",href:"#九、子桑户死·游方之外·畸人","aria-label":'Permalink to "九、子桑户死·游方之外·畸人"'},"​")],-1)),i[36]||(i[36]=n("h3",{id:"原文-8",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-8","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:q,glossary:k,"default-mode":"classic","aria-label":"大宗师·游方之外 原文"}),i[37]||(i[37]=n("h3",{id:"生僻字词-8",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-8","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"挠挑无极",pinyin:["náo","tiāo","wú","jí"],meaning:"挠挑：翻腾游荡。无拘无束游于无极之境。"},{term:"嗟来桑户乎",pinyin:["jiē","lái","sāng","hù","hū"],meaning:"唉，桑户啊！嗟来：感叹词。"},{term:"反其真",pinyin:["fǎn","qí","zhēn"],meaning:"返回本真（死亡即回归）。"},{term:"外其形骸",pinyin:["wài","qí","xíng","hái"],meaning:"置形体于度外。"},{term:"游方之外",pinyin:["yóu","fāng","zhī","wài"],meaning:"方：礼法规范的方域。游于礼法规范之外。"},{term:"附赘县疣",pinyin:["fù","zhuì","xuán","yóu"],meaning:"赘：多余的肉；疣：皮肤赘生物。以生为附赘县疣：把生命看作暂时附着在道上的形态。"},{term:"决𤴯溃痈",pinyin:["jué","zì","kuì","yōng"],meaning:"𤴯：脓疮；痈：毒疮。以死为决𤴯溃痈：把死亡看作一种释放。"},{term:"天之戮民",pinyin:["tiān","zhī","lù","mín"],meaning:"戮：受刑。受天刑之人（被天道约束之人）。孔子自认「天之戮民」。"},{term:"畸人",pinyin:["jī","rén"],meaning:"奇异之人。畸人者，畸于人而侔于天：在人的标准里奇异，在天道的标准里齐平完整。"}]}),i[38]||(i[38]=n("h3",{id:"核心句引读-8",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-8","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"畸于人而侔于天",subtitle:"人间的标准与天道的标准，是两套不同的坐标系。",lines:[{text:"嗟来桑户乎！嗟来桑户乎！而已反其真，而我犹为人猗！",tone:"羡慕",guide:"子桑户死了，两位朋友在他的遗体旁边，一个编草席，一个弹琴，相和而歌：唉，桑户啊！唉，桑户啊！你已经回归本真了，而我们还在做人啊！这首歌，是《大宗师》最动人的一幕。不是哀歌，而是羡慕——羡慕桑户已经「反其真」，回归了本真；而自己还在人间，还在「为人」——还没有完成那个回归。死亡，在这里不是失去，而是先行一步的回归。"},{text:"彼游方之外者也，而丘游方之内者也。外内不相及，而丘使女往吊之，丘则陋矣！",tone:"自知",guide:"孔子对子贡的回答，是《大宗师》中孔子最深刻的自我认知：他们游于方之外，我游于方之内。方：礼法规范的方域——儒家的秩序、礼仪、道德体系。孔子不是在贬低自己，而是在如实陈述：我是方之内的人，他们是方之外的人——两种人，两种境界，外内不相及。「丘则陋矣」——我派你去吊唁，是我浅陋——因为我用方之内的标准，去衡量方之外的人。这与《德充符》中孔子说「丘则陋矣」完全呼应——庄子笔下的孔子，是一个能够自我认知局限的人，这本身，就是一种深度。"},{text:"彼以生为附赘县疣，以死为决𤴯溃痈。",tone:"生附死释",guide:"这是孔子对「游方之外者」最精准的描述：以生为附赘县疣——把生命看作多余的赘肉、皮肤上的疣——不是厌恶生命，而是不执着于生命，生命只是暂时附着在道上的一个形态；以死为决𤴯溃痈——把死亡看作切开脓疮、使其溃散——不是恐惧死亡，而是把死亡看作一种释放，一种让积聚的东西得以流动的过程。生是附着，死是释放——两者都是造化的作品，都值得坦然对待。"},{text:"鱼相造乎水，人相造乎道。……故曰：鱼相忘乎江湖，人相忘乎道术。",tone:"类比",guide:"这是第四段「相忘于江湖」的完整展开，也是《大宗师》中最美的一段类比：鱼与水——鱼依赖水而生，如果把鱼放在池子里，需要不断给它换水、喂食——这是「穿池而养给」，是人为的维持；但如果鱼在江湖里——它与水相忘，不需要任何人为的维持，自然生存。人与道——人依赖道而生，如果人离开了道，需要不断用礼义、规范、努力来维持——这是人为的挣扎；但如果人在道中——无事而生定，不需要任何努力，生命自然安定。「人相忘乎道术」——人在道中相忘，就像鱼在江湖中相忘——不是忘记了道，而是与道合一到不需要刻意记住道。"},{text:"畸人者，畸于人而侔于天。故曰：天之小人，人之君子；人之君子，天之小人也。",tone:"两套坐标",guide:"这是《大宗师》最精炼的一个悖论，也是全篇对「真人」与「世俗人」关系的终极定义：畸人——在人间是奇异的、不合规范的人；畸于人——在人的标准里是奇异的；侔于天——在天道的标准里是齐平的、完整的。天之小人，人之君子——在天道看来是小人的，在人间是君子；人之君子，天之小人——在人间是君子的，在天道看来是小人（执着于人间规范）。这不是说人间的君子是坏人，而是说：人间的标准与天道的标准，是两套不同的坐标系。庄子不是要否定人间的君子，而是要说：别把人间的坐标系，当成唯一的坐标系。"}]}),i[39]||(i[39]=n("h2",{id:"十、孟孙才·旦宅无情死·安排而去化",tabindex:"-1"},[e("十、孟孙才·旦宅无情死·安排而去化 "),n("a",{class:"header-anchor",href:"#十、孟孙才·旦宅无情死·安排而去化","aria-label":'Permalink to "十、孟孙才·旦宅无情死·安排而去化"'},"​")],-1)),i[40]||(i[40]=n("h3",{id:"原文-9",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-9","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:P,glossary:T,"default-mode":"classic","aria-label":"大宗师·孟孙才 原文"}),i[41]||(i[41]=n("h3",{id:"生僻字词-9",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-9","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"孟孙才",pinyin:["mèng","sūn","cái"],meaning:"人名，鲁国贵族。"},{term:"中心不戚",pinyin:["zhōng","xīn","bù","qī"],meaning:"戚：悲伤。内心不悲伤。"},{term:"旦宅",pinyin:["dàn","zhái"],meaning:"旦：早晨，喻短暂；宅：居所。把形体当作短暂的居所。"},{term:"无情死",pinyin:["wú","qíng","sǐ"],meaning:"不以情感执着于死亡。"},{term:"安排而去化",pinyin:["ān","pái","ér","qù","huà"],meaning:"安然顺应，随化而去。不执着于任何状态，只是随着变化流动。"},{term:"寥天一",pinyin:["liáo","tiān","yī"],meaning:"空旷无际的天道本体。安排而去化，乃入于寥天一。"}]}),i[42]||(i[42]=n("h3",{id:"核心句引读-9",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-9","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"有骇形而无损心，有旦宅而无情死",subtitle:"不是不哭，而是哭而不伤；不是不在乎，而是在乎而不执着。",lines:[{text:"且方将化，恶知不化哉？方将不化，恶知已化哉？",tone:"变化",guide:"这两句，是《大宗师》对「变化」最深的追问：正在变化的时候，怎么知道自己没有变化？正在不变化的时候，怎么知道自己已经变化了？变化与不变化，没有清晰的边界——就像睡与醒，没有那个精确的分界点。这与下文的「梦觉之辩」直接相连：我们以为自己清醒，但怎么知道不是在梦中？"},{text:"且彼有骇形而无损心，有旦宅而无情死。",tone:"孟孙才",guide:"这是孟孙才境界的最精炼表达，两组对句：有骇形而无损心——形体受到惊动（外在有悲痛的表现，人哭他也哭），但内心没有损伤——外在顺应人间的礼仪，内心不被死亡所伤；有旦宅而无情死——把形体当作早晨短暂的居所（不执着于这副身体），对死亡没有情感的执着——不是不悲，而是悲不入心。这两句，是《大宗师》对「处丧」最深的定义：不是不哭，而是哭而不伤；不是不在乎，而是在乎而不执着。"},{text:"造适不及笑，献笑不及排，安排而去化，乃入于寥天一。",tone:"终境",guide:"这是第十段的终极结语，也是《大宗师》最美的四句话：造适不及笑——刚刚感到舒适，还来不及笑出来；献笑不及排——刚要笑，还来不及完全舒展开来。变化来得太快，连笑都来不及完成——不是悲剧，而是说明：执着于任何一种状态（哪怕是快乐），都是来不及的。安排而去化——安然顺应，随化而去——不执着于任何状态，只是随着变化流动；乃入于寥天一——于是进入那个空旷无际的天道本体。寥天一——是《大宗师》全篇最后出现的境界词，也是对「不死不生」、「撄宁」、「游方之外」的最终归宿：空旷、无际、与天道合一。"}]}),i[43]||(i[43]=n("h2",{id:"十一、意而子见许由·黥劓之喻·吾师乎",tabindex:"-1"},[e("十一、意而子见许由·黥劓之喻·吾师乎 "),n("a",{class:"header-anchor",href:"#十一、意而子见许由·黥劓之喻·吾师乎","aria-label":'Permalink to "十一、意而子见许由·黥劓之喻·吾师乎"'},"​")],-1)),i[44]||(i[44]=n("h3",{id:"原文-10",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-10","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:v,glossary:G,"default-mode":"classic","aria-label":"大宗师·意而子见许由 原文"}),i[45]||(i[45]=n("h3",{id:"生僻字词-10",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-10","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"意而子",pinyin:["yì","ér","zǐ"],meaning:"人名，虚构。曾受尧教化者。"},{term:"许由",pinyin:["xǔ","yóu"],meaning:"传说中的隐士，尧欲让位于他，不受而隐。"},{term:"躬服仁义",pinyin:["gōng","fú","rén","yì"],meaning:"躬：亲身；服：践行。亲身践行仁义。"},{term:"黥",pinyin:["qíng"],meaning:"在脸上刺字的刑罚。比喻仁义在心上留下的印记。"},{term:"劓",pinyin:["yì"],meaning:"割去鼻子的刑罚。比喻是非在心上造成的残缺。"},{term:"恣睢",pinyin:["zì","suī"],meaning:"放纵自在。遥荡恣睢转徙之涂：遥远自在、随意转徙的道路（道的境界）。"},{term:"盲者",pinyin:["máng","zhě"],meaning:"眼盲的人。盲者无以与乎眉目颜色之好：盲人无法欣赏容貌之美。"},{term:"瞽者",pinyin:["gǔ","zhě"],meaning:"天生眼盲的人。瞽者无以与乎青黄黼黻之观：盲人无法欣赏纹饰之美。"}]}),i[46]||(i[46]=n("h3",{id:"核心句引读-10",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-10","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"吾师乎！吾师乎！——道本身",subtitle:"道做了一切，却不执着于任何一种身份——这才是真正的「游」的境界。",lines:[{text:"夫尧既已黥汝以仁义，而劓汝以是非矣。汝将何以游夫遥荡恣睢转徙之涂乎？",tone:"黥劓",guide:"许由用两种刑罚来比喻尧的教化：黥——在脸上刺字，永久的印记，无法消除；劓——割去鼻子，永久的残缺，无法复原。尧用仁义在你心上刺了字，用是非割去了你的鼻子——你已经被改造了，被标记了，被残缺了。你还怎么游于那条遥远自在、随意转徙的道路？这是《大宗师》对儒家教化最深的批判——不是说仁义是非是坏的，而是说：当仁义是非成为刻在心上的印记，它就不再是自然流出的德性，而是一种束缚。"},{text:"夫无庄之失其美，据梁之失其力，黄帝之亡其知，皆在炉捶之间耳。庸讵知夫造物者之不息我黥而补我劓，使我乘成以随先生邪？",tone:"希望",guide:"意而子的反驳，是《大宗师》中最有力的一句希望：无庄失去了美貌，据梁失去了力气，黄帝失去了智慧——都是在造化的熔炉锻造中发生的。但这些失去，是为了更深的得到——黄帝失去智慧，是为了得道；无庄失去美貌，是为了超越形体的执着。怎么知道造化不会消除我心上的黥、补回我的劓，让我以完整的本性追随先生？这句话，是意而子对造化的信任——被改造过的人，也可以被造化重新完整。这与第八段子来的「大冶铸金」完全呼应：造化是大冶，熔炉里的一切，都是造化的作品——包括被黥劓的修复。"},{text:"吾师乎！吾师乎！赍万物而不为义，泽及万世而不为仁，长于上古而不为老，覆载天地、刻雕众形而不为巧。此所游已！",tone:"吾师",guide:"许由被意而子的话打动，说出了《大宗师》中最壮阔的一段：吾师乎！吾师乎！——我的老师啊！我的老师啊！许由的老师，不是某个人，而是道本身。四个「不为」，与第六段道的描述完全呼应：赍万物而不为义（养育万物，却不以义自居）、泽及万世而不为仁（恩泽万世，却不以仁自居）、长于上古而不为老（比上古更古，却不以老自居）、覆载天地、刻雕众形而不为巧（创造一切，却不以巧自居）。道做了一切，却不执着于任何一种身份——这才是真正的「游」的境界。「此所游已！」——这，就是我所游的地方！"}]}),i[47]||(i[47]=n("h2",{id:"十二、颜回坐忘·堕肢体·同于大通",tabindex:"-1"},[e("十二、颜回坐忘·堕肢体·同于大通 "),n("a",{class:"header-anchor",href:"#十二、颜回坐忘·堕肢体·同于大通","aria-label":'Permalink to "十二、颜回坐忘·堕肢体·同于大通"'},"​")],-1)),i[48]||(i[48]=n("h3",{id:"原文-11",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-11","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:D,glossary:C,"default-mode":"classic","aria-label":"大宗师·颜回坐忘 原文"}),i[49]||(i[49]=n("h3",{id:"生僻字词-11",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-11","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"回益矣",pinyin:["huí","yì","yǐ"],meaning:"益：进步、增益。我有进步了。"},{term:"忘仁义",pinyin:["wàng","rén","yì"],meaning:"超越对仁义的执着。放下儒家最核心的道德规范。"},{term:"忘礼乐",pinyin:["wàng","lǐ","yuè"],meaning:"超越对礼乐的执着。放下儒家最核心的文化形式。"},{term:"坐忘",pinyin:["zuò","wàng"],meaning:"坐：静坐；忘：忘却一切执着。静坐中忘却自我。"},{term:"蹴然",pinyin:["cù","rán"],meaning:"惊讶肃然的样子。仲尼蹴然曰：孔子听到「坐忘」，惊讶肃然。"},{term:"堕肢体",pinyin:["duò","zhī","tǐ"],meaning:"堕：废弃、忘却。忘却肢体的存在（不执着于形体）。"},{term:"黜聪明",pinyin:["chù","cōng","míng"],meaning:"黜：废除。废除聪明智慧的执着（不执着于知识）。"},{term:"离形去知",pinyin:["lí","xíng","qù","zhī"],meaning:"脱离形体，去除知识执着。"},{term:"同于大通",pinyin:["tóng","yú","dà","tōng"],meaning:"与道的通达无碍之境合一。大通：道的通达无碍之境，即道本体。"}]}),i[50]||(i[50]=n("h3",{id:"核心句引读-11",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-11","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"堕肢体，黜聪明，离形去知，同于大通",subtitle:"进步，不是加法，而是减法——每一次「益」，都是忘掉了一样东西。",lines:[{text:"回益矣。——何谓也？——回忘仁义矣。——可矣，犹未也。",tone:"三进",guide:"这段对话，用了三次相同的结构——「回益矣」→「何谓也」→「忘……矣」→「可矣，犹未也」。颜回每次说「我有进步了」，孔子每次说「可以，但还不够」。这个结构本身，就是庄子的用意：进步，不是加法，而是减法——每一次「益」，都是忘掉了一样东西。第一次：忘仁义——放下儒家最核心的道德规范；第二次：忘礼乐——放下儒家最核心的文化形式；第三次：坐忘——放下一切，包括「自我」本身。三次递进，每次都更深——最后忘掉的，不是某个具体的东西，而是「忘」这件事本身。"},{text:"堕肢体，黜聪明，离形去知，同于大通，此谓坐忘。",tone:"定义",guide:"颜回对坐忘的定义，是《大宗师》中最简洁、最完整的修道描述：堕肢体——忘却肢体的存在（不执着于形体）；黜聪明——废除聪明智慧的执着（不执着于知识）；离形去知——脱离形体，去除知识——这是撄宁七阶中「外生」的另一种表达；同于大通——与道的通达无碍之境合一。四句话，从外到内，从形到知，最终归于道——这是《大宗师》修道路径的最简版本。坐忘，是撄宁七阶的压缩版——不是七个步骤，而是一个当下的彻底放下。"},{text:"同则无好也，化则无常也。而果其贤乎！丘也请从而后也。",tone:"请从",guide:"孔子的回应，是《大宗师》中最动人的一句话：同则无好也——与道合一，就没有偏好了（无所执着）；化则无常也——随化流动，就没有固定不变的常了（无所执着）。孔子理解了坐忘的境界，然后说：你果然比我贤啊！请让我跟在你后面学习。老师向学生请教——这在儒家是极罕见的，在庄子笔下却自然发生。庄子在这里，不是要嘲笑孔子，而是要说：真正的老师，是那个能向学生学习的人。孔子在《大宗师》中，完成了一个完整的弧线：第三段「天刑之，安可解」（被判断）→ 第九段「丘，天之戮民也」（自我认知）→ 第十二段「丘也请从而后也」（主动跟随）。从被判断，到自我认知，到主动跟随——这是庄子给孔子的最深的敬意：知道自己的局限，并愿意超越它。"}]}),i[51]||(i[51]=n("h2",{id:"十三、子舆子桑·霖雨十日·命也夫",tabindex:"-1"},[e("十三、子舆子桑·霖雨十日·命也夫 "),n("a",{class:"header-anchor",href:"#十三、子舆子桑·霖雨十日·命也夫","aria-label":'Permalink to "十三、子舆子桑·霖雨十日·命也夫"'},"​")],-1)),i[52]||(i[52]=n("h3",{id:"原文-12",tabindex:"-1"},[e("原文 "),n("a",{class:"header-anchor",href:"#原文-12","aria-label":'Permalink to "原文"'},"​")],-1)),a(t,{sections:N,glossary:V,"default-mode":"classic","aria-label":"大宗师·霖雨十日 原文"}),i[53]||(i[53]=n("h3",{id:"生僻字词-12",tabindex:"-1"},[e("生僻字词 "),n("a",{class:"header-anchor",href:"#生僻字词-12","aria-label":'Permalink to "生僻字词"'},"​")],-1)),a(s,{items:[{term:"霖雨十日",pinyin:["lín","yǔ","shí","rì"],meaning:"霖雨：连续多日的大雨。连续下了十天大雨。"},{term:"殆病矣",pinyin:["dài","bìng","yǐ"],meaning:"殆：恐怕、大概。恐怕病了。"},{term:"裹饭",pinyin:["guǒ","fàn"],meaning:"包裹着饭食。"},{term:"若歌若哭",pinyin:["ruò","gē","ruò","kū"],meaning:"像唱歌又像哭泣。"},{term:"不任其声",pinyin:["bù","rèn","qí","shēng"],meaning:"任：承受。声音哽咽，无法承受（唱不下去了）。"},{term:"趋举其诗",pinyin:["qū","jǔ","qí","shī"],meaning:"趋：急促；举：接续。急促地接续那首歌。"},{term:"命也夫",pinyin:["mìng","yě","fū"],meaning:"这就是命啊！夫：语气助词，感叹。"}]}),i[54]||(i[54]=n("h3",{id:"核心句引读-12",tabindex:"-1"},[e("核心句引读 "),n("a",{class:"header-anchor",href:"#核心句引读-12","aria-label":'Permalink to "核心句引读"'},"​")],-1)),a(g,{title:"求其为之者而不得也！然而至此极者，命也夫！",subtitle:"穷尽了人的认知边界之后，对那个无法追溯的根源的最后命名。",lines:[{text:"父邪！母邪！天乎！人乎！",tone:"追问",guide:"子桑在极度贫困、病痛中，发出这四个疑问——是父亲的原因？是母亲的原因？是天的原因？是人的原因？这四个问，不是抱怨，而是真正的追问——他在认真寻找：是谁让我到了这个地步？声音哽咽，唱不下去，朋友急忙接续他的歌——这一幕，是《大宗师》中最人间烟火的一幕。没有「伟哉造化」，没有「安时处顺」，只有一个在风雨中又饿又病的人，哽咽着问：为什么？"},{text:"父母岂欲吾贫哉？天无私覆，地无私载，天地岂私贫我哉？求其为之者而不得也！然而至此极者，命也夫！",tone:"命也夫",guide:"子桑追问到最后，得出了结论：父母不想让我贫穷——不是父母的原因；天无私覆，地无私载——不是天地的原因；找遍了所有可能的原因，找不到是谁造成的——然而至此极者，命也夫！这就是命啊。这句「命也夫」，与第二段申徒嘉的「安之若命」、第四段的「死生，命也」，是同一个字，但境界完全不同：申徒嘉的「安之若命」——是已经安顿好了的平静；第四段的「死生，命也」——是哲学层面的陈述；子桑的「命也夫」——是在哽咽中、在追问之后、在找不到答案之后，才说出的那个「命」。这是《大宗师》中最真实的「命」——不是一开始就接受，而是穷尽了所有追问，找不到答案，最后才说：命也夫。这个「命」，不是放弃，不是认输，而是穷尽了人的认知边界之后，对那个无法追溯的根源的最后命名。"}]}),i[55]||(i[55]=E(`<h2 id="脉络逻辑链" tabindex="-1">脉络逻辑链 <a class="header-anchor" href="#脉络逻辑链" aria-label="Permalink to &quot;脉络逻辑链&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一部分·真人论（第1—3段）</span></span>
<span class="line"><span>第1段·起（天人之知）</span></span>
<span class="line"><span>    知天知人者至矣·知有所待而未定</span></span>
<span class="line"><span>    → 知识有局限，先有真人而后有真知</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第2段·展（真人三论）</span></span>
<span class="line"><span>    不逆寡·不雄成·不谟士·息以踵·不知说生不知恶死</span></span>
<span class="line"><span>    → 真人的行为·身心·生死三重画像</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第3段·合（真人之状·天与人不相胜）</span></span>
<span class="line"><span>    十叠词描气象·以刑为体以礼为翼·天与人不相胜</span></span>
<span class="line"><span>    → 真人定义完成：同时游于天道与人间</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第二部分·道论（第4—6段）</span></span>
<span class="line"><span>第4段·死生（相濡以沫不如相忘于江湖）</span></span>
<span class="line"><span>    死生，命也·两忘而化其道</span></span>
<span class="line"><span>    → 把死生从道德问题还原为自然问题</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第5段·变化（藏天下于天下）</span></span>
<span class="line"><span>    大块载我·藏舟于壑·善吾生者善吾死</span></span>
<span class="line"><span>    → 真正永恒者，本是一切，无处可失</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第6段·本体（道之本体·得道者列传）</span></span>
<span class="line"><span>    有情有信·自本自根·十四得道者各成其用</span></span>
<span class="line"><span>    → 道的本体论定义</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第三部分·得道之路（第7段）</span></span>
<span class="line"><span>第7段·路（女偊论道·撄宁七阶）</span></span>
<span class="line"><span>    外天下→外物→外生→朝彻→见独→无古今→不死不生</span></span>
<span class="line"><span>    → 撄宁：在扰动中成就的安宁</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第四部分·寓言群像（第8—13段）</span></span>
<span class="line"><span>第8段·县解（子祀四人·安时处顺）</span></span>
<span class="line"><span>    以天地为大炉·以造化为大冶·成然寐蘧然觉</span></span>
<span class="line"><span>    → 随化示范</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第9段·游方之外（子桑户死·畸人）</span></span>
<span class="line"><span>    相忘以生·反其真·畸于人而侔于天</span></span>
<span class="line"><span>    → 方外与方内两套坐标系</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第10段·旦宅（孟孙才·安排而去化）</span></span>
<span class="line"><span>    有骇形而无损心·有旦宅而无情死·乃入于寥天一</span></span>
<span class="line"><span>    → 处丧而不伤：哭而不伤</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第11段·黥劓（意而子见许由·吾师乎）</span></span>
<span class="line"><span>    黥汝以仁义·劓汝以是非·吾师乎赍万物而不为义</span></span>
<span class="line"><span>    → 道是真正的老师，做了一切而不居功</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第12段·坐忘（颜回·堕肢体黜聪明）</span></span>
<span class="line"><span>    忘仁义→忘礼乐→坐忘·堕肢体黜聪明·同于大通</span></span>
<span class="line"><span>    → 进步不是加法而是减法</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>第13段·命也夫（子舆子桑·霖雨十日）</span></span>
<span class="line"><span>    求其为之者而不得·然而至此极者，命也夫</span></span>
<span class="line"><span>    → 穷尽追问之后的安命，全篇收束</span></span></code></pre></div><p><strong>全篇主线</strong>：真人是什么样的人（描述·定义）→ 道是什么（本体·宇宙论）→ 如何得道（撄宁七阶的路径）→ 真实的人如何面对（寓言群像）。从「有真人而后有真知」开篇，到「命也夫」收束——先立真人与道，再以六则寓言演示真人如何在生死、丧葬、礼义、坐忘与命运中实践。</p><h2 id="三问解读" tabindex="-1">三问解读 <a class="header-anchor" href="#三问解读" aria-label="Permalink to &quot;三问解读&quot;">​</a></h2><h3 id="第一问-《大宗师》的核心命题是什么" tabindex="-1">第一问：《大宗师》的核心命题是什么？ <a class="header-anchor" href="#第一问-《大宗师》的核心命题是什么" aria-label="Permalink to &quot;第一问：《大宗师》的核心命题是什么？&quot;">​</a></h3><blockquote><p><strong>死生、命也。有真人而后有真知。天与人不相胜也，是之谓真人。</strong></p></blockquote><p>《大宗师》的核心，是<strong>死生问题</strong>——但庄子处理死生的方式，与所有其他思想传统都不同：儒家说「死生有命，富贵在天」——接受，但不深究；佛家说「死是苦，修行是为了解脱轮回」；道教追求长生不死、羽化成仙。</p><p>庄子：死生不是对立的两极，而是同一个变化过程的两面——就像昼夜，就像炉中的金属被铸成不同的形态。真正的问题不是「如何不死」，而是「如何不被死生所执」。执着于生，才会恐惧死；放下对生的执着，死也就不再是死——杀生者不死，生生者不生。</p><p>这是《大宗师》给出的根本答案：不是长生，而是超越死生的对立。</p><h3 id="第二问-《大宗师》与内篇其他篇章的关系" tabindex="-1">第二问：《大宗师》与内篇其他篇章的关系？ <a class="header-anchor" href="#第二问-《大宗师》与内篇其他篇章的关系" aria-label="Permalink to &quot;第二问：《大宗师》与内篇其他篇章的关系？&quot;">​</a></h3><p>《大宗师》是内篇七篇的<strong>枢纽</strong>：</p><table tabindex="0"><thead><tr><th>篇章</th><th>核心命题</th><th>与《大宗师》的关系</th></tr></thead><tbody><tr><td>逍遥游</td><td>无待·至人无己</td><td>《大宗师》的真人，是逍遥游的至人的展开</td></tr><tr><td>齐物论</td><td>万物齐一·梦觉之辩</td><td>《大宗师》的「梦未始觉」·「无古今」直接呼应</td></tr><tr><td>养生主</td><td>缘督以为经·安时处顺</td><td>《大宗师》的「安时处顺·县解」是养生主的深化</td></tr><tr><td>人间世</td><td>在人间如何自处</td><td>《大宗师》的「游方之内」·孔子是人间世的延伸</td></tr><tr><td>德充符</td><td>德充于内·形有所忘</td><td>《大宗师》的「才全」·「骇形无损心」是德充符的延续</td></tr><tr><td>大宗师</td><td>道·真人·死生·坐忘</td><td><strong>枢纽</strong>：汇聚前五篇，开启应帝王</td></tr><tr><td>应帝王</td><td>圣人治世·浑沌</td><td>《大宗师》的真人·道，落实到治世</td></tr></tbody></table><p>前五篇从不同角度逼近道，《大宗师》正面展开道的本体与真人的境界，《应帝王》则把这个境界落实到人间的治理。</p><h3 id="第三问-《大宗师》最难理解的是什么" tabindex="-1">第三问：《大宗师》最难理解的是什么？ <a class="header-anchor" href="#第三问-《大宗师》最难理解的是什么" aria-label="Permalink to &quot;第三问：《大宗师》最难理解的是什么？&quot;">​</a></h3><p><strong>最难的，不是概念，而是那个「转化」。</strong></p><p>《大宗师》说了很多：真人不知说生不知恶死，安时处顺哀乐不能入，坐忘同于大通……但这些，都是<strong>描述</strong>——描述一个已经转化的人是什么样的。</p><p>真正难的问题是：这个转化，怎么发生？撄宁七阶给了一个路径——外天下、外物、外生、朝彻、见独、无古今、不死不生——但这个路径，也只是描述，不是操作手册。女偊说：子非其人也。</p><p>庄子在这里，诚实地承认了一件事：道不是学来的，不是练来的，不是努力来的——它是一个存在状态的转化，而这个转化，需要「其人」。什么是「其人」？也许，就是那个已经开始放下的人——不是放下了，而是开始放下。子桑在风雨中哽咽，说「命也夫」——那一刻，他也许就是「其人」——不是因为他超然，而是因为他穷尽了追问，然后放下了。</p><h2 id="现代思考与启发" tabindex="-1">现代思考与启发 <a class="header-anchor" href="#现代思考与启发" aria-label="Permalink to &quot;现代思考与启发&quot;">​</a></h2><p><strong>关于死亡</strong></p><blockquote><p>现代人对死亡的态度，在某种意义上更加执着——医学的进步，让我们相信死亡是可以被推迟的；文化的变迁，让我们把死亡从日常生活中隔离出去。庄子不是说不要治病，不要延长生命——而是说：在做这一切的同时，不要让对死亡的恐惧，扭曲了你活着的方式。「善吾生者，乃所以善吾死也」——善待生命，就是善待死亡——一个真正活着的人，不需要害怕死亡。</p></blockquote><p><strong>关于执着</strong></p><blockquote><p>我们以为抓住了什么——财富、地位、关系、健康、年轻——以为藏得很稳固。但那个「夜半有力者」，始终在那里。庄子不是说不要拥有，而是说：不要以为你真的拥有了——你只是暂时与它同在。「藏天下于天下而不得所循」——真正不会失去的，是那个无处不在的道——因为它本来就是一切，无处可失。</p></blockquote><p><strong>关于关系</strong></p><blockquote><p>「相濡以沫，不如相忘于江湖」——这句话，被现代人误读为「冷漠比深情更好」。庄子说的是：相濡以沫，是因为失去了江湖——是困境中的温情，不是理想的状态。真正好的关系，是相忘于江湖——不是忘记对方，而是在道中各自自在，不需要用执着来维持关系。最深的爱，不是「我离不开你」，而是「我希望你在江湖里自在，不需要靠我的唾沫活着」。</p></blockquote><p><strong>关于坐忘</strong></p><blockquote><p>坐忘，不是冥想的技术，不是放空大脑——而是一个存在状态的彻底转化：堕肢体——不是不用身体，而是不执着于身体；黜聪明——不是变笨，而是不执着于聪明；离形去知——不是没有形体和知识，而是不被它们所定义；同于大通——与道合一，不是消失，而是扩展到无边界。现代人的焦虑，很多来自对「自我」的过度执着——坐忘，是放下这个执着的自我，不是失去自我，而是发现那个更大的自我——与道合一的自我，无边界的自我。</p></blockquote><p><strong>关于「命也夫」</strong></p><blockquote><p>子桑的「命也夫」，是《大宗师》最真实的一句话。不是一开始就接受，不是超然地说「造化真伟大」，而是穷尽了追问，找不到答案，在哽咽中说出的那三个字。这才是真正的安命——不是没有追问过，而是追问到了边界，然后放下了。每个人都有自己的「命也夫」时刻——那个找不到原因、找不到答案的时刻。庄子说：那个时刻，就是命，就是天，就是道的边界。不需要再追问，只需要——安排而去化，乃入于寥天一。</p></blockquote><h2 id="关键词索引" tabindex="-1">关键词索引 <a class="header-anchor" href="#关键词索引" aria-label="Permalink to &quot;关键词索引&quot;">​</a></h2><h3 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>出处</th><th>核心含义</th></tr></thead><tbody><tr><td>真人</td><td>第1—3段</td><td>天与人不相胜·不知说生不知恶死·翛然往来</td></tr><tr><td>真知</td><td>第1段</td><td>有真人而后有真知·知来自存在状态而非积累</td></tr><tr><td>撄宁</td><td>第7段</td><td>撄而后成·在扰动中成就的安宁</td></tr><tr><td>坐忘</td><td>第12段</td><td>堕肢体·黜聪明·离形去知·同于大通</td></tr><tr><td>县解</td><td>第8段</td><td>安时处顺·哀乐不能入·解除倒悬之苦</td></tr><tr><td>游方之外</td><td>第9段</td><td>畸于人而侔于天·逍遥乎无为之业</td></tr><tr><td>寥天一</td><td>第10段</td><td>安排而去化后的归宿·空旷无际的天道本体</td></tr><tr><td>旦宅</td><td>第10段</td><td>把形体当作短暂居所·不执着于形体</td></tr><tr><td>疑始</td><td>第7段</td><td>道的本源·不可追溯·无可名状</td></tr><tr><td>大通</td><td>第12段</td><td>道的通达无碍之境·坐忘的归宿</td></tr></tbody></table><h3 id="核心句速查" tabindex="-1">核心句速查 <a class="header-anchor" href="#核心句速查" aria-label="Permalink to &quot;核心句速查&quot;">​</a></h3><table tabindex="0"><thead><tr><th>句子</th><th>出处</th><th>主题</th></tr></thead><tbody><tr><td>有真人而后有真知</td><td>第1段</td><td>知识论</td></tr><tr><td>真人之息以踵，众人之息以喉</td><td>第2段</td><td>生命深度</td></tr><tr><td>其耆欲深者，其天机浅</td><td>第2段</td><td>欲望与天机</td></tr><tr><td>翛然而往，翛然而来而已矣</td><td>第2段</td><td>死生态度</td></tr><tr><td>天与人不相胜也，是之谓真人</td><td>第3段</td><td>真人定义</td></tr><tr><td>相濡以沫，不如相忘于江湖</td><td>第4段</td><td>关系·道</td></tr><tr><td>藏天下于天下而不得所循</td><td>第5段</td><td>道的存在方式</td></tr><tr><td>善吾生者，乃所以善吾死也</td><td>第5段</td><td>生死一体</td></tr><tr><td>自本自根，未有天地，自古以固存</td><td>第6段</td><td>道的本体</td></tr><tr><td>可传而不可受，可得而不可见</td><td>第6段</td><td>道的性质</td></tr><tr><td>撄宁也者，撄而后成者也</td><td>第7段</td><td>撄宁</td></tr><tr><td>杀生者不死，生生者不生</td><td>第7段</td><td>死生悖论</td></tr><tr><td>安时而处顺，哀乐不能入也</td><td>第8段</td><td>县解</td></tr><tr><td>以天地为大炉，以造化为大冶</td><td>第8段</td><td>随化</td></tr><tr><td>彼以生为附赘县疣，以死为决𤴯溃痈</td><td>第9段</td><td>游方之外者</td></tr><tr><td>鱼相忘乎江湖，人相忘乎道术</td><td>第9段</td><td>人与道</td></tr><tr><td>畸人者，畸于人而侔于天</td><td>第9段</td><td>畸人</td></tr><tr><td>有骇形而无损心，有旦宅而无情死</td><td>第10段</td><td>孟孙才</td></tr><tr><td>安排而去化，乃入于寥天一</td><td>第10段</td><td>终境</td></tr><tr><td>吾师乎！赍万物而不为义</td><td>第11段</td><td>道为大宗师</td></tr><tr><td>堕肢体，黜聪明，离形去知，同于大通</td><td>第12段</td><td>坐忘</td></tr><tr><td>丘也请从而后也</td><td>第12段</td><td>孔子向颜回学习</td></tr><tr><td>求其为之者而不得也！然而至此极者，命也夫</td><td>第13段</td><td>命</td></tr></tbody></table><h3 id="一句话读懂《大宗师》" tabindex="-1">一句话读懂《大宗师》 <a class="header-anchor" href="#一句话读懂《大宗师》" aria-label="Permalink to &quot;一句话读懂《大宗师》&quot;">​</a></h3><blockquote><p><strong>安排而去化，乃入于寥天一。</strong></p></blockquote><p><strong>安排</strong>——安然顺应，不执着于任何状态；<strong>去化</strong>——随化而去，不抗拒任何变化；<strong>乃入于寥天一</strong>——于是进入那个空旷无际、与天道合一的境界。这不是消极，不是放弃，不是冷漠——而是在彻底的顺应中，找到那个最深的自由。</p><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li>《庄子·内篇·大宗师》</li></ul>`,39))])}}});export{O as __pageData,U as default};
